"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface MarqueeProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Seconds per loop. Default 30. */
  speed?: number;
  direction?: "left" | "right";
  ref?: React.Ref<HTMLDivElement>;
}

export function Marquee({
  speed = 30,
  direction = "left",
  className,
  children,
  ref,
  ...rest
}: MarqueeProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const trackRef = React.useRef<HTMLDivElement>(null);
  const tweenRef = React.useRef<gsap.core.Tween | null>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  useGSAP(
    () => {
      const track = trackRef.current;
      if (!track || reduced) return;
      tweenRef.current = gsap.to(track, {
        xPercent: direction === "left" ? -50 : 50,
        ease: "none",
        duration: speed,
        repeat: -1,
      });
      return () => {
        tweenRef.current = null;
      };
    },
    { dependencies: [speed, direction, reduced], scope: rootRef }
  );

  // Hover eases the loop to a stop via timeScale (not an abrupt pause).
  const onEnter = () => {
    if (tweenRef.current) {
      gsap.to(tweenRef.current, { timeScale: 0, duration: 0.4 });
    }
  };
  const onLeave = () => {
    if (tweenRef.current) {
      gsap.to(tweenRef.current, { timeScale: 1, duration: 0.4 });
    }
  };

  return (
    <div
      ref={rootRef}
      data-slot="marquee"
      onPointerEnter={onEnter}
      onPointerLeave={onLeave}
      className={cn(
        "w-full overflow-hidden",
        "[mask-image:linear-gradient(to_right,transparent,black_10%,black_90%,transparent)]",
        className
      )}
      {...rest}
    >
      <div
        ref={trackRef}
        data-slot="track"
        className="flex w-max items-center gap-12 pr-12"
      >
        {/* duplicated 2x for a seamless -50% loop */}
        <div aria-hidden={false} className="flex shrink-0 items-center gap-12">
          {children}
        </div>
        <div aria-hidden="true" className="flex shrink-0 items-center gap-12">
          {children}
        </div>
      </div>
    </div>
  );
}

registry/default/motion/text-roll-link.t:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface TextRollLinkProps
  extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  label: string;
  ref?: React.Ref<HTMLAnchorElement>;
}

export function TextRollLink({
  label,
  className,
  ref,
  ...rest
}: TextRollLinkProps) {
  const rootRef = React.useRef<HTMLAnchorElement>(null);
  const underlineRef = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLAnchorElement);

  const chars = React.useMemo(() => Array.from(label), [label]);

  useGSAP(
    () => {
      const root = rootRef.current;
      const underline = underlineRef.current;
      if (!root || !underline || reduced) return;

      const stacks = gsap.utils.toArray<HTMLElement>(
        root.querySelectorAll('[data-slot="char-stack"]')
      );
      gsap.set(underline, { scaleX: 0, transformOrigin: "left" });

      const enter = () => {
        gsap.to(stacks, {
          yPercent: -100,
          duration: 0.35,
          ease: "power3.inOut",
          stagger: 0.015,
          overwrite: true,
        });
        gsap.to(underline, {
          scaleX: 1,
          transformOrigin: "left",
          duration: 0.3,
          ease: "power3.out",
          overwrite: true,
        });
      };
      const leave = () => {
        gsap.to(stacks, {
          yPercent: 0,
          duration: 0.35,
          ease: "power3.inOut",
          stagger: 0.015,
          overwrite: true,
        });
        gsap.to(underline, {
          scaleX: 0,
          transformOrigin: "right",
          duration: 0.3,
          ease: "power3.out",
          overwrite: true,
        });
      };

      root.addEventListener("pointerenter", enter);
      root.addEventListener("pointerleave", leave);
      root.addEventListener("focus", enter);
      root.addEventListener("blur", leave);
      return () => {
        root.removeEventListener("pointerenter", enter);
        root.removeEventListener("pointerleave", leave);
        root.removeEventListener("focus", enter);
        root.removeEventListener("blur", leave);
      };
    },
    { dependencies: [label, reduced], scope: rootRef }
  );

  return (
    <a
      ref={rootRef}
      data-slot="text-roll-link"
      aria-label={label}
      className={cn(
        "relative inline-block pb-0.5 text-sm font-medium text-foreground",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-sm",
        className
      )}
      {...rest}
    >
      <span aria-hidden="true" className="flex">
        {chars.map((char, i) => (
          <span
            key={i}
            className="inline-block h-[1.2em] overflow-hidden leading-[1.2em]"
          >
            <span data-slot="char-stack" className="flex flex-col">
              <span className="block whitespace-pre">{char}</span>
              <span className="block whitespace-pre">{char}</span>
            </span>
          </span>
        ))}
      </span>
      <span
        ref={underlineRef}
        data-slot="underline"
        aria-hidden="true"
        className="absolute bottom-0 left-0 h-px w-full bg-foreground"
      />
    </a>
  );
}

registry/default/motion/scroll-reveal-gr:
"use client";

import * as React from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

gsap.registerPlugin(ScrollTrigger);

export interface ScrollRevealGridProps
  extends React.HTMLAttributes<HTMLDivElement> {
  ref?: React.Ref<HTMLDivElement>;
}

/**
 * Wrapper grid: direct children rise-in on scroll with a grid-aware stagger.
 */
export function ScrollRevealGrid({
  className,
  children,
  ref,
  ...rest
}: ScrollRevealGridProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const cards = gsap.utils.toArray<HTMLElement>(
        Array.from(root.children) as HTMLElement[]
      );
      if (!cards.length) return;
      if (reduced) {
        gsap.set(cards, { y: 0, opacity: 1 });
        return;
      }
      gsap.set(cards, { y: 12, opacity: 0 });
      gsap.to(cards, {
        y: 0,
        opacity: 1,
        duration: 0.35,
        ease: "power2.out",
        stagger: { each: 0.08, grid: "auto", from: "start" },
        scrollTrigger: {
          trigger: root,
          start: "top 80%",
          once: true,
        },
      });
    },
    { dependencies: [reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="scroll-reveal-grid"
      className={cn("grid gap-4 sm:grid-cols-2 lg:grid-cols-3", className)}
      {...rest}
    >
      {children}
    </div>
  );
}

registry/default/motion/pixel-reveal-tex:
"use client";

/**
 * PixelRevealText — text that resolves out of a dithered bitmap signal.
 *
 * Two coordinated layers, never more:
 *
 *   Layer 1  Real semantic DOM text. Present from the first byte, selectable,
 *            announced by screen readers immediately, and the thing that
 *            establishes the box. If JS never runs, this is all you get — and
 *            it is correct.
 *   Layer 2  One `aria-hidden` canvas pinned over that text, drawing an ordered-
 *            dither reconstruction of the same glyphs on a fixed pixel grid,
 *            then handing off and disappearing.
 *
 * There is no third layer and there are no per-pixel DOM nodes: a 6xl headline
 * is a few thousand grid cells painted as ~48 filled paths per frame.
 */

import * as React from "react";
import {
  AnimatePresence,
  animate,
  motion,
  useInView,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import {
  GeistPixelSquare,
  GeistPixelGrid,
  GeistPixelCircle,
  GeistPixelTriangle,
  GeistPixelLine,
} from "geist/font/pixel";
import { cn } from "@/lib/utils";
import {
  clamp,
  EASE_LOCK,
  EASE_PHASE_BEZIER,
  PHASE,
  type RevealDirection,
} from "@/registry/default/lib/pixel-dither";
import {
  usePixelTextRenderer,
  type PixelVariant,
} from "@/registry/default/lib/use-pixel-text-renderer";

export type { RevealDirection, PixelVariant };

export type PixelRevealStatus = "idle" | "revealing" | "resolved" | "dissolving";

export type PixelRevealTextProps = {
  children: string;
  as?: "span" | "p" | "div" | "h1" | "h2" | "h3" | "h4";
  variant?: PixelVariant;
  trigger?: "mount" | "in-view" | "hover" | "manual";
  direction?: RevealDirection;

  /** Total sequence length in ms. Phases scale proportionally. */
  duration?: number;
  delay?: number;
  /** Grid cell size in CSS pixels. */
  pixelSize?: number;
  /** Ignore `pixelSize` and derive it from the font size: clamp(2, fs/18, 5). */
  autoPixelSize?: boolean;
  /** How present the unresolved dither field is, 0–1. */
  intensity?: number;
  /** Flicker amplitude, 0–1. */
  flicker?: number;
  /** Same seed ⇒ same pixel pattern, every replay, every machine. */
  seed?: number;

  once?: boolean;
  /** In-view trigger: fraction of the element that must be visible. */
  threshold?: number;
  /** Change to reset and replay. */
  replayKey?: string | number;

  className?: string;
  canvasClassName?: string;

  /** `trigger="manual"` only. */
  playing?: boolean;
  /** Run the reversed exit dissolve. */
  exit?: boolean;
  exitDuration?: number;

  /** Colour of pixels that have not resolved yet. Defaults to the text colour. */
  signalColor?: string;
  /** Colour of peripheral noise pixels. Defaults to `signalColor`. */
  noiseColor?: string;

  onStart?: () => void;
  onComplete?: () => void;
  onExitComplete?: () => void;
};

const PIXEL_FONTS = {
  square: GeistPixelSquare,
  grid: GeistPixelGrid,
  circle: GeistPixelCircle,
  triangle: GeistPixelTriangle,
  line: GeistPixelLine,
} as const;

const MOTION_TAGS = {
  span: motion.span,
  p: motion.p,
  div: motion.div,
  h1: motion.h1,
  h2: motion.h2,
  h3: motion.h3,
  h4: motion.h4,
} as const;

/** Old text dissolves over this before the new value is measured. */
const DISSOLVE_MS = 280;
/** Crossfade used to hand the frame between DOM text and canvas. */
const SWAP_S = 0.06;
/** Hover re-entry is ignored inside this window. */
const HOVER_COOLDOWN_MS = 420;

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

export function PixelRevealText({
  children,
  as = "span",
  variant = "square",
  trigger = "in-view",
  direction = "left",
  duration = 1100,
  delay = 0,
  pixelSize = 3,
  autoPixelSize = false,
  intensity = 0.75,
  flicker = 0.32,
  seed = 24,
  once = true,
  threshold = 0.35,
  replayKey,
  className,
  canvasClassName,
  playing,
  exit = false,
  exitDuration = 460,
  signalColor,
  noiseColor,
  onStart,
  onComplete,
  onExitComplete,
}: PixelRevealTextProps) {
  const prefersReduced = useReducedMotion();
  const reduced = !!prefersReduced;

  const [rendered, setRendered] = React.useState(children);
  const [status, setStatus] = React.useState<PixelRevealStatus>("idle");
  const [pin, setPin] = React.useState<{ w: number; h: number } | null>(null);

  const canvasOpacity = useMotionValue(0);
  const textOpacity = useMotionValue(1);
  const pulse = useMotionValue(1);

  const statusRef = React.useRef<PixelRevealStatus>("idle");
  const playedRef = React.useRef(false);
  const wantsPlayRef = React.useRef(false);
  const pendingTextRef = React.useRef<string | null>(null);
  const pendingRevealRef = React.useRef<number | null>(null);
  const hoverCooldownRef = React.useRef(0);
  const handoffRef = React.useRef(0.12);
  const durationRef = React.useRef(duration);
  durationRef.current = duration;

  const cb = React.useRef({ onStart, onComplete, onExitComplete });
  cb.current = { onStart, onComplete, onExitComplete };

  const setStatusBoth = React.useCallback((next: PixelRevealStatus) => {
    statusRef.current = next;
    setStatus(next);
  }, []);

  const renderer = usePixelTextRenderer({
    text: rendered,
    variant,
    direction,
    pixelSize,
    autoPixelSize,
    intensity,
    flicker,
    seed,
    signalColor,
    noiseColor,
    enabled: !reduced,
    onStart: () => cb.current.onStart?.(),
    onLock: () => {
      // Phase 4. One extremely subtle scale pulse as the signal locks — no
      // glow, no overshoot, over in 120ms.
      animate(pulse, [1, 1.008, 1], { duration: 0.12, ease: EASE_LOCK });
    },
    onHandoff: () => {
      // Phase 5. Canvas out, DOM text in, both perfectly aligned.
      const d = handoffRef.current;
      animate(canvasOpacity, 0, { duration: d, ease: EASE_PHASE_BEZIER });
      animate(textOpacity, 1, { duration: d, ease: EASE_PHASE_BEZIER });
    },
    onComplete: () => {
      canvasOpacity.set(0);
      textOpacity.set(1);
      setPin(null);
      setStatusBoth("resolved");
      cb.current.onComplete?.();
    },
    onDissolved: () => {
      const next = pendingTextRef.current;
      pendingTextRef.current = null;
      canvasOpacity.set(0);
      if (next === null) {
        // A plain exit: leave the signal off.
        textOpacity.set(0);
        playedRef.current = false;
        setStatusBoth("idle");
        cb.current.onExitComplete?.();
        return;
      }
      // Text swap. The entrance is shortened, per the spec's 700–850ms window.
      pendingRevealRef.current = clamp(durationRef.current * 0.72, 700, 850);
      setRendered(next);
    },
    onMicroEnd: () => {
      animate(canvasOpacity, 0, { duration: 0.07 });
      animate(textOpacity, 1, { duration: 0.07 });
    },
  });

  const { wrapperRef, textRef, canvasRef, ready } = renderer;
  const apiRef = React.useRef(renderer);
  apiRef.current = renderer;

  const inView = useInView(wrapperRef as React.RefObject<Element>, {
    amount: clamp(threshold, 0, 1),
  });

  const shouldPlay =
    trigger === "mount"
      ? true
      : trigger === "in-view"
        ? inView
        : trigger === "manual"
          ? playing === true
          : false;
  const shouldPlayRef = React.useRef(shouldPlay);
  shouldPlayRef.current = shouldPlay;

  const runReveal = React.useCallback(
    (dur: number, delayMs: number) => {
      handoffRef.current = (dur * (1 - PHASE.lock)) / 1000;
      pulse.set(1);
      textOpacity.set(0);
      canvasOpacity.set(1);
      setPin(null);
      setStatusBoth("revealing");
      apiRef.current.play(dur, delayMs);
    },
    [canvasOpacity, pulse, setStatusBoth, textOpacity]
  );

  const tryStart = React.useCallback(() => {
    if (!wantsPlayRef.current) return;
    if (!apiRef.current.ready) return;
    wantsPlayRef.current = false;
    playedRef.current = true;
    runReveal(durationRef.current, delay);
  }, [delay, runReveal]);

  /* ---- pre-reveal state ------------------------------------------------ */

  // Server markup ships the text at full opacity so a JS failure still leaves
  // readable text. Hiding it happens before paint, so there is no flash.
  useIsomorphicLayoutEffect(() => {
    if (reduced) {
      textOpacity.set(1);
      canvasOpacity.set(0);
      return;
    }
    if (statusRef.current === "idle" && !playedRef.current) textOpacity.set(0);
  }, [reduced, canvasOpacity, textOpacity]);

  /* ---- triggers -------------------------------------------------------- */

  React.useEffect(() => {
    if (reduced) {
      // No canvas, no flicker: the text is simply there.
      if (shouldPlay && !(once && playedRef.current)) {
        playedRef.current = true;
        setStatusBoth("resolved");
        cb.current.onStart?.();
        cb.current.onComplete?.();
      }
      return;
    }
    if (!shouldPlay) return;
    if (once && playedRef.current) return;
    if (statusRef.current === "revealing" || statusRef.current === "dissolving")
      return;
    wantsPlayRef.current = true;
    tryStart();
  }, [shouldPlay, reduced, once, setStatusBoth, tryStart]);

  // The mask is measured asynchronously; start as soon as it lands.
  React.useEffect(() => {
    if (ready) tryStart();
  }, [ready, tryStart]);

  // If the renderer never becomes ready (no canvas, zero-size box), do not
  // strand the text at opacity 0.
  React.useEffect(() => {
    if (reduced || !wantsPlayRef.current) return;
    const id = setTimeout(() => {
      if (wantsPlayRef.current && !apiRef.current.ready) {
        wantsPlayRef.current = false;
        playedRef.current = true;
        textOpacity.set(1);
        setStatusBoth("resolved");
      }
    }, 1500);
    return () => clearTimeout(id);
  }, [reduced, shouldPlay, setStatusBoth, textOpacity]);

  /* ---- replay ---------------------------------------------------------- */

  const firstReplayRef = React.useRef(true);
  React.useEffect(() => {
    if (firstReplayRef.current) {
      firstReplayRef.current = false;
      return;
    }
    apiRef.current.stop();
    apiRef.current.clear();
    pendingTextRef.current = null;
    pendingRevealRef.current = null;
    playedRef.current = false;
    pulse.set(1);
    setStatusBoth("idle");
    if (reduced) {
      textOpacity.set(1);
      return;
    }
    textOpacity.set(0);
    canvasOpacity.set(0);
    wantsPlayRef.current =
      trigger === "hover" ? true : shouldPlayRef.current;
    tryStart();
    // Deliberately keyed on replayKey alone: this is an imperative reset.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [replayKey]);

  /* ---- text change ----------------------------------------------------- */

  const prevTextRef = React.useRef(children);
  React.useEffect(() => {
    if (children === prevTextRef.current) return;
    prevTextRef.current = children;

    if (reduced || !playedRef.current || !apiRef.current.ready) {
      setRendered(children);
      return;
    }

    // Hold the old box so the surrounding layout cannot jump during the swap.
    const w = wrapperRef.current;
    if (w) setPin({ w: w.offsetWidth, h: w.offsetHeight });

    pendingTextRef.current = children;
    setStatusBoth("dissolving");
    // Keep the old text visible while the canvas takes over the frame, then
    // dither it apart rather than fading it out.
    animate(textOpacity, 0, { duration: SWAP_S });
    animate(canvasOpacity, 1, { duration: SWAP_S });
    apiRef.current.dissolve(DISSOLVE_MS);
  }, [children, reduced, setStatusBoth, canvasOpacity, textOpacity, wrapperRef]);

  // After the swap the new mask needs one frame to measure; two rAFs keeps the
  // gap under the 40ms budget.
  React.useEffect(() => {
    const dur = pendingRevealRef.current;
    if (dur == null) return;
    pendingRevealRef.current = null;
    let inner = 0;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => runReveal(dur, 0));
    });
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [rendered, runReveal]);

  /* ---- optional exit --------------------------------------------------- */

  const prevExitRef = React.useRef(exit);
  React.useEffect(() => {
    if (exit === prevExitRef.current) return;
    prevExitRef.current = exit;
    if (!exit) return;
    if (reduced) {
      textOpacity.set(0);
      playedRef.current = false;
      setStatusBoth("idle");
      cb.current.onExitComplete?.();
      return;
    }
    if (statusRef.current !== "resolved" || !apiRef.current.ready) return;
    pendingTextRef.current = null;
    setStatusBoth("dissolving");
    animate(textOpacity, 0, { duration: SWAP_S });
    animate(canvasOpacity, 1, { duration: SWAP_S });
    apiRef.current.dissolve(clamp(exitDuration, 400, 550));
  }, [exit, exitDuration, reduced, setStatusBoth, canvasOpacity, textOpacity]);

  /* ---- hover ----------------------------------------------------------- */

  const handlePointerEnter = React.useCallback(() => {
    if (reduced) return;
    const now = performance.now();
    if (now < hoverCooldownRef.current) return;

    if (!playedRef.current) {
      hoverCooldownRef.current = now + durationRef.current;
      wantsPlayRef.current = true;
      tryStart();
      return;
    }
    // Already resolved: a restrained micro-flicker, never a replay.
    if (statusRef.current !== "resolved" || apiRef.current.isRunning()) return;
    hoverCooldownRef.current = now + HOVER_COOLDOWN_MS;
    animate(textOpacity, 0, { duration: 0.05 });
    animate(canvasOpacity, 1, { duration: 0.05 });
    apiRef.current.microFlicker(220);
  }, [canvasOpacity, reduced, textOpacity, tryStart]);

  React.useEffect(
    () => () => {
      apiRef.current.stop();
    },
    []
  );

  const Tag = MOTION_TAGS[as];
  const fontClass = PIXEL_FONTS[variant].className;

  return (
    <Tag
      ref={wrapperRef as React.Ref<never>}
      data-slot="pixel-reveal-text"
      data-status={status}
      className={cn(
        "pixel-reveal-wrapper relative",
        as === "span" && "inline-block",
        fontClass,
        className
      )}
      style={{
        scale: pulse,
        ...(pin ? { minWidth: pin.w, minHeight: pin.h } : null),
      }}
      onPointerEnter={trigger === "hover" ? handlePointerEnter : undefined}
    >
      {/* Layer 1 — the real text. Always in the document, always announced. */}
      <AnimatePresence mode="wait" initial={false}>
        <motion.span
          key={rendered}
          ref={textRef as React.Ref<never>}
          className="pixel-reveal-text"
          style={{ opacity: textOpacity }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0 }}
        >
          {rendered}
        </motion.span>
      </AnimatePresence>

      {/* Layer 2 — the pixel signal. Not rendered at all under reduced motion. */}
      {reduced ? null : (
        <motion.canvas
          ref={canvasRef as React.Ref<never>}
          aria-hidden="true"
          className={cn(
            "pixel-reveal-canvas pointer-events-none absolute left-0 top-0 select-none [image-rendering:pixelated]",
            canvasClassName
          )}
          style={{ opacity: canvasOpacity }}
        />
      )}
    </Tag>
  );
}

registry/default/lib/pixel-dither.ts:
/**
 * pixel-dither — the deterministic maths behind PixelRevealText.
 *
 * Nothing in here touches the DOM. It turns a coverage map (how much glyph ink
 * falls inside each grid cell) into a *reveal order*: a rank-normalised value
 * per cell that says when that cell earns the right to be drawn.
 *
 * Two properties matter and both are load-bearing:
 *
 * 1. Determinism. Every random number comes from an integer hash of
 *    (cell, channel, seed) — never Math.random() — so the same seed always
 *    produces the same pixel pattern, on every replay and every machine.
 * 2. Rank normalisation. Cell order is spread evenly across [0,1), so
 *    "reveal 35% of the pixels" means exactly 35% of the pixels, which is what
 *    lets the phase timeline hit its documented dither densities.
 */

export type RevealDirection =
  | "left"
  | "right"
  | "top"
  | "bottom"
  | "center"
  | "random";

/* -------------------------------------------------------------------------
 * Scalar helpers
 * ---------------------------------------------------------------------- */

export function clamp(v: number, lo: number, hi: number) {
  return v < lo ? lo : v > hi ? hi : v;
}

export function clamp01(v: number) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

export function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

export function smoothstep(edge0: number, edge1: number, x: number) {
  const t = clamp01((x - edge0) / (edge1 - edge0 || 1));
  return t * t * (3 - 2 * t);
}

/**
 * Cubic-bezier easing solver (Newton with a bisection fallback), so the
 * component can use the same curves in JS that Motion uses in CSS.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const ax = 3 * x1 - 3 * x2 + 1;
  const bx = 3 * x2 - 6 * x1;
  const cx = 3 * x1;
  const ay = 3 * y1 - 3 * y2 + 1;
  const by = 3 * y2 - 6 * y1;
  const cy = 3 * y1;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;

  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 6; i++) {
      const d = slopeX(t);
      if (Math.abs(d) < 1e-6) break;
      const err = sampleX(t) - x;
      if (Math.abs(err) < 1e-6) return sampleY(t);
      t -= err / d;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 12; i++) {
      const err = sampleX(t) - x;
      if (Math.abs(err) < 1e-6) break;
      if (err > 0) hi = t;
      else lo = t;
      t = (lo + hi) / 2;
    }
    return sampleY(t);
  };
}

/** The house phase curve. Deliberately subtle — see `phaseEase` below. */
export const EASE_PHASE = cubicBezier(0.22, 1, 0.36, 1);
/** The signal-lock pulse curve. */
export const EASE_LOCK: readonly [number, number, number, number] = [
  0.16, 1, 0.3, 1,
];
export const EASE_PHASE_BEZIER: readonly [number, number, number, number] = [
  0.22, 1, 0.36, 1,
];

/**
 * Dither *density* stays linear (see `densityAt`). Only the phase progression —
 * opacity band, flicker envelope, peripheral noise — is eased, and only by 35%
 * of the way toward the curve, or the whole effect front-loads and stops
 * feeling computational.
 */
export function phaseEase(t: number) {
  return lerp(t, EASE_PHASE(t), 0.35);
}

/* -------------------------------------------------------------------------
 * Deterministic hashing
 * ---------------------------------------------------------------------- */

/**
 * Integer hash → [0,1). Stable for a given (a, b, seed), which is what makes a
 * replay with the same seed produce the same pixel pattern.
 */
export function hash3(a: number, b: number, seed: number) {
  let h = Math.imul(a ^ 0x9e3779b9, 0x27d4eb2d);
  h = (h ^ Math.imul(b + 0x165667b1, 0x85ebca6b)) | 0;
  h = (h ^ Math.imul(seed + 0x1b873593, 0xc2b2ae35)) | 0;
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d);
  h = Math.imul(h ^ (h >>> 13), 0x297a2d39);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

/** 4×4 Bayer ordered-dither matrix, the backbone of the reveal pattern. */
export const BAYER_4 = [
  0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5,
] as const;

export function bayer4(x: number, y: number) {
  return BAYER_4[(y & 3) * 4 + (x & 3)] / 16;
}

/* -------------------------------------------------------------------------
 * The phase timeline
 *
 * Times are expressed against the 1100ms reference sequence and stored as
 * fractions, so a 700ms or 1400ms run keeps the same proportions.
 * ---------------------------------------------------------------------- */

export const REFERENCE_DURATION = 1100;

export const PHASE = {
  /** Phase 1 → 2: signal detection ends. */
  detect: 140 / REFERENCE_DURATION,
  /** Phase 2 → 3: pixel formation ends. */
  form: 430 / REFERENCE_DURATION,
  /** Phase 3 → 4: glyph resolution ends, signal lock begins. */
  resolve: 820 / REFERENCE_DURATION,
  /** Phase 4 → 5: canvas-to-DOM handoff begins. */
  lock: 980 / REFERENCE_DURATION,
  /** End of sequence. */
  end: 1,
} as const;

type Stop = readonly [number, number];

function piecewise(stops: readonly Stop[], t: number) {
  if (t <= stops[0][0]) return stops[0][1];
  const last = stops[stops.length - 1];
  if (t >= last[0]) return last[1];
  for (let i = 1; i < stops.length; i++) {
    const [x1, y1] = stops[i];
    const [x0, y0] = stops[i - 1];
    if (t <= x1) return lerp(y0, y1, (t - x0) / (x1 - x0 || 1));
  }
  return last[1];
}

/**
 * Fraction of eligible glyph cells that should be revealed at normalised time
 * `t`. Piecewise-linear by design: phase 1 lands at 8%, phase 2 at 35%,
 * phase 3 at 88%, and phase 4 snaps the remainder into place.
 */
const DENSITY_STOPS: readonly Stop[] = [
  [0, 0],
  [PHASE.detect, 0.08],
  [PHASE.form, 0.35],
  [PHASE.resolve, 0.88],
  [PHASE.lock, 1],
  [1, 1],
];

export function densityAt(t: number) {
  return piecewise(DENSITY_STOPS, t);
}

/**
 * The opacity window open at time `t`, straight from the spec's phase table.
 * Unresolved pixels ride the low end, resolved pixels the high end.
 */
const OPACITY_MIN_STOPS: readonly Stop[] = [
  [0, 0.08],
  [PHASE.detect, 0.08],
  [PHASE.form, 0.18],
  [PHASE.resolve, 0.55],
  [1, 0.55],
];
const OPACITY_MAX_STOPS: readonly Stop[] = [
  [0, 0.35],
  [PHASE.detect, 0.35],
  [PHASE.form, 0.75],
  [PHASE.resolve, 1],
  [1, 1],
];

export function opacityMinAt(t: number) {
  return piecewise(OPACITY_MIN_STOPS, t);
}

export function opacityMaxAt(t: number) {
  return piecewise(OPACITY_MAX_STOPS, t);
}

/**
 * Flicker amplitude envelope. Full strength while the signal is unresolved,
 * gone by the time the glyphs lock — "flicker frequency and amplitude
 * gradually decrease".
 */
export function flickerEnvelopeAt(t: number) {
  return 1 - smoothstep(0.42, PHASE.resolve, t);
}

/**
 * Probability that a peripheral (one-cell-outside) pixel shows up. Peaks during
 * signal detection, gone well before the lock so no stray noise survives.
 */
const HALO_STOPS: readonly Stop[] = [
  [0, 0.02],
  [0.07, 0.17],
  [0.3, 0.14],
  [0.5, 0.07],
  [0.72, 0],
  [1, 0],
];

export function haloChanceAt(t: number) {
  return piecewise(HALO_STOPS, t);
}

/** Flicker pattern updates per second. Decoupled from the rAF frame rate. */
export const FLICKER_HZ = 24;

/** How far past its threshold a cell must travel before it counts as resolved. */
export const RESOLVE_BAND = 0.22;

/* -------------------------------------------------------------------------
 * The field
 * ---------------------------------------------------------------------- */

/** Coverage at or above this counts as glyph ink. */
const INK_MIN = 0.12;

export interface PixelField {
  cols: number;
  rows: number;
  /** Active cells: glyph ink plus the one-cell halo around it. */
  count: number;
  x: Int32Array;
  y: Int32Array;
  /** 0 = glyph ink, 1 = peripheral halo. */
  kind: Uint8Array;
  /** 0 = horizontal, 1 = vertical. Used by the `line` variant only. */
  stroke: Uint8Array;
  /** Rank-normalised reveal order in [0,1). Halo cells are 2. */
  order: Float32Array;
  /** Direction-free order, used by dissolve and exit passes. */
  scatter: Float32Array;
  glyphCount: number;
}

export interface BuildFieldOptions {
  cols: number;
  rows: number;
  /** Per-cell glyph coverage in [0,1], row-major. */
  coverage: Float32Array;
  direction: RevealDirection;
  seed: number;
}

function directionTerm(
  direction: RevealDirection,
  x: number,
  y: number,
  cols: number,
  rows: number
) {
  const u = cols > 1 ? x / (cols - 1) : 0;
  const v = rows > 1 ? y / (rows - 1) : 0;
  switch (direction) {
    case "left":
      return u;
    case "right":
      return 1 - u;
    case "top":
      return v;
    case "bottom":
      return 1 - v;
    case "center": {
      // Headlines are wide and short; weighting y down keeps the front reading
      // as an outward expansion rather than a vertical band.
      const dx = (u - 0.5) * 2;
      const dy = (v - 0.5) * 2 * 0.55;
      return clamp01(Math.hypot(dx, dy) / 1.1414);
    }
    default:
      return 0;
  }
}

const RANK_BINS = 4096;

/**
 * Histogram rank-normalisation: O(n), no sort. Scores land uniformly in [0,1)
 * so `order < density` reveals exactly `density` of the eligible cells. Cells
 * inside a bin are separated by their sub-bin position, so ties don't pop
 * together in visible clumps.
 */
function rankNormalise(
  score: Float32Array,
  eligible: Uint8Array,
  n: number,
  out: Float32Array
) {
  const bins = new Uint32Array(RANK_BINS);
  for (let i = 0; i < n; i++) {
    if (!eligible[i]) continue;
    const b = Math.min(RANK_BINS - 1, (score[i] * RANK_BINS) | 0);
    bins[b]++;
  }
  const start = new Uint32Array(RANK_BINS);
  let acc = 0;
  for (let b = 0; b < RANK_BINS; b++) {
    start[b] = acc;
    acc += bins[b];
  }
  const total = acc || 1;
  for (let i = 0; i < n; i++) {
    if (!eligible[i]) {
      out[i] = 2;
      continue;
    }
    const s = score[i] * RANK_BINS;
    const b = Math.min(RANK_BINS - 1, s | 0);
    out[i] = (start[b] + (s - b) * bins[b]) / total;
  }
}

export function buildField({
  cols,
  rows,
  coverage,
  direction,
  seed,
}: BuildFieldOptions): PixelField {
  const n = cols * rows;
  const ink = new Uint8Array(n);
  let glyphCount = 0;
  for (let i = 0; i < n; i++) {
    if (coverage[i] >= INK_MIN) {
      ink[i] = 1;
      glyphCount++;
    }
  }

  // A halo cell is empty but sits one grid step outside the silhouette. These
  // are the pixels that "occasionally appear outside the glyph" early on.
  const halo = new Uint8Array(n);
  for (let cy = 0; cy < rows; cy++) {
    for (let cx = 0; cx < cols; cx++) {
      const i = cy * cols + cx;
      if (ink[i]) continue;
      let touching = false;
      for (let dy = -1; dy <= 1 && !touching; dy++) {
        const ny = cy + dy;
        if (ny < 0 || ny >= rows) continue;
        for (let dx = -1; dx <= 1; dx++) {
          const nx = cx + dx;
          if (nx < 0 || nx >= cols) continue;
          if (ink[ny * cols + nx]) {
            touching = true;
            break;
          }
        }
      }
      if (touching) halo[i] = 1;
    }
  }

  // Weights. The directional term dominates so the front reads clearly; the
  // Bayer matrix and the seeded noise are what make its edge irregular, and the
  // coverage term pulls glyph cores in ahead of anti-aliased boundary cells.
  const W =
    direction === "random"
      ? { dir: 0, dither: 0.42, cover: 0.14, rand: 0.44, jitter: 0 }
      : { dir: 1, dither: 0.4, cover: 0.16, rand: 0.12, jitter: 0.24 };
  const wSum = W.dir + W.dither + W.cover + W.rand;

  const scoreOrder = new Float32Array(n);
  const scoreScatter = new Float32Array(n);
  for (let cy = 0; cy < rows; cy++) {
    for (let cx = 0; cx < cols; cx++) {
      const i = cy * cols + cx;
      if (!ink[i]) continue;
      const r1 = hash3(cx, cy, seed);
      const r2 = hash3(cx, cy, seed + 101);
      const r3 = hash3(cx, cy, seed + 977);
      const bayer = bayer4(cx, cy);
      const cov = coverage[i];
      // 10–20% of cells resolve ahead of or behind the front.
      const dj = clamp01(
        directionTerm(direction, cx, cy, cols, rows) + (r1 - 0.5) * W.jitter
      );
      scoreOrder[i] = clamp01(
        (W.dir * dj + W.dither * bayer + W.cover * (1 - cov) + W.rand * r2) /
          wSum
      );
      // Dissolve order: direction-free, biased so isolated / low-coverage
      // cells are the first to drop out.
      scoreScatter[i] = clamp01(
        0.34 * bayer + 0.46 * r3 + 0.2 * (1 - cov)
      );
    }
  }

  const order = new Float32Array(n);
  const scatter = new Float32Array(n);
  rankNormalise(scoreOrder, ink, n, order);
  rankNormalise(scoreScatter, ink, n, scatter);

  // Pack the active cells into flat arrays so the render loop never walks the
  // empty majority of the grid.
  let count = 0;
  for (let i = 0; i < n; i++) if (ink[i] || halo[i]) count++;

  const xs = new Int32Array(count);
  const ys = new Int32Array(count);
  const kind = new Uint8Array(count);
  const stroke = new Uint8Array(count);
  const aOrder = new Float32Array(count);
  const aScatter = new Float32Array(count);

  let k = 0;
  for (let cy = 0; cy < rows; cy++) {
    for (let cx = 0; cx < cols; cx++) {
      const i = cy * cols + cx;
      if (!ink[i] && !halo[i]) continue;
      xs[k] = cx;
      ys[k] = cy;
      kind[k] = ink[i] ? 0 : 1;
      aOrder[k] = ink[i] ? order[i] : 2;
      aScatter[k] = ink[i] ? scatter[i] : 2;
      // Rectilinear stroke orientation for the `line` variant: follow the run
      // the cell belongs to.
      const up = cy > 0 && ink[i - cols];
      const down = cy < rows - 1 && ink[i + cols];
      const left = cx > 0 && ink[i - 1];
      const right = cx < cols - 1 && ink[i + 1];
      stroke[k] = up && down && !(left && right) ? 1 : 0;
      k++;
    }
  }

  return {
    cols,
    rows,
    count,
    x: xs,
    y: ys,
    kind,
    stroke,
    order: aOrder,
    scatter: aScatter,
    glyphCount,
  };
}

registry/default/lib/use-pixel-text-rend:
"use client";

/**
 * use-pixel-text-renderer — everything PixelRevealText knows about the DOM,
 * the glyph mask and the canvas.
 *
 * The hook owns three things React never sees:
 *
 * 1. Measurement. It reads the real DOM text's computed typography and the
 *    per-character client rects, so the canvas is a redraw of the *actual*
 *    laid-out text: wrapping, alignment, letter-spacing and text-transform
 *    included. Nothing is re-implemented, so nothing can drift.
 * 2. The mask. Text is drawn once to an offscreen canvas and reduced to a
 *    per-cell coverage map, then handed to `buildField` for its reveal order.
 *    Cached until the text, typography or box changes.
 * 3. The loop. A single requestAnimationFrame driver that writes pixels and
 *    never touches React state, stops the moment a pass completes, and pauses
 *    while the document is hidden.
 */

import * as React from "react";
import {
  buildField,
  clamp,
  clamp01,
  densityAt,
  FLICKER_HZ,
  flickerEnvelopeAt,
  haloChanceAt,
  hash3,
  lerp,
  opacityMaxAt,
  opacityMinAt,
  PHASE,
  phaseEase,
  RESOLVE_BAND,
  type PixelField,
  type RevealDirection,
} from "./pixel-dither";

export type PixelVariant = "square" | "grid" | "circle" | "triangle" | "line";

export interface UsePixelTextRendererOptions {
  /** The exact string currently rendered in the DOM text layer. */
  text: string;
  variant: PixelVariant;
  direction: RevealDirection;
  /** Cell size in CSS pixels. */
  pixelSize: number;
  /** Derive pixelSize from the measured font size instead: clamp(2, fs/18, 5). */
  autoPixelSize?: boolean;
  intensity: number;
  flicker: number;
  seed: number;
  signalColor?: string;
  noiseColor?: string;
  /** When false the hook does no measuring, no masking and no drawing at all. */
  enabled: boolean;
  onReady?: (ready: boolean) => void;
  onStart?: () => void;
  /** Fires at the phase-4 boundary so the caller can run the lock pulse. */
  onLock?: () => void;
  /** Fires at the phase-5 boundary so the caller can crossfade to DOM text. */
  onHandoff?: () => void;
  onComplete?: () => void;
  onDissolved?: () => void;
  onMicroEnd?: () => void;
}

type Pass = "in" | "out" | "micro";

export interface PixelTextRenderer {
  wrapperRef: React.RefObject<HTMLElement | null>;
  textRef: React.RefObject<HTMLElement | null>;
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
  /** True once the glyph mask has been measured and is safe to animate. */
  ready: boolean;
  /** Play the full reveal. `delay` is in milliseconds. */
  play: (duration: number, delay?: number) => void;
  /** Reverse-dither the resolved text away. Used for text swaps and exits. */
  dissolve: (duration: number) => void;
  /** Short restrained flicker across a few percent of the resolved glyph. */
  microFlicker: (duration?: number) => void;
  /** Draw nothing. */
  clear: () => void;
  /** Stop the loop and drop any pending delayed start. */
  stop: () => void;
  /** True while a pass is running. Read from a ref — never triggers a render. */
  isRunning: () => boolean;
}

interface Geometry {
  left: number;
  top: number;
  /** CSS-pixel size of the canvas box. */
  width: number;
  height: number;
  /** Device-pixel size of the canvas backing store. */
  deviceWidth: number;
  deviceHeight: number;
  cell: number;
  cols: number;
  rows: number;
  dpr: number;
  /** Device-pixel column/row edges. Integers, so cells tile without seams. */
  xs: Int32Array;
  ys: Int32Array;
}

interface RunState {
  pass: Pass;
  start: number;
  duration: number;
  pausedTotal: number;
  hiddenAt: number;
  lastTick: number;
  lastDensity: number;
  lockFired: boolean;
  handoffFired: boolean;
}

const ALPHA_BUCKETS = 16;
const COLOR_GROUPS = 3; // 0 resolved, 1 forming/signal, 2 peripheral noise
const TOTAL_BUCKETS = ALPHA_BUCKETS * COLOR_GROUPS;
const HIDDEN = 255;

/** Hard ceiling on grid cells. Guards a huge paragraph from a huge mask. */
const MAX_CELLS = 260_000;

function applyTextTransform(raw: string, transform: string) {
  switch (transform) {
    case "uppercase":
      return raw.toUpperCase();
    case "lowercase":
      return raw.toLowerCase();
    case "capitalize":
      return raw.replace(/(^|\s)(\S)/g, (_m, a: string, b: string) => a + b.toUpperCase());
    default:
      return raw;
  }
}

export function usePixelTextRenderer(
  options: UsePixelTextRendererOptions
): PixelTextRenderer {
  const {
    text,
    variant,
    direction,
    pixelSize,
    autoPixelSize = false,
    intensity,
    flicker,
    seed,
    enabled,
  } = options;

  const wrapperRef = React.useRef<HTMLElement | null>(null);
  const textRef = React.useRef<HTMLElement | null>(null);
  const canvasRef = React.useRef<HTMLCanvasElement | null>(null);

  const [ready, setReady] = React.useState(false);

  // Everything below lives in refs: the render loop must never cause a React
  // render, and changing a callback must never restart the loop.
  const cbRef = React.useRef(options);
  cbRef.current = options;

  const fieldRef = React.useRef<PixelField | null>(null);
  const geomRef = React.useRef<Geometry | null>(null);
  const ctxRef = React.useRef<CanvasRenderingContext2D | null>(null);
  const colorsRef = React.useRef<[string, string, string]>([
    "#000",
    "#000",
    "#000",
  ]);
  const runRef = React.useRef<RunState | null>(null);
  const rafRef = React.useRef(0);
  const delayTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const measureTokenRef = React.useRef(0);

  // Scratch buffers for the per-frame counting sort. Grown only when the
  // active-cell count grows.
  const bucketOfRef = React.useRef<Uint8Array>(new Uint8Array(0));
  const sortedRef = React.useRef<Int32Array>(new Int32Array(0));
  const countsRef = React.useRef(new Int32Array(TOTAL_BUCKETS));
  const startsRef = React.useRef(new Int32Array(TOTAL_BUCKETS));
  const cursorRef = React.useRef(new Int32Array(TOTAL_BUCKETS));

  const readyRef = React.useRef(false);
  const setReadySafe = React.useCallback((v: boolean) => {
    if (readyRef.current === v) return;
    readyRef.current = v;
    setReady(v);
    cbRef.current.onReady?.(v);
  }, []);

  /* ---------------------------------------------------------------------
   * Painting
   * ------------------------------------------------------------------ */

  const addShape = React.useCallback(
    (
      ctx: CanvasRenderingContext2D,
      geom: Geometry,
      field: PixelField,
      k: number
    ) => {
      const cx = field.x[k];
      const cy = field.y[k];
      const x0 = geom.xs[cx];
      const y0 = geom.ys[cy];
      const w = geom.xs[cx + 1] - x0;
      const h = geom.ys[cy + 1] - y0;
      if (w <= 0 || h <= 0) return;

      switch (variant) {
        case "grid": {
          // Grid exposes a lattice gap, but never below one device pixel of ink.
          const gap = w >= 4 ? Math.max(1, Math.round(w * 0.22)) : 0;
          ctx.rect(x0, y0, Math.max(1, w - gap), Math.max(1, h - gap));
          break;
        }
        case "circle": {
          const r = Math.min(w, h) / 2;
          const mx = x0 + w / 2;
          const my = y0 + h / 2;
          ctx.moveTo(mx + r, my);
          ctx.arc(mx, my, r, 0, Math.PI * 2);
          break;
        }
        case "triangle": {
          // Alternating orientation tiles cleanly across the glyph.
          if (((cx + cy) & 1) === 1) {
            ctx.moveTo(x0, y0);
            ctx.lineTo(x0 + w, y0);
            ctx.lineTo(x0 + w / 2, y0 + h);
          } else {
            ctx.moveTo(x0 + w / 2, y0);
            ctx.lineTo(x0 + w, y0 + h);
            ctx.lineTo(x0, y0 + h);
          }
          ctx.closePath();
          break;
        }
        case "line": {
          if (field.stroke[k]) {
            const sw = Math.max(1, Math.round(w * 0.5));
            ctx.rect(x0 + ((w - sw) >> 1), y0, sw, h);
          } else {
            const sh = Math.max(1, Math.round(h * 0.5));
            ctx.rect(x0, y0 + ((h - sh) >> 1), w, sh);
          }
          break;
        }
        default:
          ctx.rect(x0, y0, w, h);
      }
    },
    [variant]
  );

  /**
   * One frame. `t` is normalised sequence time, `tick` the quantised flicker
   * clock. Cells are bucketed by colour group and quantised alpha, counting-
   * sorted, then painted as at most 48 filled paths — never one fill per pixel.
   */
  const paint = React.useCallback(
    (pass: Pass, t: number, tick: number) => {
      const ctx = ctxRef.current;
      const geom = geomRef.current;
      const field = fieldRef.current;
      if (!ctx || !geom || !field) return;

      ctx.clearRect(0, 0, geom.deviceWidth, geom.deviceHeight);
      if (field.count === 0) return;

      const bucketOf = bucketOfRef.current;
      const sorted = sortedRef.current;
      const counts = countsRef.current;
      const starts = startsRef.current;
      const cursor = cursorRef.current;
      counts.fill(0);

      const tp = phaseEase(t);
      const lo = opacityMinAt(tp);
      const hi = opacityMaxAt(tp);
      const unresolvedGain = clamp(0.55 + 0.6 * intensity, 0, 1.25);

      let density: number;
      let ampBase: number;
      let haloChance: number;
      let lockPulse = 0;

      if (pass === "in") {
        density = densityAt(t);
        ampBase = flicker * 0.42 * flickerEnvelopeAt(t);
        haloChance = haloChanceAt(t) * (0.5 + 0.7 * intensity);
        // One extremely subtle brightness lift as the signal locks. Not a glow:
        // it only pulls half-formed pixels toward the top of the band.
        if (t >= PHASE.resolve && t < PHASE.lock) {
          const u = (t - PHASE.resolve) / (PHASE.lock - PHASE.resolve);
          lockPulse = Math.sin(u * Math.PI) * 0.5;
        }
      } else if (pass === "out") {
        density = 1 - t;
        // Remaining clusters get noisier as the signal dies.
        ampBase = flicker * 0.5 * (0.35 + 0.65 * t);
        haloChance = haloChanceAt(density) * 0.6 * (0.5 + 0.7 * intensity);
      } else {
        density = 2; // fully resolved; micro-flicker only dims
        ampBase = 0;
        haloChance = 0;
      }

      // Micro-flicker: at most 8% of glyph cells dim briefly, and only dim —
      // the word stays readable throughout.
      const microChance = pass === "micro" ? 0.08 * Math.sin(t * Math.PI) : 0;
      const order = pass === "out" ? field.scatter : field.order;

      for (let k = 0; k < field.count; k++) {
        bucketOf[k] = HIDDEN;

        if (field.kind[k] === 1) {
          // Peripheral noise. Gone entirely once the glyph resolves.
          if (haloChance <= 0) continue;
          if (hash3(k, tick, seed + 5) >= haloChance) continue;
          const q = 0.15 + 0.35 * hash3(k, tick, seed + 6);
          const a = clamp01(lerp(lo, hi, q) * unresolvedGain);
          if (a <= 0.01) continue;
          bucketOf[k] = 2 * ALPHA_BUCKETS + Math.min(15, (a * 16) | 0);
          counts[bucketOf[k]]++;
          continue;
        }

        if (pass === "micro") {
          const dim = hash3(k, tick, seed + 9) < microChance;
          bucketOf[k] = dim ? ALPHA_BUCKETS + 4 : 15;
          counts[bucketOf[k]]++;
          continue;
        }

        const o = order[k];
        const res = (density - o) / RESOLVE_BAND;

        // Perturbation decays fast past the front, so resolved regions hold
        // still while the leading edge keeps churning.
        const amp = res >= 1 ? 0 : ampBase * Math.exp(-Math.max(0, res) * 2.4);
        const n = hash3(k, tick, seed + 1);
        if (density + (n - 0.5) * 2 * amp <= o) continue;

        let q: number;
        let group: number;
        if (res >= 1) {
          q = 1;
          group = 0;
        } else if (res > 0) {
          q = 0.55 + 0.45 * res;
          group = 1;
        } else {
          // The 15–65% flicker band the unresolved field lives in.
          q = 0.15 + 0.5 * hash3(k, tick, seed + 3);
          group = 1;
        }

        let a = lerp(lo, hi, q);
        if (res < 1) {
          a *= unresolvedGain;
          if (lockPulse > 0) a += (hi - a) * lockPulse;
        }
        a = clamp01(a);
        if (a <= 0.01) continue;

        bucketOf[k] = group * ALPHA_BUCKETS + Math.min(15, (a * 16) | 0);
        counts[bucketOf[k]]++;
      }

      let acc = 0;
      for (let b = 0; b < TOTAL_BUCKETS; b++) {
        starts[b] = acc;
        cursor[b] = acc;
        acc += counts[b];
      }
      if (acc === 0) return;
      for (let k = 0; k < field.count; k++) {
        const b = bucketOf[k];
        if (b === HIDDEN) continue;
        sorted[cursor[b]++] = k;
      }

      const colors = colorsRef.current;
      for (let b = 0; b < TOTAL_BUCKETS; b++) {
        const c = counts[b];
        if (c === 0) continue;
        const bi = b % ALPHA_BUCKETS;
        ctx.fillStyle = colors[(b / ALPHA_BUCKETS) | 0];
        // The top bucket paints at exactly 1, so resolved text is never a few
        // percent transparent going into the handoff.
        ctx.globalAlpha =
          bi === ALPHA_BUCKETS - 1 ? 1 : (bi + 0.5) / ALPHA_BUCKETS;
        ctx.beginPath();
        const from = starts[b];
        for (let j = from; j < from + c; j++) addShape(ctx, geom, field, sorted[j]);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    },
    [addShape, flicker, intensity, seed]
  );

  /* ---------------------------------------------------------------------
   * Measurement
   * ------------------------------------------------------------------ */

  const measure = React.useCallback(async () => {
    const token = ++measureTokenRef.current;
    const wrapper = wrapperRef.current;
    const textEl = textRef.current;
    const canvas = canvasRef.current;
    if (!wrapper || !textEl || !canvas) return;

    const node = textEl.firstChild;
    if (!node || node.nodeType !== 3) return;
    const raw = node.nodeValue ?? "";
    if (!raw.trim()) {
      setReadySafe(false);
      return;
    }

    const cs = getComputedStyle(textEl);
    const fontSize = parseFloat(cs.fontSize) || 16;
    const shorthand = `${cs.fontStyle || "normal"} ${cs.fontWeight || "400"} ${fontSize}px ${cs.fontFamily}`;

    // Never measure against a fallback face — the mask would be wrong and the
    // handoff would visibly jump.
    try {
      if (document.fonts && !document.fonts.check(shorthand, raw)) {
        await document.fonts.load(shorthand, raw);
      }
    } catch {
      /* best-effort; measure whatever is available */
    }
    if (token !== measureTokenRef.current) return;
    if (!wrapperRef.current || !textRef.current || !canvasRef.current) return;

    const transformed = applyTextTransform(raw, cs.textTransform);
    const sameLength = transformed.length === raw.length;

    // Per-character client rects. This is what keeps the canvas locked to the
    // DOM through wrapping, alignment, letter-spacing and responsive sizes.
    const range = document.createRange();
    const wrapRect = wrapper.getBoundingClientRect();

    // Client rects are post-transform. If an ancestor is mid-animation (a
    // scaling preview panel, a card entrance), divide the scale back out so the
    // mask is built in layout pixels and stays valid once the transform lands.
    const ratioX = wrapper.offsetWidth ? wrapRect.width / wrapper.offsetWidth : 1;
    const ratioY = wrapper.offsetHeight ? wrapRect.height / wrapper.offsetHeight : 1;
    const sx = Math.abs(ratioX - 1) > 0.01 && ratioX > 0.01 ? ratioX : 1;
    const sy = Math.abs(ratioY - 1) > 0.01 && ratioY > 0.01 ? ratioY : 1;

    const chars: { ch: string; x: number; y: number; h: number }[] = [];
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;

    for (let i = 0; i < raw.length; i++) {
      const ch = sameLength ? transformed[i] : raw[i];
      if (!ch || !ch.trim()) continue;
      range.setStart(node, i);
      range.setEnd(node, i + 1);
      const r = range.getBoundingClientRect();
      if (r.width === 0 && r.height === 0) continue;
      const x = (r.left - wrapRect.left) / sx;
      const y = (r.top - wrapRect.top) / sy;
      const w = r.width / sx;
      const h = r.height / sy;
      chars.push({ ch, x, y, h });
      if (x < minX) minX = x;
      if (y < minY) minY = y;
      if (x + w > maxX) maxX = x + w;
      if (y + h > maxY) maxY = y + h;
    }

    if (!chars.length || !isFinite(minX)) {
      setReadySafe(false);
      return;
    }

    // Pad the box so ascenders, descenders and the one-cell halo cannot clip.
    const pad = Math.ceil(fontSize * 0.4);
    const boxLeft = Math.floor(minX - pad);
    const boxTop = Math.floor(minY - pad);
    const rawW = Math.ceil(maxX + pad) - boxLeft;
    const rawH = Math.ceil(maxY + pad) - boxTop;
    if (rawW <= 0 || rawH <= 0) {
      setReadySafe(false);
      return;
    }

    let cell = autoPixelSize
      ? Math.round(clamp(fontSize / 18, 2, 5))
      : Math.max(1, Math.round(pixelSize));
    let cols = Math.ceil(rawW / cell);
    let rows = Math.ceil(rawH / cell);
    while (cols * rows > MAX_CELLS && cell < 24) {
      cell += 1;
      cols = Math.ceil(rawW / cell);
      rows = Math.ceil(rawH / cell);
    }
    // The grid defines the box, so every cell is whole.
    const width = cols * cell;
    const height = rows * cell;

    // --- offscreen glyph mask, sampled at CSS resolution ------------------
    const off = document.createElement("canvas");
    off.width = width;
    off.height = height;
    const octx = off.getContext("2d", { willReadFrequently: true });
    if (!octx) return;
    octx.font = shorthand;
    octx.textBaseline = "alphabetic";
    octx.textAlign = "left";
    octx.fillStyle = "#fff";
    if ("letterSpacing" in octx) {
      // Per-character positioning already carries letter-spacing; make sure the
      // context does not apply it a second time.
      (octx as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing =
        "0px";
    }

    const metrics = octx.measureText("Hxg");
    const asc =
      metrics.fontBoundingBoxAscent ??
      metrics.actualBoundingBoxAscent ??
      fontSize * 0.8;
    const desc =
      metrics.fontBoundingBoxDescent ??
      metrics.actualBoundingBoxDescent ??
      fontSize * 0.2;
    const boxH = asc + desc;

    for (const c of chars) {
      // Centre the font box inside the box the browser reported for the
      // character, then sit on the alphabetic baseline.
      octx.fillText(c.ch, c.x - boxLeft, c.y + (c.h - boxH) / 2 + asc - boxTop);
    }

    // --- coverage per cell -------------------------------------------------
    const data = octx.getImageData(0, 0, width, height).data;
    const coverage = new Float32Array(cols * rows);
    const inv = 1 / (cell * cell * 255);
    for (let cy = 0; cy < rows; cy++) {
      const rowBase = cy * cols;
      for (let py = cy * cell; py < (cy + 1) * cell; py++) {
        const lineBase = py * width * 4;
        for (let cx = 0; cx < cols; cx++) {
          let sum = 0;
          const base = lineBase + cx * cell * 4 + 3;
          for (let s = 0; s < cell; s++) sum += data[base + s * 4];
          coverage[rowBase + cx] += sum;
        }
      }
    }
    for (let i = 0; i < coverage.length; i++) coverage[i] *= inv;

    if (token !== measureTokenRef.current) return;

    const field = buildField({ cols, rows, coverage, direction, seed });

    // --- device-pixel geometry --------------------------------------------
    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const xs = new Int32Array(cols + 1);
    const ys = new Int32Array(rows + 1);
    // Rounding each *edge* (rather than an origin plus a width) keeps every
    // cell on whole device pixels and seamless: no half-pixel blur, no gaps.
    for (let i = 0; i <= cols; i++) xs[i] = Math.round(i * cell * dpr);
    for (let i = 0; i <= rows; i++) ys[i] = Math.round(i * cell * dpr);

    canvas.style.left = `${boxLeft}px`;
    canvas.style.top = `${boxTop}px`;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    canvas.width = xs[cols];
    canvas.height = ys[rows];

    const ctx = canvas.getContext("2d", { alpha: true });
    if (!ctx) return;
    ctx.imageSmoothingEnabled = false;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctxRef.current = ctx;

    geomRef.current = {
      left: boxLeft,
      top: boxTop,
      width,
      height,
      deviceWidth: xs[cols],
      deviceHeight: ys[rows],
      cell,
      cols,
      rows,
      dpr,
      xs,
      ys,
    };
    fieldRef.current = field;

    if (bucketOfRef.current.length < field.count) {
      bucketOfRef.current = new Uint8Array(field.count);
      sortedRef.current = new Int32Array(field.count);
    }

    setReadySafe(field.glyphCount > 0);
  }, [autoPixelSize, direction, pixelSize, seed, setReadySafe]);

  const refreshColors = React.useCallback(() => {
    const textEl = textRef.current;
    if (!textEl) return;
    const base = getComputedStyle(textEl).color || "#000";
    const signal = cbRef.current.signalColor || base;
    colorsRef.current = [base, signal, cbRef.current.noiseColor || signal];
  }, []);

  /* ---------------------------------------------------------------------
   * The loop
   * ------------------------------------------------------------------ */

  const clear = React.useCallback(() => {
    const ctx = ctxRef.current;
    const canvas = canvasRef.current;
    if (ctx && canvas) ctx.clearRect(0, 0, canvas.width, canvas.height);
  }, []);

  const stopLoop = React.useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = 0;
    if (delayTimerRef.current) clearTimeout(delayTimerRef.current);
    delayTimerRef.current = null;
  }, []);

  const frame = React.useCallback(
    (now: number) => {
      const run = runRef.current;
      if (!run) return;
      const elapsed = now - run.start - run.pausedTotal;
      const t = run.duration > 0 ? clamp01(elapsed / run.duration) : 1;
      const tick = Math.floor(Math.max(0, elapsed) / (1000 / FLICKER_HZ));

      if (run.pass === "in") {
        if (!run.lockFired && t >= PHASE.resolve) {
          run.lockFired = true;
          cbRef.current.onLock?.();
        }
        if (!run.handoffFired && t >= PHASE.lock) {
          run.handoffFired = true;
          cbRef.current.onHandoff?.();
        }
      }

      if (t >= 1) {
        const pass = run.pass;
        runRef.current = null;
        rafRef.current = 0;
        clear();
        if (pass === "in") cbRef.current.onComplete?.();
        else if (pass === "out") cbRef.current.onDissolved?.();
        else cbRef.current.onMicroEnd?.();
        return;
      }

      // Skip redundant repaints: the flicker pattern only moves at FLICKER_HZ,
      // and sub-percent density changes are invisible.
      const density = run.pass === "in" ? densityAt(t) : t;
      if (tick !== run.lastTick || Math.abs(density - run.lastDensity) > 0.004) {
        run.lastTick = tick;
        run.lastDensity = density;
        paint(run.pass, t, tick);
      }
      rafRef.current = requestAnimationFrame(frame);
    },
    [clear, paint]
  );

  const begin = React.useCallback(
    (pass: Pass, duration: number) => {
      if (!enabled) return;
      stopLoop();
      refreshColors();
      runRef.current = {
        pass,
        start: performance.now(),
        duration: Math.max(1, duration),
        pausedTotal: 0,
        hiddenAt: 0,
        lastTick: -1,
        lastDensity: -1,
        lockFired: false,
        handoffFired: false,
      };
      rafRef.current = requestAnimationFrame(frame);
    },
    [enabled, frame, refreshColors, stopLoop]
  );

  const play = React.useCallback(
    (duration: number, delay = 0) => {
      if (!enabled) return;
      stopLoop();
      runRef.current = null;
      clear();
      const start = () => {
        delayTimerRef.current = null;
        cbRef.current.onStart?.();
        begin("in", duration);
      };
      if (delay > 0) delayTimerRef.current = setTimeout(start, delay);
      else start();
    },
    [begin, clear, enabled, stopLoop]
  );

  const dissolve = React.useCallback(
    (duration: number) => begin("out", duration),
    [begin]
  );

  const microFlicker = React.useCallback(
    (duration = 220) => {
      if (!enabled || runRef.current) return;
      begin("micro", clamp(duration, 180, 260));
    },
    [begin, enabled]
  );

  const stop = React.useCallback(() => {
    stopLoop();
    runRef.current = null;
  }, [stopLoop]);

  const isRunning = React.useCallback(() => runRef.current !== null, []);

  /* ---------------------------------------------------------------------
   * Lifecycle
   * ------------------------------------------------------------------ */

  // Re-measure whenever the text, typography inputs or box change. The mask is
  // cached between these; a frame never re-measures anything.
  React.useEffect(() => {
    if (!enabled) {
      setReadySafe(false);
      fieldRef.current = null;
      geomRef.current = null;
      return;
    }
    let raf = 0;
    const schedule = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => void measure());
    };
    schedule();

    const wrapper = wrapperRef.current;
    let ro: ResizeObserver | null = null;
    if (wrapper && typeof ResizeObserver !== "undefined") {
      let first = true;
      ro = new ResizeObserver(() => {
        // The observer fires once on observe(); the initial measure covers it.
        if (first) {
          first = false;
          return;
        }
        schedule();
      });
      ro.observe(wrapper);
    }

    let cancelled = false;
    document.fonts?.ready.then(() => {
      if (!cancelled) schedule();
    });

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, measure, text, variant, setReadySafe]);

  // Pause while the tab is hidden; resume without skipping the sequence.
  React.useEffect(() => {
    if (!enabled) return;
    const onVisibility = () => {
      const run = runRef.current;
      if (!run) return;
      if (document.hidden) {
        run.hiddenAt = performance.now();
        if (rafRef.current) cancelAnimationFrame(rafRef.current);
        rafRef.current = 0;
      } else if (run.hiddenAt) {
        run.pausedTotal += performance.now() - run.hiddenAt;
        run.hiddenAt = 0;
        if (!rafRef.current) rafRef.current = requestAnimationFrame(frame);
      }
    };
    document.addEventListener("visibilitychange", onVisibility);
    return () => document.removeEventListener("visibilitychange", onVisibility);
  }, [enabled, frame]);

  React.useEffect(
    () => () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (delayTimerRef.current) clearTimeout(delayTimerRef.current);
      runRef.current = null;
    },
    []
  );

  return {
    wrapperRef,
    textRef,
    canvasRef,
    ready,
    play,
    dissolve,
    microFlicker,
    clear,
    stop,
    isRunning,
  };
}

/** The documented responsive cell size: clamp(2, fontSize / 18, 5). */
export function responsivePixelSize(fontSize: number) {
  return Math.round(clamp(fontSize / 18, 2, 5));
}

registry/default/motion/pixel-reveal-tex:
/**
 * pixel-reveal-text.css — the plain-CSS equivalent of the Tailwind utilities
 * PixelRevealText ships with.
 *
 * The component already carries these rules as Tailwind classes, so you only
 * need this file if you are dropping the component into a project without
 * Tailwind. In that case, import it once and delete the `cn(...)` utility
 * classes from the component, leaving the three semantic class names:
 * `.pixel-reveal-wrapper`, `.pixel-reveal-text`, `.pixel-reveal-canvas`.
 *
 * Everything here is layout and rasterisation. No colour, no motion: colour is
 * inherited from `currentColor` and motion is owned by Motion and the canvas.
 */

.pixel-reveal-wrapper {
  position: relative;
  /* The DOM text — not the canvas — establishes the box, so nothing shifts. */
}

/* Only inline usage needs shrink-to-fit plus a transform-able box. Block-level
   tags (h1–h4, p, div) are already fine. */
span.pixel-reveal-wrapper {
  display: inline-block;
}

.pixel-reveal-text {
  /* Stays `inline` so multi-line wrapping, text-align and letter-spacing
     behave exactly as they would without the component. */
  display: inline;
}

.pixel-reveal-canvas {
  position: absolute;
  left: 0;
  top: 0;
  /* Never intercept the pointer: the text underneath must stay selectable. */
  pointer-events: none;
  user-select: none;
  -webkit-user-select: none;
  /* Hard pixel edges on every display density. */
  image-rendering: pixelated;
  image-rendering: -moz-crisp-edges;
  image-rendering: crisp-edges;
}

/* Belt and braces: if a consumer renders the canvas despite reduced motion
   being set, it must not animate or obscure the text. */
@media (prefers-reduced-motion: reduce) {
  .pixel-reveal-canvas {
    display: none;
  }
  .pixel-reveal-text {
    opacity: 1 !important;
  }
}

registry/default/fintech/option-chain.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import {
  blackScholes,
  smileIv,
} from "@/registry/default/lib/black-scholes";

/* ------------------------------------------------------------------ */
/* Data model + example-data generator                                  */
/* ------------------------------------------------------------------ */

export interface OptionQuote {
  ltp: number;
  /** Percent change on the day. */
  chg: number;
  oi: number;
  chgOi: number;
  volume: number;
  /** Implied volatility as a fraction, e.g. 0.14. */
  iv: number;
  bid: number;
  ask: number;
  bidQty: number;
  askQty: number;
  delta: number;
  gamma: number;
  theta: number;
  vega: number;
}

export interface OptionChainRow {
  strike: number;
  call: OptionQuote;
  put: OptionQuote;
}

/** Deterministic pseudo-random in [0,1) seeded by strike + salt. */
const prand = (seed: number) => {
  const x = Math.sin(seed * 12.9898) * 43758.5453;
  return x - Math.floor(x);
};

export interface GenerateOptionChainOptions {
  spot: number;
  /** Strike interval. Default 50 (NIFTY). */
  step?: number;
  /** Strikes on each side of ATM. Default 8. */
  span?: number;
  /** Days to expiry. Default 7. */
  dte?: number;
}

/** Coherent example data: premiums and Greeks come from Black-Scholes. */
export function generateOptionChain({
  spot,
  step = 50,
  span = 8,
  dte = 7,
}: GenerateOptionChainOptions): OptionChainRow[] {
  const atm = Math.round(spot / step) * step;
  const t = dte / 365;
  const rows: OptionChainRow[] = [];
  for (let i = -span; i <= span; i++) {
    const strike = atm + i * step;
    const iv = smileIv(spot, strike);
    const quote = (side: "call" | "put"): OptionQuote => {
      const g = blackScholes({ s: spot, k: strike, t, iv, side });
      const salt = strike + (side === "call" ? 1 : 2) * 1000 + dte;
      const near = Math.exp(-Math.abs(strike - spot) / (step * 4));
      const ltp = Math.max(0.05, g.price);
      const spread = Math.max(0.05, ltp * 0.004 + 0.05);
      return {
        ltp,
        chg: (prand(salt) - (side === "call" ? 0.45 : 0.55)) * 18,
        oi: Math.round((0.4 + near) * (1.5 + prand(salt + 1)) * 2_000_000),
        chgOi: Math.round((prand(salt + 2) - 0.45) * 900_000),
        volume: Math.round((0.3 + near) * (1 + prand(salt + 3)) * 1_500_000),
        iv,
        bid: ltp - spread / 2,
        ask: ltp + spread / 2,
        bidQty: Math.round((1 + prand(salt + 4) * 9) * 75),
        askQty: Math.round((1 + prand(salt + 5) * 9) * 75),
        delta: g.delta,
        gamma: g.gamma,
        theta: g.theta,
        vega: g.vega,
      };
    };
    rows.push({ strike, call: quote("call"), put: quote("put") });
  }
  return rows;
}

/* ------------------------------------------------------------------ */
/* Formatting                                                           */
/* ------------------------------------------------------------------ */

const nf0 = new Intl.NumberFormat("en-IN");
const nf2 = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
const compactOi = (n: number) =>
  Math.abs(n) >= 100_000
    ? `${(n / 100_000).toFixed(1)}L`
    : Math.abs(n) >= 1_000
      ? `${(n / 1_000).toFixed(1)}K`
      : nf0.format(n);

/* ------------------------------------------------------------------ */
/* Tick cell: restrained directional flash when a value changes         */
/* ------------------------------------------------------------------ */

function TickNum({
  value,
  format = nf2.format,
  className,
}: {
  value: number;
  format?: (n: number) => string;
  className?: string;
}) {
  const reduced = useReducedMotion();
  const prev = React.useRef(value);
  const [dir, setDir] = React.useState<"up" | "down" | null>(null);

  React.useEffect(() => {
    if (reduced || value === prev.current) {
      prev.current = value;
      return;
    }
    setDir(value > prev.current ? "up" : "down");
    prev.current = value;
    const t = setTimeout(() => setDir(null), 600);
    return () => clearTimeout(t);
  }, [value, reduced]);

  return (
    <span
      className={cn(
        "numeric transition-colors duration-500",
        dir === "up" && "text-market-up",
        dir === "down" && "text-market-down",
        className
      )}
    >
      {format(value)}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* Option chain                                                         */
/* ------------------------------------------------------------------ */

export interface OptionOrder {
  side: "call" | "put";
  action: "buy" | "sell";
  strike: number;
  price: number;
}

export interface OptionChainProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "rows"> {
  rows: OptionChainRow[];
  spot: number;
  /** Lot size shown in the depth panel. Default 75 (NIFTY). */
  lotSize?: number;
  expiries?: string[];
  expiry?: string;
  onExpiryChange?: (expiry: string) => void;
  /** Start with Greek columns instead of OI/volume. */
  defaultShowGreeks?: boolean;
  /** Fewer columns for narrow containers. */
  compact?: boolean;
  onOrder?: (order: OptionOrder) => void;
  ref?: React.Ref<HTMLDivElement>;
}

interface ColumnDef {
  key: string;
  label: string;
  cell: (q: OptionQuote) => React.ReactNode;
}

export function OptionChain({
  rows,
  spot,
  lotSize = 75,
  expiries,
  expiry,
  onExpiryChange,
  defaultShowGreeks = false,
  compact = false,
  onOrder,
  className,
  ref,
  ...rest
}: OptionChainProps) {
  const reduced = useReducedMotion();
  const [showGreeks, setShowGreeks] = React.useState(defaultShowGreeks);
  const [expanded, setExpanded] = React.useState<number | null>(null);

  const atmStrike = React.useMemo(() => {
    let best = rows[0]?.strike ?? 0;
    for (const r of rows)
      if (Math.abs(r.strike - spot) < Math.abs(best - spot)) best = r.strike;
    return best;
  }, [rows, spot]);

  const maxOi = React.useMemo(
    () => Math.max(1, ...rows.flatMap((r) => [r.call.oi, r.put.oi])),
    [rows]
  );

  const columns: ColumnDef[] = React.useMemo(() => {
    if (compact)
      return [
        { key: "oi", label: "OI", cell: (q) => compactOi(q.oi) },
        { key: "ltp", label: "LTP", cell: (q) => <TickNum value={q.ltp} /> },
      ];
    if (showGreeks)
      return [
        { key: "delta", label: "Δ", cell: (q) => <TickNum value={q.delta} format={(n) => n.toFixed(2)} /> },
        { key: "gamma", label: "Γ", cell: (q) => <TickNum value={q.gamma} format={(n) => n.toFixed(4)} /> },
        { key: "theta", label: "Θ", cell: (q) => <TickNum value={q.theta} format={(n) => n.toFixed(2)} /> },
        { key: "vega", label: "V", cell: (q) => <TickNum value={q.vega} format={(n) => n.toFixed(2)} /> },
        { key: "ltp", label: "LTP", cell: (q) => <TickNum value={q.ltp} /> },
      ];
    return [
      { key: "oi", label: "OI", cell: (q) => compactOi(q.oi) },
      {
        key: "chgOi",
        label: "Chg OI",
        cell: (q) => (
          <span className={q.chgOi >= 0 ? "text-market-up" : "text-market-down"}>
            {q.chgOi >= 0 ? "+" : ""}
            {compactOi(q.chgOi)}
          </span>
        ),
      },
      { key: "volume", label: "Vol", cell: (q) => compactOi(q.volume) },
      { key: "iv", label: "IV", cell: (q) => `${(q.iv * 100).toFixed(1)}%` },
      { key: "ltp", label: "LTP", cell: (q) => <TickNum value={q.ltp} /> },
      {
        key: "chg",
        label: "Chg%",
        cell: (q) => (
          <TickNum
            value={q.chg}
            format={(n) => `${n >= 0 ? "+" : ""}${n.toFixed(1)}%`}
            className={q.chg >= 0 ? "text-market-up" : "text-market-down"}
          />
        ),
      },
    ];
  }, [compact, showGreeks]);

  const toggleRow = (strike: number) =>
    setExpanded((e) => (e === strike ? null : strike));

  const oiBar = (q: OptionQuote, side: "call" | "put") => {
    const pct = Math.round((q.oi / maxOi) * 100);
    const color = side === "call" ? "var(--bid)" : "var(--ask)";
    return {
      backgroundImage: `linear-gradient(to ${side === "call" ? "left" : "right"}, color-mix(in oklab, ${color} 26%, transparent) 0%, color-mix(in oklab, ${color} 9%, transparent) ${pct}%, transparent ${pct}%)`,
    };
  };

  return (
    <div
      ref={ref}
      data-slot="option-chain"
      className={cn(
        "w-full overflow-hidden rounded-2xl border border-border/60 bg-card text-sm shadow-md",
        className
      )}
      {...rest}
    >
      {/* Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border/70 px-3 py-2.5">
        <div className="flex items-center gap-2">
          <span className="text-xs font-medium text-muted-foreground">
            Spot
          </span>
          <TickNum value={spot} className="text-sm font-semibold" />
        </div>
        {expiries && expiries.length > 0 ? (
          <div
            role="tablist"
            aria-label="Expiry"
            className="flex items-center gap-1 rounded-lg bg-muted p-0.5"
          >
            {expiries.map((e) => (
              <button
                key={e}
                role="tab"
                aria-selected={e === expiry}
                onClick={() => onExpiryChange?.(e)}
                className={cn(
                  "rounded-md px-2 py-1 text-xs font-medium transition-colors duration-200",
                  e === expiry
                    ? "bg-background text-foreground shadow-sm"
                    : "text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {e}
              </button>
            ))}
          </div>
        ) : null}
        {!compact ? (
          <button
            type="button"
            aria-pressed={showGreeks}
            onClick={() => setShowGreeks((g) => !g)}
            className={cn(
              "rounded-md border border-border px-2.5 py-1 text-xs font-medium transition-colors duration-200",
              showGreeks
                ? "bg-primary text-primary-foreground"
                : "text-muted-foreground hover:bg-muted hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            Greeks
          </button>
        ) : null}
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full min-w-max border-collapse text-right type-label">
          <thead>
            <tr className="border-b border-border type-overline text-muted-foreground">
              <th
                colSpan={columns.length}
                className="px-3 pb-1 pt-2 text-center font-medium text-bid"
              >
                Calls
              </th>
              <th className="px-3 pb-1 pt-2 text-center font-medium">Strike</th>
              <th
                colSpan={columns.length}
                className="px-3 pb-1 pt-2 text-center font-medium text-ask"
              >
                Puts
              </th>
            </tr>
            <tr className="border-b border-border type-meta text-muted-foreground">
              {columns.map((c) => (
                <th key={`c-${c.key}`} className="px-3 py-1.5 font-medium">
                  {c.label}
                </th>
              ))}
              <th className="px-3 py-1.5 text-center font-medium">₹</th>
              {[...columns].reverse().map((c) => (
                <th key={`p-${c.key}`} className="px-3 py-1.5 font-medium">
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => {
              const isAtm = row.strike === atmStrike;
              const callItm = row.strike < spot;
              const putItm = row.strike > spot;
              const isOpen = expanded === row.strike;
              return (
                <React.Fragment key={row.strike}>
                  <tr
                    tabIndex={0}
                    role="button"
                    aria-expanded={isOpen}
                    aria-label={`Strike ${row.strike}, ${isAtm ? "at the money, " : ""}call ${nf2.format(row.call.ltp)}, put ${nf2.format(row.put.ltp)}`}
                    onClick={() => toggleRow(row.strike)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        toggleRow(row.strike);
                      }
                    }}
                    className={cn(
                      "cursor-pointer border-b border-border/60 transition-colors duration-150",
                      isAtm
                        ? "bg-accent/80 font-medium"
                        : "hover:bg-muted/50",
                      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                    )}
                  >
                    {columns.map((c, i) => (
                      <td
                        key={`c-${c.key}`}
                        className={cn(
                          "relative px-3 py-1.5",
                          callItm && "bg-bid/5"
                        )}
                      >
                        {i === 0 && !compact ? (
                          <span
                            aria-hidden="true"
                            className="absolute inset-y-1 right-0 left-0"
                            style={oiBar(row.call, "call")}
                          />
                        ) : null}
                        <span className="relative">{c.cell(row.call)}</span>
                      </td>
                    ))}
                    <td
                      className={cn(
                        "px-3 py-1.5 text-center font-semibold numeric",
                        isAtm && "text-foreground"
                      )}
                    >
                      {nf0.format(row.strike)}
                      {isAtm ? (
                        <span className="ml-1 rounded bg-primary px-1 py-px text-[9px] font-semibold uppercase text-primary-foreground">
                          ATM
                        </span>
                      ) : null}
                    </td>
                    {[...columns].reverse().map((c, i) => (
                      <td
                        key={`p-${c.key}`}
                        className={cn(
                          "relative px-3 py-1.5",
                          putItm && "bg-ask/5"
                        )}
                      >
                        {i === columns.length - 1 && !compact ? (
                          <span
                            aria-hidden="true"
                            className="absolute inset-y-1 left-0 right-0"
                            style={oiBar(row.put, "put")}
                          />
                        ) : null}
                        <span className="relative">{c.cell(row.put)}</span>
                      </td>
                    ))}
                  </tr>
                  {isOpen ? (
                    <tr className="border-b border-border/60 bg-muted/30">
                      <td colSpan={columns.length * 2 + 1} className="p-0">
                        <DepthPanel
                          row={row}
                          lotSize={lotSize}
                          reduced={reduced}
                          onOrder={onOrder}
                        />
                      </td>
                    </tr>
                  ) : null}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
      <p className="border-t border-border px-3 py-2 type-meta text-muted-foreground">
        Lot size {lotSize} · click a strike for depth and orders · simulated
        data
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Depth + order panel (expands in context under the strike row)        */
/* ------------------------------------------------------------------ */

function DepthPanel({
  row,
  lotSize,
  reduced,
  onOrder,
}: {
  row: OptionChainRow;
  lotSize: number;
  reduced: boolean;
  onOrder?: (order: OptionOrder) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { height: "auto", opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { height: 0, opacity: 0 },
        {
          height: "auto",
          opacity: 1,
          duration: 0.35,
          ease: "power3.out",
          clearProps: "height",
        }
      );
    },
    { scope: ref }
  );

  const side = (label: "call" | "put", q: OptionQuote) => (
    <div className="flex-1 rounded-lg border border-border bg-card p-3">
      <div className="mb-2 flex items-center justify-between">
        <span
          className={cn(
            "text-xs font-semibold uppercase tracking-wide",
            label === "call" ? "text-bid" : "text-ask"
          )}
        >
          {label} {nf0.format(row.strike)}
        </span>
        <span className="text-xs text-muted-foreground">
          Δ {q.delta.toFixed(2)} · Θ {q.theta.toFixed(2)}
        </span>
      </div>
      <div className="grid grid-cols-2 gap-2 text-center type-label numeric">
        <div className="rounded-md bg-bid/10 px-2 py-1.5">
          <p className="type-overline text-muted-foreground">
            Bid × {q.bidQty}
          </p>
          <p className="font-medium text-bid">{nf2.format(q.bid)}</p>
        </div>
        <div className="rounded-md bg-ask/10 px-2 py-1.5">
          <p className="type-overline text-muted-foreground">
            Ask × {q.askQty}
          </p>
          <p className="font-medium text-ask">{nf2.format(q.ask)}</p>
        </div>
      </div>
      <div className="mt-2 grid grid-cols-2 gap-2">
        <button
          type="button"
          onClick={() =>
            onOrder?.({ side: label, action: "buy", strike: row.strike, price: q.ask })
          }
          className="rounded-md bg-market-up px-2 py-1.5 text-xs font-semibold text-white transition-transform duration-100 active:scale-97 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          Buy ({lotSize})
        </button>
        <button
          type="button"
          onClick={() =>
            onOrder?.({ side: label, action: "sell", strike: row.strike, price: q.bid })
          }
          className="rounded-md bg-market-down px-2 py-1.5 text-xs font-semibold text-white transition-transform duration-100 active:scale-97 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          Sell ({lotSize})
        </button>
      </div>
    </div>
  );

  return (
    <div ref={ref} className="overflow-hidden">
      <div className="flex flex-col gap-3 p-3 sm:flex-row">
        {side("call", row.call)}
        {side("put", row.put)}
      </div>
    </div>
  );
}

registry/default/lib/black-scholes.ts:
/**
 * Compact Black-Scholes pricing and Greeks for index options.
 * Powers OptionChain and GreeksPanel so displayed values stay coherent
 * (premium, delta, gamma, theta and vega always agree with each other).
 * Rates are annualized; time is in years.
 */

/** Abramowitz–Stegun error-function approximation (max error ~1.5e-7). */
export function erf(x: number): number {
  const sign = x < 0 ? -1 : 1;
  const ax = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * ax);
  const y =
    1 -
    (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t -
      0.284496736) *
      t +
      0.254829592) *
      t *
      Math.exp(-ax * ax);
  return sign * y;
}

/** Standard normal CDF. */
export const cnd = (x: number): number => 0.5 * (1 + erf(x / Math.SQRT2));

/** Standard normal PDF. */
export const pdf = (x: number): number =>
  Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);

export interface Greeks {
  /** Option premium. */
  price: number;
  /** Per ₹1 move in the underlying. */
  delta: number;
  /** Delta change per ₹1 move. */
  gamma: number;
  /** Per calendar day (already divided by 365). */
  theta: number;
  /** Per 1 percentage-point change in IV. */
  vega: number;
}

export interface BsInput {
  /** Spot price. */
  s: number;
  /** Strike price. */
  k: number;
  /** Time to expiry in years. */
  t: number;
  /** Implied volatility, e.g. 0.14 for 14%. */
  iv: number;
  /** Risk-free rate. Default 0.065. */
  r?: number;
  side: "call" | "put";
}

export function blackScholes({ s, k, t, iv, r = 0.065, side }: BsInput): Greeks {
  const T = Math.max(t, 1 / 365 / 24); // clamp: expiry day still prices
  const sig = Math.max(iv, 0.001);
  const sqT = Math.sqrt(T);
  const d1 = (Math.log(s / k) + (r + (sig * sig) / 2) * T) / (sig * sqT);
  const d2 = d1 - sig * sqT;
  const disc = Math.exp(-r * T);

  const callPrice = s * cnd(d1) - k * disc * cnd(d2);
  const putPrice = k * disc * cnd(-d2) - s * cnd(-d1);
  const gamma = pdf(d1) / (s * sig * sqT);
  const vega = (s * pdf(d1) * sqT) / 100;

  if (side === "call") {
    const theta =
      (-(s * pdf(d1) * sig) / (2 * sqT) - r * k * disc * cnd(d2)) / 365;
    return { price: callPrice, delta: cnd(d1), gamma, theta, vega };
  }
  const theta =
    (-(s * pdf(d1) * sig) / (2 * sqT) + r * k * disc * cnd(-d2)) / 365;
  return { price: putPrice, delta: cnd(d1) - 1, gamma, theta, vega };
}

/** A gentle smile: IV rises away from ATM. `skew` tilts the put side up. */
export function smileIv(
  s: number,
  k: number,
  base = 0.13,
  skew = 0.015
): number {
  const m = (k - s) / s;
  return base + 6 * m * m - skew * m * 10 * 0.01;
}

registry/default/fintech/greeks-panel.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { blackScholes, smileIv } from "@/registry/default/lib/black-scholes";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

export interface GreeksPanelProps
  extends React.HTMLAttributes<HTMLDivElement> {
  side: "call" | "put";
  strike: number;
  spot: number;
  /** Days to expiry. */
  dte: number;
  /** Implied volatility as a fraction. Defaults to a smile around ATM. */
  iv?: number;
  /** Contract lot size used for the per-lot theta line. Default 75. */
  lotSize?: number;
  ref?: React.Ref<HTMLDivElement>;
}

interface GreekRow {
  key: "delta" | "gamma" | "theta" | "vega";
  label: string;
  symbol: string;
  value: number;
  decimals: number;
  /** 0–1 magnitude for the gauge. */
  norm: number;
  negative: boolean;
  description: string;
  /** Identity hue (HSL channels). */
  hue: string;
}

/**
 * Live Greeks for one option: premium and Δ Γ Θ V computed with
 * Black-Scholes so every number agrees. Values roll with NumberFlow and
 * each gauge springs to its new magnitude when inputs change.
 */
export function GreeksPanel({
  side,
  strike,
  spot,
  dte,
  iv,
  lotSize = 75,
  className,
  ref,
  ...rest
}: GreeksPanelProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const vol = iv ?? smileIv(spot, strike);
  const g = blackScholes({ s: spot, k: strike, t: dte / 365, iv: vol, side });
  const moneyness =
    (side === "call" ? spot - strike : strike - spot) > 0 ? "ITM" : "OTM";

  const rows: GreekRow[] = [
    {
      key: "delta",
      label: "Delta",
      symbol: "Δ",
      value: g.delta,
      decimals: 2,
      norm: Math.min(1, Math.abs(g.delta)),
      negative: g.delta < 0,
      description: "Premium change per ₹1 move.",
      hue: "217 91% 60%",
    },
    {
      key: "gamma",
      label: "Gamma",
      symbol: "Γ",
      value: g.gamma,
      decimals: 4,
      norm: Math.min(1, g.gamma * 400),
      negative: false,
      description: "How fast delta moves; peaks ATM.",
      hue: "258 90% 66%",
    },
    {
      key: "theta",
      label: "Theta",
      symbol: "Θ",
      value: g.theta,
      decimals: 2,
      norm: Math.min(1, Math.abs(g.theta) / Math.max(1, g.price * 0.25)),
      negative: g.theta < 0,
      description: "Time decay per day.",
      hue: "0 84% 60%",
    },
    {
      key: "vega",
      label: "Vega",
      symbol: "V",
      value: g.vega,
      decimals: 2,
      norm: Math.min(1, g.vega / Math.max(1, spot * 0.002)),
      negative: false,
      description: "Premium change per 1% IV.",
      hue: "173 80% 40%",
    },
  ];

  // Gauges spring to their new magnitude whenever inputs change.
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(
        root.querySelectorAll("[data-gauge]")
      );
      for (const bar of bars) {
        const target = Number(bar.dataset.gauge ?? 0) * 100;
        if (reduced) gsap.set(bar, { width: `${target}%` });
        else
          gsap.to(bar, {
            width: `${target}%`,
            duration: 0.6,
            ease: "power3.out",
            overwrite: true,
          });
      }
      // Tiles cascade in on first paint.
      const tiles = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-tile]"));
      if (!reduced) {
        gsap.fromTo(
          tiles,
          { y: 10, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.45, ease: "power3.out", stagger: 0.06, clearProps: "transform,opacity" }
        );
      }
    },
    { dependencies: [spot, strike, dte, vol, side, reduced], scope: rootRef }
  );

  const sideHue = side === "call" ? "217 91% 60%" : "38 92% 50%";

  return (
    <div
      ref={rootRef}
      data-slot="greeks-panel"
      className={cn(
        "relative w-full max-w-md overflow-hidden rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -right-10 -top-12 size-32 rounded-full opacity-[0.12] blur-2xl"
        style={{ background: `hsl(${sideHue})` }}
      />

      {/* Header */}
      <div className="relative flex flex-wrap items-center gap-2">
        <span
          className="type-overline rounded-lg px-2 py-0.5 font-semibold ring-1 ring-inset"
          style={{
            color: `hsl(${sideHue})`,
            background: `hsl(${sideHue} / 0.12)`,
            boxShadow: `inset 0 0 0 1px hsl(${sideHue} / 0.2)`,
          }}
        >
          {side}
        </span>
        <span className="text-sm font-semibold numeric text-foreground">
          {new Intl.NumberFormat("en-IN").format(strike)}
        </span>
        <span className="rounded-full bg-muted/70 px-1.5 py-0.5 type-caption font-medium text-muted-foreground">
          {moneyness}
        </span>
        <span className="text-xs text-muted-foreground">
          {dte}d · IV {(vol * 100).toFixed(1)}%
        </span>
      </div>

      {/* Premium hero */}
      <div className="relative mt-3 flex items-baseline gap-2">
        <span className="type-display text-foreground">
          <NumberFlow value={g.price} prefix="₹" decimals={2} locale="en-IN" trend />
        </span>
        <span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
          premium
        </span>
      </div>

      {/* Greek tiles */}
      <ul className="relative mt-5 grid grid-cols-2 gap-3">
        {rows.map((row) => (
          <li
            key={row.key}
            data-tile
            className="group/tile relative overflow-hidden rounded-2xl border border-border/60 bg-background/60 p-3.5 transition-shadow duration-200 hover:shadow-sm"
          >
            <span
              aria-hidden="true"
              className="pointer-events-none absolute -right-1 -top-2 select-none text-5xl font-semibold leading-none opacity-[0.07] transition-opacity duration-300 group-hover/tile:opacity-[0.14]"
              style={{ color: `hsl(${row.hue})` }}
            >
              {row.symbol}
            </span>
            <p className="type-overline text-muted-foreground">
              {row.label}
            </p>
            <p
              className={cn(
                "mt-0.5 text-xl font-semibold numeric",
                row.negative ? "text-market-down" : "text-foreground"
              )}
            >
              <NumberFlow value={row.value} decimals={row.decimals} trend />
            </p>
            <div
              className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-muted/70 ring-1 ring-inset ring-border/40"
              role="meter"
              aria-label={`${row.label} magnitude`}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={Math.round(row.norm * 100)}
            >
              <span
                data-gauge={row.norm}
                className="block h-full rounded-full"
                style={{
                  width: 0,
                  background: `linear-gradient(90deg, hsl(${row.hue} / 0.5), hsl(${row.hue}))`,
                }}
              />
            </div>
            <p className="mt-2 type-meta leading-4 text-muted-foreground">
              {row.description}
            </p>
          </li>
        ))}
      </ul>

      <p className="relative mt-4 flex items-center justify-between border-t border-border/60 pt-3 type-meta text-muted-foreground">
        <span>
          Θ per lot ({lotSize}):{" "}
          <span className="font-medium numeric text-foreground">
            ₹{(g.theta * lotSize).toFixed(0)}/day
          </span>
        </span>
        <span>Black-Scholes · r 6.5%</span>
      </p>
    </div>
  );
}

registry/default/workflows/kyc-flow.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Input } from "@/registry/default/ui/input";
import { Field } from "@/registry/default/ui/field";
import { Alert } from "@/registry/default/ui/alert";
import { Badge } from "@/registry/default/ui/badge";

/* ------------------------------------------------------------------ */
/* Types                                                                */
/* ------------------------------------------------------------------ */

export interface KycData {
  name: string;
  email: string;
  dob: string;
  pan: string;
}

export type KycOutcome = "approved" | "manual-review";

export interface KycFlowProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onComplete"> {
  /** Final verification outcome once submitted. Default "approved". */
  outcome?: KycOutcome;
  onComplete?: (data: KycData, outcome: KycOutcome) => void;
  onStepChange?: (step: number) => void;
  initialData?: Partial<KycData>;
  ref?: React.Ref<HTMLDivElement>;
}

const STEPS = ["Details", "PAN", "Documents", "Liveness", "Review"] as const;
const PAN_RE = /^[A-Z]{5}[0-9]{4}[A-Z]$/;
const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/* ------------------------------------------------------------------ */
/* Small shared pieces                                                  */
/* ------------------------------------------------------------------ */

function CheckIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn("size-3.5", className)}
      aria-hidden="true"
    >
      <path d="M5 13l4 4L19 7" />
    </svg>
  );
}

/** Big success check that draws itself. */
function SuccessCheck() {
  const ref = React.useRef<SVGPathElement>(null);
  const reduced = useReducedMotion();
  useGSAP(() => {
    if (!ref.current) return;
    if (reduced) {
      gsap.set(ref.current, { strokeDashoffset: 0 });
      return;
    }
    gsap.fromTo(
      ref.current,
      { strokeDashoffset: 1 },
      { strokeDashoffset: 0, duration: 0.6, ease: "power2.inOut", delay: 0.2 }
    );
  });
  return (
    <span className="flex size-14 items-center justify-center rounded-full bg-success/15">
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2.5}
        strokeLinecap="round"
        strokeLinejoin="round"
        className="size-7 text-success"
        aria-hidden="true"
      >
        <path
          ref={ref}
          d="M5 13l4 4L19 7"
          pathLength={1}
          strokeDasharray={1}
          strokeDashoffset={1}
        />
      </svg>
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* Progress rail                                                        */
/* ------------------------------------------------------------------ */

function StepRail({ step }: { step: number }) {
  const reduced = useReducedMotion();
  const fillRef = React.useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (!fillRef.current) return;
      const pct = (Math.min(step, STEPS.length - 1) / (STEPS.length - 1)) * 100;
      if (reduced) gsap.set(fillRef.current, { width: `${pct}%` });
      else
        gsap.to(fillRef.current, {
          width: `${pct}%`,
          duration: 0.5,
          ease: "power3.inOut",
        });
    },
    { dependencies: [step, reduced] }
  );

  return (
    <ol
      aria-label="Verification progress"
      className="relative mb-6 flex items-start justify-between"
    >
      <span
        aria-hidden="true"
        className="absolute left-3 right-3 top-[11px] h-0.5 bg-border"
      />
      <span
        aria-hidden="true"
        className="absolute left-3 top-[11px] h-0.5 max-w-[calc(100%-1.5rem)] rounded-full"
        ref={fillRef}
        style={{
          width: 0,
          background: "linear-gradient(90deg, color-mix(in oklab, var(--primary) 55%, transparent), var(--primary))",
        }}
      />
      {STEPS.map((label, i) => {
        const done = step > i;
        const active = step === i;
        return (
          <li
            key={label}
            aria-current={active ? "step" : undefined}
            className="relative flex w-12 flex-col items-center gap-1.5"
          >
            <span
              className={cn(
                "flex size-6 items-center justify-center rounded-full border-2 type-caption font-semibold transition-colors duration-300",
                done
                  ? "border-primary bg-primary text-primary-foreground"
                  : active
                    ? "border-primary bg-background text-foreground"
                    : "border-border bg-background text-muted-foreground"
              )}
            >
              {done ? <CheckIcon className="size-3" /> : i + 1}
            </span>
            <span
              className={cn(
                "type-caption font-medium",
                active ? "text-foreground" : "text-muted-foreground"
              )}
            >
              {label}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

/* ------------------------------------------------------------------ */
/* Step container: directional slide-in on step change                  */
/* ------------------------------------------------------------------ */

function StepPanel({
  step,
  dir,
  children,
}: {
  step: number;
  dir: 1 | -1;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { x: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { x: 28 * dir, opacity: 0, filter: "blur(6px)" },
        {
          x: 0,
          opacity: 1,
          filter: "blur(0px)",
          duration: 0.4,
          ease: "power3.out",
          clearProps: "filter",
        }
      );
    },
    { dependencies: [step], scope: ref }
  );

  return (
    <div ref={ref} key={step}>
      {children}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Step 2: document capture card                                        */
/* ------------------------------------------------------------------ */

type DocState = "idle" | "checking" | "glare" | "done";

function DocCapture({
  label,
  state,
  onCapture,
}: {
  label: string;
  state: DocState;
  onCapture: () => void;
}) {
  return (
    <div
      className={cn(
        "flex flex-1 flex-col items-center gap-2 rounded-xl border border-dashed p-4 text-center transition-colors duration-300",
        state === "done"
          ? "border-success/60 bg-success/5"
          : state === "glare"
            ? "border-warning/60 bg-warning/5"
            : "border-border"
      )}
    >
      <span className="text-xs font-medium text-foreground">{label}</span>
      {state === "idle" ? (
        <>
          <span className="type-meta text-muted-foreground">
            Align inside the frame — we check focus and glare
          </span>
          <Button size="sm" variant="outline" onClick={onCapture}>
            Capture
          </Button>
        </>
      ) : null}
      {state === "checking" ? (
        <>
          <span className="relative h-1.5 w-full overflow-hidden rounded-full bg-muted">
            <span className="absolute inset-y-0 w-1/3 animate-duku-shimmer rounded-full bg-primary/60" />
          </span>
          <span className="type-meta text-muted-foreground">
            Checking edges, blur and glare…
          </span>
        </>
      ) : null}
      {state === "glare" ? (
        <>
          <span className="type-meta text-warning">
            Glare detected — tilt the document away from the light
          </span>
          <Button size="sm" variant="outline" onClick={onCapture}>
            Retake
          </Button>
        </>
      ) : null}
      {state === "done" ? (
        <span className="flex items-center gap-1.5 type-meta font-medium text-success">
          <CheckIcon /> Quality passed
        </span>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Step 3: liveness arc                                                 */
/* ------------------------------------------------------------------ */

const LIVENESS_PROMPTS = [
  "Center your face",
  "Turn your head left",
  "Turn your head right",
  "Blink twice",
] as const;

function LivenessCheck({
  running,
  done,
  prompt,
  progress,
}: {
  running: boolean;
  done: boolean;
  prompt: string;
  progress: number;
}) {
  const arcRef = React.useRef<SVGCircleElement>(null);
  const reduced = useReducedMotion();

  useGSAP(
    () => {
      if (!arcRef.current) return;
      if (reduced) {
        gsap.set(arcRef.current, { strokeDashoffset: 1 - progress });
        return;
      }
      gsap.to(arcRef.current, {
        strokeDashoffset: 1 - progress,
        duration: 0.8,
        ease: "power2.inOut",
      });
    },
    { dependencies: [progress, reduced] }
  );

  return (
    <div className="flex flex-col items-center gap-3">
      <div className="relative">
        <svg viewBox="0 0 120 120" className="size-32" aria-hidden="true">
          <circle
            cx="60"
            cy="60"
            r="54"
            fill="none"
            strokeWidth="4"
            className="stroke-muted"
          />
          <circle
            ref={arcRef}
            cx="60"
            cy="60"
            r="54"
            fill="none"
            strokeWidth="4"
            strokeLinecap="round"
            pathLength={1}
            strokeDasharray={1}
            strokeDashoffset={1}
            transform="rotate(-90 60 60)"
            className={cn(done ? "stroke-success" : "stroke-primary")}
          />
          {/* abstract face silhouette */}
          <circle cx="60" cy="50" r="14" className="fill-muted-foreground/30" />
          <path
            d="M36 92c4-14 14-20 24-20s20 6 24 20"
            className="fill-muted-foreground/30"
          />
        </svg>
        {done ? (
          <span className="absolute inset-0 flex items-center justify-center">
            <SuccessCheck />
          </span>
        ) : null}
      </div>
      <p
        aria-live="polite"
        className={cn(
          "text-sm font-medium",
          done ? "text-success" : "text-foreground"
        )}
      >
        {done ? "Liveness confirmed" : running ? prompt : "Ready when you are"}
      </p>
      <p className="max-w-xs text-center type-meta leading-4 text-muted-foreground">
        Frames are processed on-device for this check and never stored. This
        demo simulates the camera.
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* The flow                                                             */
/* ------------------------------------------------------------------ */

export function KycFlow({
  outcome = "approved",
  onComplete,
  onStepChange,
  initialData,
  className,
  ref,
  ...rest
}: KycFlowProps) {
  const [step, setStepRaw] = React.useState(0);
  const [dir, setDir] = React.useState<1 | -1>(1);
  const [data, setData] = React.useState<KycData>({
    name: initialData?.name ?? "",
    email: initialData?.email ?? "",
    dob: initialData?.dob ?? "",
    pan: initialData?.pan ?? "",
  });
  const [errors, setErrors] = React.useState<Partial<Record<keyof KycData, string>>>({});
  const [panState, setPanState] = React.useState<"idle" | "verifying" | "verified">("idle");
  const [docFront, setDocFront] = React.useState<DocState>("idle");
  const [docBack, setDocBack] = React.useState<DocState>("idle");
  const frontAttempts = React.useRef(0);
  const [liveRunning, setLiveRunning] = React.useState(false);
  const [liveDone, setLiveDone] = React.useState(false);
  const [livePrompt, setLivePrompt] = React.useState<string>(LIVENESS_PROMPTS[0]);
  const [liveProgress, setLiveProgress] = React.useState(0);
  const [submitting, setSubmitting] = React.useState(false);
  const [result, setResult] = React.useState<KycOutcome | null>(null);

  const setStep = (next: number) => {
    setDir(next > step ? 1 : -1);
    setStepRaw(next);
    onStepChange?.(next);
  };

  const patch = (k: keyof KycData, v: string) => {
    setData((d) => ({ ...d, [k]: v }));
    setErrors((e) => ({ ...e, [k]: undefined }));
  };

  /* Step 0 */
  const submitDetails = () => {
    const next: typeof errors = {};
    if (data.name.trim().length < 2) next.name = "Enter your full legal name.";
    if (!/^\S+@\S+\.\S+$/.test(data.email)) next.email = "Enter a valid email.";
    if (!data.dob) next.dob = "Date of birth is required.";
    setErrors(next);
    if (Object.values(next).some(Boolean)) return;
    setStep(1);
  };

  /* Step 1 */
  const verifyPan = async () => {
    if (!PAN_RE.test(data.pan)) {
      setErrors((e) => ({
        ...e,
        pan: "PAN must look like ABCDE1234F.",
      }));
      return;
    }
    setPanState("verifying");
    await wait(1200);
    setPanState("verified");
  };

  /* Step 2 */
  const capture = async (side: "front" | "back") => {
    const set = side === "front" ? setDocFront : setDocBack;
    set("checking");
    await wait(1100);
    if (side === "front" && frontAttempts.current === 0) {
      frontAttempts.current += 1;
      set("glare"); // first front attempt fails: the state is the product
      return;
    }
    set("done");
  };

  /* Step 3 */
  const runLiveness = async () => {
    setLiveRunning(true);
    for (let i = 0; i < LIVENESS_PROMPTS.length; i++) {
      setLivePrompt(LIVENESS_PROMPTS[i]);
      setLiveProgress((i + 1) / LIVENESS_PROMPTS.length);
      await wait(900);
    }
    setLiveRunning(false);
    setLiveDone(true);
  };

  /* Step 4 */
  const submitAll = async () => {
    setSubmitting(true);
    await wait(1500);
    setSubmitting(false);
    setResult(outcome);
    setStep(5);
    onComplete?.(data, outcome);
  };

  const review: [string, string, number][] = [
    ["Name", data.name, 0],
    ["Email", data.email, 0],
    ["Date of birth", data.dob, 0],
    ["PAN", data.pan, 1],
    ["ID document", "Front + back verified", 2],
    ["Liveness", "Confirmed", 3],
  ];

  return (
    <div
      ref={ref}
      data-slot="kyc-flow"
      className={cn(
        "w-full max-w-md rounded-3xl border border-border/60 bg-card p-6 shadow-md",
        className
      )}
      {...rest}
    >
      {step < 5 ? <StepRail step={step} /> : null}

      <StepPanel step={step} dir={dir}>
        {step === 0 ? (
          <form
            className="flex flex-col gap-4"
            onSubmit={(e) => {
              e.preventDefault();
              submitDetails();
            }}
          >
            <Field
              label="Full name"
              state={errors.name ? "error" : null}
              message={errors.name}
            >
              <Input
                value={data.name}
                invalid={!!errors.name}
                autoComplete="name"
                onChange={(e) => patch("name", e.target.value)}
              />
            </Field>
            <Field
              label="Email"
              state={errors.email ? "error" : null}
              message={errors.email}
            >
              <Input
                type="email"
                value={data.email}
                invalid={!!errors.email}
                autoComplete="email"
                onChange={(e) => patch("email", e.target.value)}
              />
            </Field>
            <Field
              label="Date of birth"
              state={errors.dob ? "error" : null}
              message={errors.dob}
            >
              <Input
                type="date"
                value={data.dob}
                invalid={!!errors.dob}
                onChange={(e) => patch("dob", e.target.value)}
              />
            </Field>
            <Button type="submit" className="mt-1">
              Continue
            </Button>
          </form>
        ) : null}

        {step === 1 ? (
          <div className="flex flex-col gap-4">
            <Field
              label="PAN"
              state={errors.pan ? "error" : panState === "verified" ? "success" : "hint"}
              message={
                errors.pan ??
                (panState === "verified"
                  ? "Verified against the income-tax registry."
                  : "Permanent Account Number, e.g. ABCDE1234F.")
              }
            >
              <Input
                value={data.pan}
                invalid={!!errors.pan}
                valid={panState === "verified"}
                maxLength={10}
                autoCapitalize="characters"
                disabled={panState !== "idle"}
                onChange={(e) => patch("pan", e.target.value.toUpperCase())}
              />
            </Field>
            {panState === "verified" ? (
              <Alert variant="success" title="Name match">
                Registered name matches your PAN record.
              </Alert>
            ) : null}
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(0)}>
                Back
              </Button>
              {panState === "verified" ? (
                <Button className="flex-1" onClick={() => setStep(2)}>
                  Continue
                </Button>
              ) : (
                <Button
                  className="flex-1"
                  loading={panState === "verifying"}
                  onClick={verifyPan}
                >
                  Verify PAN
                </Button>
              )}
            </div>
          </div>
        ) : null}

        {step === 2 ? (
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-3 sm:flex-row">
              <DocCapture
                label="ID front"
                state={docFront}
                onCapture={() => capture("front")}
              />
              <DocCapture
                label="ID back"
                state={docBack}
                onCapture={() => capture("back")}
              />
            </div>
            <p className="type-meta text-muted-foreground">
              No camera? You can also upload a scan — the same quality checks
              apply.
            </p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(1)}>
                Back
              </Button>
              <Button
                className="flex-1"
                disabled={docFront !== "done" || docBack !== "done"}
                onClick={() => setStep(3)}
              >
                Continue
              </Button>
            </div>
          </div>
        ) : null}

        {step === 3 ? (
          <div className="flex flex-col gap-4">
            <LivenessCheck
              running={liveRunning}
              done={liveDone}
              prompt={livePrompt}
              progress={liveProgress}
            />
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(2)}>
                Back
              </Button>
              {liveDone ? (
                <Button className="flex-1" onClick={() => setStep(4)}>
                  Continue
                </Button>
              ) : (
                <Button
                  className="flex-1"
                  loading={liveRunning}
                  onClick={runLiveness}
                >
                  Start liveness check
                </Button>
              )}
            </div>
          </div>
        ) : null}

        {step === 4 ? (
          <div className="flex flex-col gap-4">
            <dl className="divide-y divide-border rounded-xl border border-border">
              {review.map(([k, v, target]) => (
                <div
                  key={k}
                  className="flex items-center justify-between gap-2 px-3 py-2.5"
                >
                  <div className="min-w-0">
                    <dt className="type-overline text-muted-foreground">
                      {k}
                    </dt>
                    <dd className="truncate text-sm text-foreground">{v}</dd>
                  </div>
                  <button
                    type="button"
                    onClick={() => setStep(target)}
                    className="text-xs font-medium text-muted-foreground underline-offset-4 transition-colors duration-200 hover:text-foreground hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    Edit
                  </button>
                </div>
              ))}
            </dl>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(3)}>
                Back
              </Button>
              <Button className="flex-1" loading={submitting} onClick={submitAll}>
                Submit for verification
              </Button>
            </div>
          </div>
        ) : null}

        {step === 5 && result === "approved" ? (
          <div className="flex flex-col items-center gap-3 py-4 text-center">
            <SuccessCheck />
            <h3 className="text-lg font-semibold text-foreground">
              Identity verified
            </h3>
            <p className="max-w-xs text-sm text-muted-foreground">
              {data.name.split(" ")[0] || "You"}, your account is fully
              activated. A confirmation is on its way to {data.email}.
            </p>
          </div>
        ) : null}

        {step === 5 && result === "manual-review" ? (
          <div className="flex flex-col items-center gap-3 py-4 text-center">
            <Badge variant="outline" pulse className="text-warning">
              Manual review
            </Badge>
            <h3 className="text-lg font-semibold text-foreground">
              A specialist is taking a look
            </h3>
            <p className="max-w-xs text-sm text-muted-foreground">
              Your documents passed automated checks but need one human
              confirmation. Typical turnaround is under 2 hours — we&apos;ll
              email {data.email} the moment it completes. Nothing else is
              needed from you.
            </p>
          </div>
        ) : null}
      </StepPanel>
    </div>
  );
}

registry/default/crypto/crypto-swap.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Spinner } from "@/registry/default/ui/spinner";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface SwapToken {
  symbol: string;
  name: string;
  /** USD price used for quoting. */
  usd: number;
  balance: number;
  /** Tailwind color class for the coin dot. */
  tone: string;
  /** ERC-20s need an approval transaction before the first swap. */
  needsApproval?: boolean;
}

export const DEFAULT_TOKENS: SwapToken[] = [
  { symbol: "USDT", name: "Tether USD", usd: 1, balance: 2450.75, tone: "bg-emerald-500", needsApproval: true },
  { symbol: "ETH", name: "Ether", usd: 3412.6, balance: 0.42, tone: "bg-indigo-500" },
  { symbol: "USDC", name: "USD Coin", usd: 1, balance: 830.1, tone: "bg-sky-500", needsApproval: true },
  { symbol: "WBTC", name: "Wrapped BTC", usd: 97540, balance: 0.012, tone: "bg-amber-500", needsApproval: true },
];

export interface SwapQuote {
  rate: number;
  priceImpact: number;
  gasUsd: number;
  route: string[];
}

export interface CryptoSwapProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  tokens?: SwapToken[];
  /** Called after the simulated on-chain confirmation. */
  onSwapped?: (detail: {
    from: string;
    to: string;
    amountIn: number;
    amountOut: number;
  }) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const fmt = (n: number, max = 6) =>
  new Intl.NumberFormat("en-US", { maximumFractionDigits: max }).format(n);

function quote(from: SwapToken, to: SwapToken, amountIn: number): SwapQuote {
  const rate = from.usd / to.usd;
  const notional = amountIn * from.usd;
  const priceImpact = Math.min(9.9, (notional / 2_000_000) * 100);
  const direct =
    (from.symbol === "USDC" && to.symbol === "ETH") ||
    (from.symbol === "ETH" && to.symbol === "USDC");
  const route = direct
    ? [from.symbol, to.symbol]
    : from.symbol === "ETH" || to.symbol === "ETH"
      ? [from.symbol, "USDC", to.symbol === "ETH" ? "WETH" : to.symbol, ...(to.symbol === "ETH" ? ["ETH"] : [])]
      : [from.symbol, "USDC", to.symbol];
  return { rate, priceImpact, gasUsd: 2.6 + priceImpact * 0.4, route: [...new Set(route)] };
}

/* ------------------------------------------------------------------ */
/* Token select                                                         */
/* ------------------------------------------------------------------ */

function TokenSelect({
  tokens,
  value,
  exclude,
  onChange,
  label,
}: {
  tokens: SwapToken[];
  value: SwapToken;
  exclude: string;
  onChange: (t: SwapToken) => void;
  label: string;
}) {
  return (
    <div className="relative inline-flex items-center gap-1.5">
      <span aria-hidden="true" className={cn("size-4 rounded-full", value.tone)} />
      <select
        aria-label={label}
        value={value.symbol}
        onChange={(e) => {
          const t = tokens.find((x) => x.symbol === e.target.value);
          if (t) onChange(t);
        }}
        className="appearance-none rounded-md bg-transparent pr-4 text-sm font-semibold text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {tokens
          .filter((t) => t.symbol !== exclude)
          .map((t) => (
            <option key={t.symbol} value={t.symbol}>
              {t.symbol}
            </option>
          ))}
      </select>
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        className="pointer-events-none absolute right-0 size-3 text-muted-foreground"
        aria-hidden="true"
      >
        <path d="m6 9 6 6 6-6" />
      </svg>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Swap                                                                 */
/* ------------------------------------------------------------------ */

type Stage = "form" | "approving" | "swapping" | "done";

export function CryptoSwap({
  tokens = DEFAULT_TOKENS,
  onSwapped,
  className,
  ref,
  ...rest
}: CryptoSwapProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [from, setFrom] = React.useState(tokens[0]);
  const [to, setTo] = React.useState(tokens[1]);
  const [amount, setAmount] = React.useState("1000");
  const [slippage, setSlippage] = React.useState(0.5);
  const [feesOpen, setFeesOpen] = React.useState(false);
  const [approved, setApproved] = React.useState<Record<string, boolean>>({});
  const [stage, setStage] = React.useState<Stage>("form");
  const [txStep, setTxStep] = React.useState(0);

  const amountIn = parseFloat(amount) || 0;
  const q = quote(from, to, amountIn);
  const amountOut = amountIn * q.rate * (1 - q.priceImpact / 100);
  const minReceived = amountOut * (1 - slippage / 100);
  const insufficient = amountIn > from.balance;
  const needsApproval = !!from.needsApproval && !approved[from.symbol];

  const feesRef = React.useRef<HTMLDivElement>(null);
  const payRef = React.useRef<HTMLDivElement>(null);
  const recvRef = React.useRef<HTMLDivElement>(null);

  /* Fee breakdown expands fluidly. */
  useGSAP(
    () => {
      if (!feesRef.current) return;
      if (reduced) {
        gsap.set(feesRef.current, { height: feesOpen ? "auto" : 0, opacity: feesOpen ? 1 : 0 });
        return;
      }
      gsap.to(feesRef.current, {
        height: feesOpen ? "auto" : 0,
        opacity: feesOpen ? 1 : 0,
        duration: 0.35,
        ease: "power3.out",
      });
    },
    { dependencies: [feesOpen, reduced] }
  );

  /* Tokens physically exchange position on flip. */
  const flip = () => {
    const doSwap = () => {
      setFrom(to);
      setTo(from);
      setAmount(fmt(amountOut, to.usd > 100 ? 5 : 2).replace(/,/g, ""));
    };
    if (reduced || !payRef.current || !recvRef.current) {
      doSwap();
      return;
    }
    const dy = recvRef.current.offsetTop - payRef.current.offsetTop;
    const tl = gsap.timeline({
      onComplete: () => {
        gsap.set([payRef.current, recvRef.current], { y: 0 });
        doSwap();
      },
    });
    tl.to(payRef.current, { y: dy, duration: 0.35, ease: "power3.inOut" }, 0)
      .to(recvRef.current, { y: -dy, duration: 0.35, ease: "power3.inOut" }, 0);
  };

  const approve = async () => {
    setStage("approving");
    await new Promise((r) => setTimeout(r, 1400));
    setApproved((a) => ({ ...a, [from.symbol]: true }));
    setStage("form");
  };

  const swap = async () => {
    setStage("swapping");
    setTxStep(0);
    await new Promise((r) => setTimeout(r, 900));
    setTxStep(1);
    await new Promise((r) => setTimeout(r, 1400));
    setTxStep(2);
    setStage("done");
    onSwapped?.({ from: from.symbol, to: to.symbol, amountIn, amountOut });
  };

  const reset = () => {
    setStage("form");
    setTxStep(0);
    setAmount("");
  };

  const tokenCard = (
    which: "pay" | "receive",
    token: SwapToken,
    onToken: (t: SwapToken) => void
  ) => (
    <div
      ref={which === "pay" ? payRef : recvRef}
      className={cn(
        "rounded-2xl border bg-background/60 p-3.5 shadow-xs transition-colors duration-200",
        which === "pay" && insufficient ? "border-destructive/50" : "border-border/60"
      )}
    >
      <div className="flex items-center justify-between type-meta text-muted-foreground">
        <span>{which === "pay" ? "You pay" : "You receive"}</span>
        <button
          type="button"
          onClick={which === "pay" ? () => setAmount(String(token.balance)) : undefined}
          disabled={which !== "pay"}
          className={cn(
            "numeric",
            which === "pay" &&
              "underline-offset-2 hover:text-foreground hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          )}
        >
          Bal {fmt(token.balance, 4)}
          {which === "pay" ? " · MAX" : ""}
        </button>
      </div>
      <div className="mt-1.5 flex items-center justify-between gap-2">
        {which === "pay" ? (
          <input
            inputMode="decimal"
            aria-label="Amount to pay"
            value={amount}
            onChange={(e) => setAmount(e.target.value.replace(/[^0-9.]/g, ""))}
            placeholder="0.0"
            className="w-full min-w-0 bg-transparent type-metric numeric text-foreground placeholder:text-muted-foreground/50 focus-visible:outline-none"
          />
        ) : (
          <span className="truncate type-metric numeric text-foreground">
            {amountIn > 0 ? fmt(amountOut, token.usd > 100 ? 5 : 2) : "0.0"}
          </span>
        )}
        <TokenSelect
          tokens={tokens}
          value={token}
          exclude={which === "pay" ? to.symbol : from.symbol}
          onChange={onToken}
          label={which === "pay" ? "Pay token" : "Receive token"}
        />
      </div>
      <p className="mt-1 type-meta numeric text-muted-foreground">
        ≈ ${fmt((which === "pay" ? amountIn : amountOut) * token.usd, 2)}
        {which === "pay" && insufficient ? (
          <span className="ml-2 font-medium text-destructive">
            Insufficient balance
          </span>
        ) : null}
      </p>
    </div>
  );

  return (
    <div
      ref={rootRef}
      data-slot="crypto-swap"
      className={cn(
        "w-full max-w-sm rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      {stage !== "done" ? (
        <>
          <div className="relative flex flex-col gap-2">
            {tokenCard("pay", from, setFrom)}
            <button
              type="button"
              aria-label="Flip tokens"
              onClick={flip}
              className="group/flip absolute left-1/2 top-1/2 z-10 flex size-9 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-xl border-2 border-card bg-background text-muted-foreground shadow-md ring-1 ring-border/60 transition-[transform,color,box-shadow] duration-200 ease-out-expo hover:text-foreground hover:shadow-lg active:scale-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" className="size-4 transition-transform duration-300 ease-out-expo group-hover/flip:rotate-180 motion-reduce:group-hover/flip:rotate-0" aria-hidden="true">
                <path d="M7 4v16m0 0-3-3m3 3 3-3M17 20V4m0 0-3 3m3-3 3 3" />
              </svg>
            </button>
            {tokenCard("receive", to, setTo)}
          </div>

          {/* Quote summary */}
          <button
            type="button"
            aria-expanded={feesOpen}
            onClick={() => setFeesOpen((o) => !o)}
            className="mt-3 flex w-full items-center justify-between rounded-lg px-1 py-1 text-xs text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <span className="numeric">
              1 {from.symbol} = {fmt(q.rate, q.rate < 0.01 ? 6 : 4)} {to.symbol}
            </span>
            <span className="flex items-center gap-1 numeric">
              ${q.gasUsd.toFixed(2)} gas
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2}
                className={cn("size-3 transition-transform duration-300", feesOpen && "rotate-180")}
                aria-hidden="true"
              >
                <path d="m6 9 6 6 6-6" />
              </svg>
            </span>
          </button>
          <div ref={feesRef} className="overflow-hidden" style={{ height: 0, opacity: 0 }}>
            <dl className="flex flex-col gap-1.5 px-1 pb-1 pt-2 text-xs">
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Price impact</dt>
                <dd className={cn("numeric", q.priceImpact > 2 ? "text-warning" : "text-foreground")}>
                  {q.priceImpact.toFixed(2)}%
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Min received ({slippage}% slippage)</dt>
                <dd className="numeric text-foreground">
                  {fmt(minReceived, 5)} {to.symbol}
                </dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-muted-foreground">Slippage</dt>
                <dd className="flex gap-1">
                  {[0.1, 0.5, 1].map((s) => (
                    <button
                      key={s}
                      type="button"
                      aria-pressed={slippage === s}
                      onClick={() => setSlippage(s)}
                      className={cn(
                        "rounded px-1.5 py-0.5 numeric transition-colors duration-150",
                        slippage === s
                          ? "bg-primary text-primary-foreground"
                          : "bg-muted text-muted-foreground hover:text-foreground",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      )}
                    >
                      {s}%
                    </button>
                  ))}
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Route</dt>
                <dd className="flex items-center gap-1">
                  {q.route.map((hop, i) => (
                    <React.Fragment key={hop}>
                      {i > 0 ? (
                        <span aria-hidden="true" className="text-muted-foreground">→</span>
                      ) : null}
                      <span className="rounded bg-muted px-1 py-0.5 type-caption font-medium text-foreground">
                        {hop}
                      </span>
                    </React.Fragment>
                  ))}
                </dd>
              </div>
            </dl>
          </div>

          <div className="mt-3">
            {needsApproval && amountIn > 0 && !insufficient ? (
              <Button
                className="w-full"
                loading={stage === "approving"}
                onClick={approve}
              >
                Approve {from.symbol}
              </Button>
            ) : (
              <Button
                className="w-full"
                disabled={amountIn <= 0 || insufficient}
                loading={stage === "swapping"}
                onClick={swap}
              >
                {insufficient ? "Insufficient balance" : "Swap"}
              </Button>
            )}
            {needsApproval && amountIn > 0 && !insufficient ? (
              <p className="mt-1.5 text-center type-meta text-muted-foreground">
                One-time token approval, then the swap transaction.
              </p>
            ) : null}
          </div>
        </>
      ) : (
        <TxTimeline
          from={from}
          to={to}
          amountIn={amountIn}
          amountOut={amountOut}
          step={txStep}
          onReset={reset}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Confirmation timeline                                                */
/* ------------------------------------------------------------------ */

const TX_STEPS = ["Submitted", "Pending on-chain", "Confirmed"] as const;

function TxTimeline({
  from,
  to,
  amountIn,
  amountOut,
  step,
  onReset,
}: {
  from: SwapToken;
  to: SwapToken;
  amountIn: number;
  amountOut: number;
  step: number;
  onReset: () => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 14, filter: "blur(8px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.45, ease: "power3.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );

  return (
    <div ref={ref} className="flex flex-col gap-4 py-2">
      <div className="text-center">
        <p className="type-title text-foreground">
          {fmt(amountIn)} {from.symbol} → {fmt(amountOut, 5)} {to.symbol}
        </p>
        <p className="mt-0.5 type-meta text-muted-foreground">
          Swap complete · tx 0x3f8a…c21d
        </p>
      </div>
      <ol className="flex flex-col gap-0">
        {TX_STEPS.map((label, i) => {
          const done = step > i || (i === TX_STEPS.length - 1 && step >= i);
          const active = step === i && i < TX_STEPS.length - 1;
          return (
            <li key={label} className="flex gap-3">
              <div className="flex flex-col items-center">
                <span
                  className={cn(
                    "flex size-5 items-center justify-center rounded-full type-caption",
                    done
                      ? "bg-success text-white"
                      : active
                        ? "bg-primary/15"
                        : "bg-muted"
                  )}
                >
                  {done ? (
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true">
                      <path d="M5 13l4 4L19 7" />
                    </svg>
                  ) : active ? (
                    <Spinner size="sm" />
                  ) : null}
                </span>
                {i < TX_STEPS.length - 1 ? (
                  <span className={cn("my-0.5 h-5 w-px", done ? "bg-success" : "bg-border")} />
                ) : null}
              </div>
              <span
                className={cn(
                  "pt-0.5 text-sm",
                  done ? "text-foreground" : "text-muted-foreground"
                )}
              >
                {label}
              </span>
            </li>
          );
        })}
      </ol>
      <Button variant="outline" onClick={onReset}>
        New swap
      </Button>
    </div>
  );
}

registry/default/ai/agent-canvas.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Spinner } from "@/registry/default/ui/spinner";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface AgentToolCall {
  tool: string;
  args: string;
  /** Simulated duration in ms. */
  duration?: number;
  result?: string;
  /** First run fails with this error; a retry succeeds. */
  failsOnceWith?: string;
}

export interface AgentStep {
  id: string;
  title: string;
  toolCalls?: AgentToolCall[];
  /** Pause and require human approval before running. */
  approval?: { summary: string };
}

export type AgentRunStatus =
  | "idle"
  | "running"
  | "waiting-approval"
  | "error"
  | "complete"
  | "rejected";

export interface AgentCanvasProps
  extends React.HTMLAttributes<HTMLDivElement> {
  goal: string;
  steps: AgentStep[];
  /** Begin executing on mount. Default false — shows the plan first. */
  autoStart?: boolean;
  /** Rendered when the run completes. */
  artifact?: React.ReactNode;
  onStatusChange?: (status: AgentRunStatus) => void;
  ref?: React.Ref<HTMLDivElement>;
}

type StepState = "pending" | "active" | "done" | "error" | "waiting";
const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

const STATUS_META: Record<AgentRunStatus, { label: string; tone: string; pulse?: boolean }> = {
  idle: { label: "Plan ready", tone: "text-muted-foreground" },
  running: { label: "Running", tone: "text-agent-active", pulse: true },
  "waiting-approval": { label: "Waiting for approval", tone: "text-agent-waiting", pulse: true },
  error: { label: "Error — retry available", tone: "text-agent-error" },
  complete: { label: "Complete", tone: "text-success" },
  rejected: { label: "Stopped by user", tone: "text-muted-foreground" },
};

/* ------------------------------------------------------------------ */
/* Bits                                                                 */
/* ------------------------------------------------------------------ */

function StepDot({ state }: { state: StepState }) {
  return (
    <span
      className={cn(
        "relative mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full border-2 transition-colors duration-300",
        state === "done" && "border-success bg-success text-white",
        state === "active" && "border-agent-active",
        state === "waiting" && "border-agent-waiting",
        state === "error" && "border-agent-error bg-agent-error text-white",
        state === "pending" && "border-border bg-background shadow-xs"
      )}
    >
      {state === "done" ? (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true">
          <path d="M5 13l4 4L19 7" />
        </svg>
      ) : null}
      {state === "error" ? (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" className="size-3" aria-hidden="true">
          <path d="M18 6 6 18M6 6l12 12" />
        </svg>
      ) : null}
      {state === "active" || state === "waiting" ? (
        <>
          <span
            className={cn(
              "absolute inline-flex size-2.5 animate-ping rounded-full opacity-60",
              state === "active" ? "bg-agent-active" : "bg-agent-waiting"
            )}
          />
          <span
            className={cn(
              "size-2 rounded-full",
              state === "active" ? "bg-agent-active" : "bg-agent-waiting"
            )}
          />
        </>
      ) : null}
    </span>
  );
}

function ToolCallRow({
  call,
  state,
  error,
}: {
  call: AgentToolCall;
  state: "pending" | "running" | "done" | "error";
  error?: string;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 8, filter: "blur(4px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.3, ease: "power2.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );

  return (
    <div
      ref={ref}
      className="flex items-start gap-2 rounded-lg border border-border/70 bg-muted/40 px-2.5 py-1.5 font-mono type-meta leading-5"
    >
      <span className="mt-1">
        {state === "running" ? (
          <Spinner size="sm" />
        ) : state === "done" ? (
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3 text-success" aria-hidden="true">
            <path d="M5 13l4 4L19 7" />
          </svg>
        ) : state === "error" ? (
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" className="size-3 text-agent-error" aria-hidden="true">
            <path d="M18 6 6 18M6 6l12 12" />
          </svg>
        ) : (
          <span className="block size-3 rounded-full border border-border" />
        )}
      </span>
      <div className="min-w-0 flex-1">
        <p className="truncate">
          <span className="font-semibold text-foreground">{call.tool}</span>
          <span className="text-muted-foreground">({call.args})</span>
        </p>
        {state === "done" && call.result ? (
          <p className="truncate text-muted-foreground">→ {call.result}</p>
        ) : null}
        {state === "error" && error ? (
          <p className="truncate text-agent-error">✕ {error}</p>
        ) : null}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Canvas                                                               */
/* ------------------------------------------------------------------ */

export function AgentCanvas({
  goal,
  steps,
  autoStart = false,
  artifact,
  onStatusChange,
  className,
  ref,
  ...rest
}: AgentCanvasProps) {
  const reduced = useReducedMotion();
  const [status, setStatusRaw] = React.useState<AgentRunStatus>("idle");
  const [stepIdx, setStepIdx] = React.useState(-1);
  const [callIdx, setCallIdx] = React.useState(-1);
  const [failedOnce, setFailedOnce] = React.useState<Record<string, boolean>>({});
  const [errorMsg, setErrorMsg] = React.useState<string | null>(null);
  const runToken = React.useRef(0);

  const setStatus = (s: AgentRunStatus) => {
    setStatusRaw(s);
    onStatusChange?.(s);
  };

  const stepState = (i: number): StepState => {
    if (status === "complete" || i < stepIdx) return "done";
    if (i > stepIdx) return "pending";
    if (status === "waiting-approval") return "waiting";
    if (status === "error") return "error";
    if (status === "running") return "active";
    return "pending";
  };

  const runFrom = React.useCallback(
    async (startStep: number, startCall: number) => {
      const token = ++runToken.current;
      setStatus("running");
      setErrorMsg(null);
      for (let i = startStep; i < steps.length; i++) {
        if (runToken.current !== token) return;
        const step = steps[i];
        setStepIdx(i);
        if (step.approval && !(startStep === i && startCall > -1)) {
          setCallIdx(-1);
          setStatus("waiting-approval");
          return; // resumes via approve()
        }
        const calls = step.toolCalls ?? [];
        for (let c = i === startStep ? Math.max(0, startCall) : 0; c < calls.length; c++) {
          if (runToken.current !== token) return;
          setCallIdx(c);
          await wait(calls[c].duration ?? 900);
          if (runToken.current !== token) return;
          const key = `${step.id}:${c}`;
          if (calls[c].failsOnceWith && !failedOnce[key]) {
            setFailedOnce((f) => ({ ...f, [key]: true }));
            setErrorMsg(calls[c].failsOnceWith ?? "Tool failed");
            setStatus("error");
            return;
          }
        }
        setCallIdx(calls.length);
      }
      setStepIdx(steps.length);
      setStatus("complete");
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [steps, failedOnce]
  );

  React.useEffect(() => {
    if (autoStart) runFrom(0, -1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoStart]);

  const approve = () => {
    // continue current step's tool calls after the gate
    runFrom(stepIdx, 0);
  };
  const reject = () => {
    runToken.current++;
    setStatus("rejected");
  };
  const retry = () => runFrom(stepIdx, callIdx);

  const meta = STATUS_META[status];

  return (
    <div
      ref={ref}
      data-slot="agent-canvas"
      className={cn(
        "w-full max-w-lg overflow-hidden rounded-3xl border border-border/60 bg-card shadow-md",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex items-start justify-between gap-3 border-b border-border/60 bg-muted/20 px-5 py-3.5">
        <div className="min-w-0">
          <p className="type-overline text-muted-foreground">
            Goal
          </p>
          <p className="truncate text-sm font-medium text-foreground">{goal}</p>
        </div>
        <span className={cn("flex shrink-0 items-center gap-1.5 text-xs font-medium", meta.tone)}>
          {meta.pulse ? (
            <span className="relative flex size-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-current opacity-50" />
              <span className="relative inline-flex size-2 rounded-full bg-current" />
            </span>
          ) : null}
          {meta.label}
        </span>
      </div>

      {/* Timeline */}
      <ol className="flex flex-col px-5 py-4">
        {steps.map((step, i) => {
          const state = stepState(i);
          const calls = step.toolCalls ?? [];
          return (
            <li key={step.id} className="relative flex gap-3 pb-4 last:pb-0">
              {i < steps.length - 1 ? (
                <span
                  aria-hidden="true"
                  className={cn(
                    "absolute left-[9px] top-6 h-[calc(100%-1.25rem)] w-0.5 rounded transition-colors duration-500",
                    state === "done" ? "bg-success/50" : "bg-border"
                  )}
                />
              ) : null}
              <StepDot state={state} />
              <div className="min-w-0 flex-1">
                <p
                  className={cn(
                    "text-sm",
                    state === "pending" ? "text-muted-foreground" : "font-medium text-foreground"
                  )}
                >
                  {step.title}
                </p>

                {/* Tool calls appear as the step executes */}
                {(state === "active" || state === "error") && calls.length > 0 ? (
                  <div className="mt-1.5 flex flex-col gap-1">
                    {calls.slice(0, Math.max(0, callIdx + 1)).map((call, c) => (
                      <ToolCallRow
                        key={c}
                        call={call}
                        state={
                          status === "error" && c === callIdx
                            ? "error"
                            : c < callIdx
                              ? "done"
                              : "running"
                        }
                        error={errorMsg ?? undefined}
                      />
                    ))}
                  </div>
                ) : null}
                {state === "done" && calls.length > 0 ? (
                  <p className="mt-0.5 type-meta text-muted-foreground">
                    {calls.length} tool call{calls.length > 1 ? "s" : ""} ·{" "}
                    {calls.map((c) => c.tool).join(", ")}
                  </p>
                ) : null}

                {/* Approval gate */}
                {state === "waiting" && step.approval ? (
                  <div className="mt-2 rounded-lg border border-agent-waiting/40 bg-agent-waiting/10 p-2.5">
                    <p className="text-xs text-foreground">{step.approval.summary}</p>
                    <div className="mt-2 flex gap-2">
                      <Button size="sm" onClick={approve}>
                        Approve
                      </Button>
                      <Button size="sm" variant="outline" onClick={reject}>
                        Reject
                      </Button>
                    </div>
                  </div>
                ) : null}

                {/* Retry */}
                {state === "error" ? (
                  <div className="mt-2">
                    <Button size="sm" variant="outline" onClick={retry}>
                      Retry step
                    </Button>
                  </div>
                ) : null}
              </div>
            </li>
          );
        })}
      </ol>

      {/* Footer: start / artifact */}
      <div className="border-t border-border/60 px-5 py-3.5">
        {status === "idle" ? (
          <Button className="w-full" onClick={() => runFrom(0, -1)}>
            Run plan
          </Button>
        ) : null}
        {status === "rejected" ? (
          <Button className="w-full" variant="outline" onClick={() => runFrom(stepIdx, -1)}>
            Resume run
          </Button>
        ) : null}
        {status === "complete" ? (
          artifact ? (
            <ArtifactReveal reduced={reduced}>{artifact}</ArtifactReveal>
          ) : (
            <p className="text-center text-xs text-success">Run complete</p>
          )
        ) : null}
        {status === "running" || status === "waiting-approval" || status === "error" ? (
          <p className="text-center type-meta numeric text-muted-foreground">
            step {Math.min(stepIdx + 1, steps.length)}/{steps.length} · 12.4k tokens · $0.08
          </p>
        ) : null}
      </div>
    </div>
  );
}

function ArtifactReveal({
  children,
  reduced,
}: {
  children: React.ReactNode;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 12, filter: "blur(8px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.45, ease: "power3.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );
  return (
    <div ref={ref}>
      <p className="mb-2 type-overline text-muted-foreground">
        Artifact
      </p>
      {children}
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface Holding {
  symbol: string;
  name: string;
  sector: string;
  value: number;
  /** Stock beta vs the index. */
  beta: number;
  dayChangePct: number;
}

export const DEMO_HOLDINGS: Holding[] = [
  { symbol: "HDFCBANK", name: "HDFC Bank", sector: "Financials", value: 412000, beta: 1.05, dayChangePct: 0.6 },
  { symbol: "ICICIBANK", name: "ICICI Bank", sector: "Financials", value: 268000, beta: 1.12, dayChangePct: -0.3 },
  { symbol: "INFY", name: "Infosys", sector: "IT", value: 236000, beta: 0.85, dayChangePct: 1.2 },
  { symbol: "TCS", name: "TCS", sector: "IT", value: 158000, beta: 0.8, dayChangePct: 0.4 },
  { symbol: "RELIANCE", name: "Reliance", sector: "Energy", value: 301000, beta: 1.1, dayChangePct: -0.8 },
  { symbol: "SUNPHARMA", name: "Sun Pharma", sector: "Pharma", value: 92000, beta: 0.6, dayChangePct: 0.9 },
  { symbol: "DMART", name: "Avenue Supermarts", sector: "Consumer", value: 74000, beta: 0.7, dayChangePct: -1.1 },
];

export interface PortfolioRiskProps
  extends React.HTMLAttributes<HTMLDivElement> {
  holdings?: Holding[];
  /** Concentration warning threshold as a fraction of portfolio. Default 0.25. */
  concentrationLimit?: number;
  ref?: React.Ref<HTMLDivElement>;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);

// Categorical allocation palette, tuned to read in both themes.
const SECTOR_HUES = [
  "217 91% 60%", // indigo
  "258 90% 66%", // violet
  "173 80% 40%", // teal
  "38 92% 50%", // amber
  "330 81% 60%", // rose
  "199 89% 48%", // cyan
];

/* ------------------------------------------------------------------ */
/* Cockpit                                                              */
/* ------------------------------------------------------------------ */

export function PortfolioRisk({
  holdings = DEMO_HOLDINGS,
  concentrationLimit = 0.25,
  className,
  ref,
  ...rest
}: PortfolioRiskProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [shock, setShock] = React.useState(0); // NIFTY move in %, negative = down
  const [active, setActive] = React.useState<string | null>(null);

  const total = holdings.reduce((s, h) => s + h.value, 0);
  const beta = holdings.reduce((s, h) => s + h.beta * h.value, 0) / total;
  const dayPnl = holdings.reduce((s, h) => s + (h.dayChangePct / 100) * h.value, 0);
  const dayPnlPct = (dayPnl / total) * 100;
  // 1-day 95% parametric VaR with ~1% daily index vol scaled by beta
  const var95 = total * beta * 0.01 * 1.65;

  const sectors = React.useMemo(() => {
    const map = new Map<string, number>();
    for (const h of holdings) map.set(h.sector, (map.get(h.sector) ?? 0) + h.value);
    return [...map.entries()]
      .map(([sector, value]) => ({ sector, value, share: value / total }))
      .sort((a, b) => b.value - a.value)
      .map((s, i) => ({ ...s, hue: SECTOR_HUES[i % SECTOR_HUES.length] }));
  }, [holdings, total]);

  // Cumulative offsets so segments lay out along one bar.
  const laidOut = React.useMemo(() => {
    let acc = 0;
    return sectors.map((s) => {
      const left = acc;
      acc += s.share;
      return { ...s, left };
    });
  }, [sectors]);

  const topConcentration = sectors[0];
  const concentrated = topConcentration.share > concentrationLimit;
  const shockImpact = total * beta * (shock / 100);

  // Stress slider geometry: 0% sits where "no move" falls in the range.
  const SHOCK_MIN = -10;
  const SHOCK_MAX = 5;
  const posOf = (v: number) => ((v - SHOCK_MIN) / (SHOCK_MAX - SHOCK_MIN)) * 100;
  const zeroPos = posOf(0);
  const thumbPos = posOf(shock);
  const fillLeft = Math.min(zeroPos, thumbPos);
  const fillWidth = Math.abs(thumbPos - zeroPos);
  const stressDown = shock < 0;

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const segs = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-seg]"));
      const legend = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-legend]"));
      if (reduced) {
        gsap.set(segs, { scaleX: 1, opacity: 1 });
        gsap.set(legend, { y: 0, opacity: 1 });
        return;
      }
      gsap.set(segs, { transformOrigin: "left center" });
      gsap
        .timeline()
        .fromTo(
          segs,
          { scaleX: 0, opacity: 0.4 },
          { scaleX: 1, opacity: 1, duration: 0.75, ease: "expo.out", stagger: 0.07 }
        )
        .fromTo(
          legend,
          { y: 6, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.4, ease: "power3.out", stagger: 0.04 },
          0.35
        );
    },
    { dependencies: [reduced, holdings], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="portfolio-risk"
      className={cn(
        "group/card relative w-full max-w-2xl overflow-hidden rounded-3xl border border-border/60 bg-card p-6 shadow-md",
        className
      )}
      {...rest}
    >
      {/* Ambient top sheen */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 -top-24 h-40 bg-[radial-gradient(60%_100%_at_50%_100%,hsl(var(--elevation-hue)/0.05),transparent)] dark:bg-[radial-gradient(60%_100%_at_50%_100%,hsl(0_0%_100%/0.04),transparent)]"
      />

      {/* ---- Hero: value + day P&L ---------------------------------- */}
      <div className="relative flex flex-wrap items-start justify-between gap-4">
        <div>
          <p className="tracking-[0.1em] type-overline text-muted-foreground">
            Portfolio value
          </p>
          <div className="mt-1.5 flex flex-wrap items-center gap-2.5">
            <span className="text-4xl font-semibold leading-none tracking-tight text-foreground numeric">
              <NumberFlow value={total} prefix="₹" locale="en-IN" />
            </span>
            <span
              className={cn(
                "inline-flex items-center gap-1 rounded-full px-2 py-1 text-xs font-medium numeric ring-1 ring-inset",
                dayPnl >= 0
                  ? "bg-market-up/10 text-market-up ring-market-up/20"
                  : "bg-market-down/10 text-market-down ring-market-down/20"
              )}
            >
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
                className={cn("size-3", dayPnl < 0 && "rotate-180")}
                aria-hidden="true"
              >
                <path d="M12 19V5M5 12l7-7 7 7" />
              </svg>
              {dayPnl >= 0 ? "+₹" : "−₹"}
              {inr(Math.abs(Math.round(dayPnl)))}
              <span className="opacity-60">· {Math.abs(dayPnlPct).toFixed(2)}%</span>
            </span>
          </div>
          <p className="mt-1.5 text-xs text-muted-foreground">
            {holdings.length} holdings · updated just now
          </p>
        </div>

        {/* Risk chips */}
        <div className="flex items-stretch gap-5 rounded-2xl border border-border/60 bg-background/60 px-4 py-2.5 backdrop-blur-sm">
          <div>
            <p className="type-overline text-muted-foreground">
              Beta
            </p>
            <p className="mt-0.5 text-lg font-semibold numeric text-foreground">
              <NumberFlow value={beta} decimals={2} />
            </p>
            <p className="type-caption text-muted-foreground">vs NIFTY 50</p>
          </div>
          <div className="w-px bg-border/60" />
          <div>
            <p className="type-overline text-muted-foreground">
              VaR 95% · 1d
            </p>
            <p className="mt-0.5 text-lg font-semibold numeric text-risk-high">
              ₹<NumberFlow value={Math.round(var95)} locale="en-IN" />
            </p>
            <p className="type-caption text-muted-foreground">
              {((var95 / total) * 100).toFixed(1)}% of value
            </p>
          </div>
        </div>
      </div>

      {/* ---- Allocation: one segmented bar + interactive legend ------ */}
      <div className="relative mt-7">
        <div className="flex items-baseline justify-between">
          <h3 className="type-title text-foreground">Allocation</h3>
          {concentrated ? (
            <span className="inline-flex items-center gap-1.5 type-meta font-medium text-warning">
              <span className="relative flex size-1.5">
                <span className="absolute inline-flex size-full animate-ping rounded-full bg-warning/60" />
                <span className="relative inline-flex size-1.5 rounded-full bg-warning" />
              </span>
              Concentrated
            </span>
          ) : null}
        </div>

        {/* Segmented bar */}
        <div
          className="relative mt-3 h-3.5 w-full"
          role="img"
          aria-label={`Sector allocation: ${sectors
            .map((s) => `${s.sector} ${(s.share * 100).toFixed(0)}%`)
            .join(", ")}`}
        >
          {laidOut.map((s) => {
            const isActive = active === s.sector;
            const dim = active != null && !isActive;
            return (
              <div
                key={s.sector}
                data-seg
                onMouseEnter={() => setActive(s.sector)}
                onMouseLeave={() => setActive(null)}
                className={cn(
                  "absolute top-0 h-full cursor-default rounded-full transition-[opacity,transform,box-shadow] duration-300",
                  dim ? "opacity-40" : "opacity-100",
                  isActive && "shadow-[0_0_0_1px_var(--card),0_4px_12px_-2px_var(--seg-shadow)]"
                )}
                style={
                  {
                    left: `calc(${s.left * 100}% + ${s.left > 0 ? 3 : 0}px)`,
                    width: `calc(${s.share * 100}% - 3px)`,
                    background: `linear-gradient(180deg, hsl(${s.hue} / 0.92), hsl(${s.hue}))`,
                    transform: isActive ? "scaleY(1.25)" : "scaleY(1)",
                    "--seg-shadow": `hsl(${s.hue} / 0.5)`,
                  } as React.CSSProperties
                }
              />
            );
          })}
        </div>

        {/* Legend */}
        <ul className="mt-4 flex flex-wrap gap-x-5 gap-y-2.5">
          {laidOut.map((s) => {
            const isActive = active === s.sector;
            const dim = active != null && !isActive;
            const over = s.share > concentrationLimit;
            return (
              <li
                key={s.sector}
                data-legend
                onMouseEnter={() => setActive(s.sector)}
                onMouseLeave={() => setActive(null)}
                className={cn(
                  "flex cursor-default items-center gap-2 transition-opacity duration-200",
                  dim && "opacity-45"
                )}
              >
                <span
                  className="size-2.5 shrink-0 rounded-[4px] transition-transform duration-200"
                  style={{
                    background: `hsl(${s.hue})`,
                    transform: isActive ? "scale(1.25)" : "scale(1)",
                  }}
                />
                <span className="text-xs font-medium text-foreground">{s.sector}</span>
                <span
                  className={cn(
                    "text-xs numeric",
                    over ? "font-semibold text-warning" : "text-muted-foreground"
                  )}
                >
                  {(s.share * 100).toFixed(1)}%
                </span>
              </li>
            );
          })}
        </ul>

        {concentrated ? (
          <div className="mt-4 flex items-start gap-2.5 rounded-2xl border border-warning/25 bg-warning/[0.06] px-3.5 py-3">
            <svg
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={2}
              strokeLinecap="round"
              strokeLinejoin="round"
              className="mt-px size-4 shrink-0 text-warning"
              aria-hidden="true"
            >
              <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
              <path d="M12 9v4M12 17h.01" />
            </svg>
            <p className="type-label leading-5 text-foreground">
              <span className="font-semibold">{topConcentration.sector}</span> is{" "}
              {(topConcentration.share * 100).toFixed(0)}% of the portfolio, above your{" "}
              {(concentrationLimit * 100).toFixed(0)}% limit. Trimming it lowers single-sector risk.
            </p>
          </div>
        ) : null}
      </div>

      {/* ---- Stress test: custom slider ----------------------------- */}
      <div className="relative mt-7 rounded-2xl border border-border/60 bg-background/50 p-4">
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <h3 className="type-title text-foreground">Stress test</h3>
            <span className="type-meta text-muted-foreground">β-scaled impact</span>
          </div>
          <span
            className={cn(
              "rounded-lg px-2 py-1 text-xs font-semibold numeric ring-1 ring-inset transition-colors duration-300",
              shock === 0
                ? "bg-muted/60 text-muted-foreground ring-border/60"
                : stressDown
                  ? "bg-market-down/10 text-market-down ring-market-down/20"
                  : "bg-market-up/10 text-market-up ring-market-up/20"
            )}
          >
            NIFTY {shock >= 0 ? "+" : ""}
            {shock.toFixed(1)}%
          </span>
        </div>

        {/* Slider */}
        <div className="relative mt-4 h-6">
          <style>{`
            #stress-${uid}::-webkit-slider-thumb { -webkit-appearance: none; width: 28px; height: 28px; cursor: grab; }
            #stress-${uid}:active::-webkit-slider-thumb { cursor: grabbing; }
            #stress-${uid}::-moz-range-thumb { width: 28px; height: 28px; border: 0; background: transparent; cursor: grab; }
          `}</style>
          {/* track */}
          <div className="pointer-events-none absolute inset-x-0 top-1/2 h-2 -translate-y-1/2 rounded-full bg-muted ring-1 ring-inset ring-border/50" />
          {/* fill */}
          <div
            className="pointer-events-none absolute top-1/2 h-2 -translate-y-1/2 rounded-full transition-[background] duration-300"
            style={{
              left: `${fillLeft}%`,
              width: `${fillWidth}%`,
              background: stressDown
                ? "linear-gradient(270deg, color-mix(in oklab, var(--market-down) 55%, transparent), var(--market-down))"
                : "linear-gradient(90deg, color-mix(in oklab, var(--market-up) 55%, transparent), var(--market-up))",
            }}
          />
          {/* zero tick */}
          <div
            className="pointer-events-none absolute top-1/2 h-3.5 w-px -translate-x-1/2 -translate-y-1/2 rounded-full bg-border"
            style={{ left: `${zeroPos}%` }}
          />
          {/* native input (a11y + keyboard + pointer), transparent on top */}
          <input
            id={`stress-${uid}`}
            type="range"
            min={SHOCK_MIN}
            max={SHOCK_MAX}
            step={0.5}
            value={shock}
            aria-label="Index shock scenario in percent"
            onChange={(e) => setShock(parseFloat(e.target.value))}
            className="peer absolute inset-0 z-20 w-full cursor-pointer appearance-none bg-transparent opacity-0"
          />
          {/* thumb */}
          <div
            className={cn(
              "pointer-events-none absolute top-1/2 z-10 size-5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 bg-background shadow-md transition-[border-color,box-shadow] duration-300",
              "peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-background",
              shock === 0
                ? "border-muted-foreground/60"
                : stressDown
                  ? "border-market-down"
                  : "border-market-up"
            )}
            style={{ left: `${thumbPos}%` }}
          />
        </div>

        <div className="mt-4 flex items-end justify-between">
          <span className="type-meta text-muted-foreground">
            Estimated portfolio impact
          </span>
          <span
            className={cn(
              "type-metric numeric transition-colors duration-300",
              shock === 0
                ? "text-muted-foreground"
                : shockImpact >= 0
                  ? "text-market-up"
                  : "text-market-down"
            )}
          >
            <NumberFlow
              value={Math.abs(Math.round(shockImpact))}
              prefix={shock === 0 ? "₹" : shockImpact >= 0 ? "+₹" : "−₹"}
              locale="en-IN"
            />
          </span>
        </div>

        {shock <= -5 ? (
          <p className="mt-3 rounded-xl bg-muted/60 px-3 py-2 type-meta leading-4 text-foreground">
            <span className="font-semibold">Hedge idea:</span> a NIFTY put ~5% below spot
            (β-weighted ₹{inr(Math.round(total * beta))} exposure) caps this scenario near ₹
            {inr(Math.round(Math.abs(shockImpact) * 0.4))}. Educational, not advice.
          </p>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface BiomarkerReading {
  date: string; // ISO date
  value: number;
}

export interface BiomarkerEvent {
  date: string;
  label: string;
}

export interface BiomarkerTrendProps
  extends React.HTMLAttributes<HTMLDivElement> {
  name: string;
  unit: string;
  readings: BiomarkerReading[];
  /** Laboratory reference range in primary units. */
  range: { low: number; high: number };
  /** Personal baseline (median of historical normals). */
  baseline?: number;
  events?: BiomarkerEvent[];
  /** Optional secondary unit, e.g. mmol/L for a mg/dL marker. */
  altUnit?: { unit: string; factor: number };
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_LDL: Omit<BiomarkerTrendProps, keyof React.HTMLAttributes<HTMLDivElement>> = {
  name: "LDL cholesterol",
  unit: "mg/dL",
  range: { low: 50, high: 130 },
  baseline: 112,
  altUnit: { unit: "mmol/L", factor: 0.02586 },
  readings: [
    { date: "2025-01-14", value: 118 },
    { date: "2025-03-02", value: 127 },
    { date: "2025-05-20", value: 149 },
    { date: "2025-07-11", value: 158 },
    { date: "2025-09-05", value: 141 },
    { date: "2025-11-19", value: 122 },
    { date: "2026-01-24", value: 108 },
    { date: "2026-04-02", value: 101 },
  ],
  events: [{ date: "2025-08-01", label: "Statin started" }],
};

const short = (iso: string) =>
  new Date(iso).toLocaleDateString("en-GB", { month: "short", year: "2-digit" });

/* ------------------------------------------------------------------ */
/* Explorer                                                             */
/* ------------------------------------------------------------------ */

const W = 560;
const H = 220;
const PAD = { l: 40, r: 12, t: 14, b: 26 };

export function BiomarkerTrend({
  name,
  unit,
  readings,
  range,
  baseline,
  events = [],
  altUnit,
  className,
  ref,
  ...rest
}: BiomarkerTrendProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const pathRef = React.useRef<SVGPathElement>(null);
  const areaRef = React.useRef<SVGPathElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [useAlt, setUseAlt] = React.useState(false);
  const [selected, setSelected] = React.useState<number | null>(
    readings.length - 1
  );

  const factor = useAlt && altUnit ? altUnit.factor : 1;
  const displayUnit = useAlt && altUnit ? altUnit.unit : unit;
  const decimals = useAlt && altUnit ? 2 : 0;
  const fmtVal = (v: number) => (v * factor).toFixed(decimals);

  const t0 = new Date(readings[0].date).getTime();
  const t1 = new Date(readings[readings.length - 1].date).getTime();
  const values = readings.map((r) => r.value);
  const vMin = Math.min(...values, range.low) * 0.9;
  const vMax = Math.max(...values, range.high) * 1.06;

  const x = (iso: string) =>
    PAD.l + ((new Date(iso).getTime() - t0) / (t1 - t0)) * (W - PAD.l - PAD.r);
  const y = (v: number) =>
    H - PAD.b - ((v - vMin) / (vMax - vMin)) * (H - PAD.t - PAD.b);

  const line = readings
    .map((r, i) => `${i === 0 ? "M" : "L"}${x(r.date).toFixed(1)},${y(r.value).toFixed(1)}`)
    .join(" ");
  const area = `${line} L${x(readings[readings.length - 1].date).toFixed(1)},${(H - PAD.b).toFixed(1)} L${x(readings[0].date).toFixed(1)},${(H - PAD.b).toFixed(1)} Z`;

  /* The trend draws itself once, then the area fades up beneath it. */
  useGSAP(
    () => {
      const p = pathRef.current;
      const a = areaRef.current;
      if (!p) return;
      const len = p.getTotalLength();
      if (reduced) {
        gsap.set(p, { strokeDasharray: "none", strokeDashoffset: 0 });
        if (a) gsap.set(a, { opacity: 1 });
        return;
      }
      if (a) gsap.set(a, { opacity: 0 });
      gsap.fromTo(
        p,
        { strokeDasharray: len, strokeDashoffset: len },
        { strokeDashoffset: 0, duration: 1.2, ease: "power2.inOut" }
      );
      if (a) gsap.to(a, { opacity: 1, duration: 0.6, delay: 0.7 });
    },
    { dependencies: [reduced], scope: rootRef }
  );

  const sel = selected != null ? readings[selected] : null;
  const selAbnormal = sel != null && (sel.value > range.high || sel.value < range.low);
  const latest = readings[readings.length - 1];
  const prev = readings[readings.length - 2];
  const trendPct = prev ? ((latest.value - prev.value) / prev.value) * 100 : 0;

  return (
    <div
      ref={rootRef}
      data-slot="biomarker-trend"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <h3 className="type-title text-foreground">{name}</h3>
          <p className="type-meta text-muted-foreground">
            Lab range {fmtVal(range.low)}–{fmtVal(range.high)} {displayUnit}
            {baseline ? ` · your baseline ${fmtVal(baseline)}` : ""}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span
            className={cn(
              "text-xs font-medium numeric",
              trendPct <= 0 ? "text-success" : "text-warning"
            )}
          >
            {trendPct >= 0 ? "▲" : "▼"} {Math.abs(trendPct).toFixed(1)}% vs last
          </span>
          {altUnit ? (
            <button
              type="button"
              aria-pressed={useAlt}
              onClick={() => setUseAlt((a) => !a)}
              className="rounded-md border border-border px-2 py-0.5 type-meta font-medium text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {displayUnit}
            </button>
          ) : null}
        </div>
      </div>

      {/* Chart */}
      <div className="mt-3 overflow-x-auto">
        <svg
          viewBox={`0 0 ${W} ${H}`}
          role="img"
          aria-label={`${name} trend: ${readings.length} readings from ${short(readings[0].date)} to ${short(latest.date)}`}
          className="min-w-[420px]"
        >
          <defs>
            <linearGradient id={`bm-area-${uid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--info)" stopOpacity={0.24} />
              <stop offset="100%" stopColor="var(--info)" stopOpacity={0} />
            </linearGradient>
            <linearGradient id={`bm-band-${uid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--success)" stopOpacity={0.16} />
              <stop offset="100%" stopColor="var(--success)" stopOpacity={0.05} />
            </linearGradient>
            <filter id={`bm-glow-${uid}`} x="-10%" y="-40%" width="120%" height="180%">
              <feDropShadow dx="0" dy="1.5" stdDeviation="3" floodColor="var(--info)" floodOpacity="0.3" />
            </filter>
          </defs>

          {/* reference band */}
          <rect
            x={PAD.l}
            width={W - PAD.l - PAD.r}
            y={y(range.high)}
            height={y(range.low) - y(range.high)}
            rx={6}
            fill={`url(#bm-band-${uid})`}
          />
          <line
            x1={PAD.l}
            x2={W - PAD.r}
            y1={y(range.high)}
            y2={y(range.high)}
            className="stroke-success/25"
            strokeDasharray="3 3"
          />
          <text x={PAD.l + 4} y={y(range.high) + 11} className="fill-success text-[9px] font-medium">
            in range
          </text>

          {/* baseline */}
          {baseline ? (
            <>
              <line
                x1={PAD.l}
                x2={W - PAD.r}
                y1={y(baseline)}
                y2={y(baseline)}
                strokeDasharray="4 4"
                className="stroke-muted-foreground/50"
              />
              <text
                x={W - PAD.r - 2}
                y={y(baseline) - 3}
                textAnchor="end"
                className="fill-muted-foreground text-[9px]"
              >
                baseline
              </text>
            </>
          ) : null}

          {/* events */}
          {events.map((e) => (
            <g key={e.date}>
              <line
                x1={x(e.date)}
                x2={x(e.date)}
                y1={PAD.t}
                y2={H - PAD.b}
                className="stroke-info/50"
                strokeDasharray="2 3"
              />
              <text
                x={x(e.date) + 3}
                y={PAD.t + 8}
                className="fill-info text-[9px] font-medium"
              >
                {e.label}
              </text>
            </g>
          ))}

          {/* axis labels */}
          {[range.low, range.high].map((v) => (
            <text
              key={v}
              x={PAD.l - 5}
              y={y(v) + 3}
              textAnchor="end"
              className="fill-muted-foreground text-[9px] tabular-nums"
            >
              {fmtVal(v)}
            </text>
          ))}
          {readings.map((r, i) =>
            i % 2 === 0 ? (
              <text
                key={r.date}
                x={x(r.date)}
                y={H - 8}
                textAnchor="middle"
                className="fill-muted-foreground text-[9px]"
              >
                {short(r.date)}
              </text>
            ) : null
          )}

          {/* trend area + line */}
          <path ref={areaRef} d={area} fill={`url(#bm-area-${uid})`} opacity={0} />
          <path
            ref={pathRef}
            d={line}
            fill="none"
            stroke="var(--info)"
            strokeWidth={2.25}
            strokeLinecap="round"
            strokeLinejoin="round"
            filter={`url(#bm-glow-${uid})`}
          />

          {/* points */}
          {readings.map((r, i) => {
            const abnormal = r.value > range.high || r.value < range.low;
            const isSel = selected === i;
            return (
              <circle
                key={r.date}
                cx={x(r.date)}
                cy={y(r.value)}
                r={isSel ? 6 : 4}
                tabIndex={0}
                role="button"
                aria-label={`${short(r.date)}: ${fmtVal(r.value)} ${displayUnit}${abnormal ? ", outside range" : ""}`}
                onClick={() => setSelected(i)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    setSelected(i);
                  }
                }}
                className={cn(
                  "cursor-pointer transition-all duration-200 focus-visible:outline-none",
                  abnormal ? "fill-risk-high stroke-card" : "fill-info stroke-card",
                  isSel && "stroke-2"
                )}
                strokeWidth={isSel ? 2.5 : 1.5}
                style={
                  isSel
                    ? {
                        filter: `drop-shadow(0 0 5px color-mix(in oklab, ${abnormal ? "var(--risk-high)" : "var(--info)"} 60%, transparent))`,
                      }
                    : undefined
                }
              />
            );
          })}
        </svg>
      </div>

      {/* Selected reading */}
      {sel ? (
        <div
          className={cn(
            "mt-2 rounded-xl border p-3 text-sm transition-colors duration-300",
            selAbnormal ? "border-risk-high/40 bg-risk-high/5" : "border-border bg-background"
          )}
        >
          <div className="flex items-baseline justify-between gap-2">
            <span className="font-semibold numeric text-foreground">
              {fmtVal(sel.value)} {displayUnit}
            </span>
            <span className="text-xs text-muted-foreground">
              {new Date(sel.date).toLocaleDateString("en-GB", {
                day: "numeric",
                month: "long",
                year: "numeric",
              })}
            </span>
          </div>
          <p className="mt-1 type-meta leading-5 text-muted-foreground">
            {selAbnormal ? (
              <>
                Above the laboratory range. Single readings vary with fasting
                state and lab method — the trend matters more than one point.
                Discuss persistent elevation with your clinician; this view is
                informational, not a diagnosis.
              </>
            ) : (
              <>
                Within the laboratory range
                {baseline
                  ? sel.value <= baseline
                    ? " and at or below your personal baseline."
                    : ", slightly above your personal baseline."
                  : "."}
              </>
            )}
          </p>
        </div>
      ) : null}
    </div>
  );
}

registry/default/fintech/market-depth.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface DepthLevel {
  price: number;
  qty: number;
  orders: number;
}

export interface MarketDepthProps
  extends React.HTMLAttributes<HTMLDivElement> {
  symbol: string;
  /** Best-first (descending price) bid levels. */
  bids: DepthLevel[];
  /** Best-first (ascending price) ask levels. */
  asks: DepthLevel[];
  lastPrice: number;
  /** Average traded price marker. */
  atp?: number;
  onLevelSelect?: (side: "bid" | "ask", level: DepthLevel) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const nf = new Intl.NumberFormat("en-IN");
const nf2 = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

/** Deterministic demo ladder around a mid price. */
export function generateDepth(mid: number, tick = 0.05, levels = 7) {
  const mk = (side: 1 | -1): DepthLevel[] =>
    Array.from({ length: levels }, (_, i) => {
      const seed = Math.sin((mid + side * i) * 7.13) * 10_000;
      const r = seed - Math.floor(seed);
      return {
        price: +(mid + side * tick * (i + 1)).toFixed(2),
        qty: Math.round(300 + r * 4200),
        orders: 1 + Math.round(r * 14),
      };
    });
  return { bids: mk(-1), asks: mk(1) };
}

/* ------------------------------------------------------------------ */
/* Ladder                                                               */
/* ------------------------------------------------------------------ */

function Row({
  side,
  level,
  maxQty,
  best,
  onSelect,
}: {
  side: "bid" | "ask";
  level: DepthLevel;
  maxQty: number;
  best: boolean;
  onSelect?: (side: "bid" | "ask", level: DepthLevel) => void;
}) {
  const barRef = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const pct = Math.round((level.qty / maxQty) * 100);

  /* Qty bars breathe to their new size on every update. */
  useGSAP(
    () => {
      if (!barRef.current) return;
      if (reduced) {
        gsap.set(barRef.current, { width: `${pct}%` });
        return;
      }
      gsap.to(barRef.current, {
        width: `${pct}%`,
        duration: 0.7,
        ease: "power2.out",
        overwrite: "auto",
      });
    },
    { dependencies: [pct, reduced] }
  );

  return (
    <button
      type="button"
      onClick={() => onSelect?.(side, level)}
      aria-label={`${side} ${nf2.format(level.price)}, quantity ${nf.format(level.qty)}, ${level.orders} orders`}
      className={cn(
        "relative grid w-full grid-cols-[1fr_auto_auto] items-center gap-2 rounded-md px-2 py-1 text-right font-mono type-meta numeric transition-colors duration-150",
        "hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
        best && "font-semibold"
      )}
    >
      <span
        ref={barRef}
        aria-hidden="true"
        className={cn("absolute inset-y-0.5 rounded-md", side === "bid" ? "right-0" : "left-0")}
        style={{
          width: 0,
          background:
            side === "bid"
              ? "linear-gradient(270deg, color-mix(in oklab, var(--bid) 26%, transparent), color-mix(in oklab, var(--bid) 6%, transparent))"
              : "linear-gradient(90deg, color-mix(in oklab, var(--ask) 26%, transparent), color-mix(in oklab, var(--ask) 6%, transparent))",
        }}
      />
      <span className="relative text-left text-muted-foreground">
        {level.orders}
      </span>
      <span className="relative text-muted-foreground">{nf.format(level.qty)}</span>
      <span
        className={cn(
          "relative w-16",
          side === "bid" ? "text-bid" : "text-ask"
        )}
      >
        {nf2.format(level.price)}
      </span>
    </button>
  );
}

/**
 * Live bid/ask depth ladder: quantity bars grow from the outside in,
 * the spread sits in the middle, and last price flashes directionally.
 */
export function MarketDepth({
  symbol,
  bids,
  asks,
  lastPrice,
  atp,
  onLevelSelect,
  className,
  ref,
  ...rest
}: MarketDepthProps) {
  const reduced = useReducedMotion();
  const prevLast = React.useRef(lastPrice);
  const [flash, setFlash] = React.useState<"up" | "down" | null>(null);

  React.useEffect(() => {
    if (reduced || lastPrice === prevLast.current) {
      prevLast.current = lastPrice;
      return;
    }
    setFlash(lastPrice > prevLast.current ? "up" : "down");
    prevLast.current = lastPrice;
    const t = setTimeout(() => setFlash(null), 600);
    return () => clearTimeout(t);
  }, [lastPrice, reduced]);

  const maxQty = Math.max(1, ...bids.map((b) => b.qty), ...asks.map((a) => a.qty));
  const spread = asks[0] && bids[0] ? asks[0].price - bids[0].price : 0;
  const bidTotal = bids.reduce((s, b) => s + b.qty, 0);
  const askTotal = asks.reduce((s, a) => s + a.qty, 0);
  const bidShare = Math.round((bidTotal / (bidTotal + askTotal)) * 100);

  return (
    <div
      ref={ref}
      data-slot="market-depth"
      className={cn(
        "w-full max-w-sm rounded-3xl border border-border/60 bg-card p-4 shadow-md",
        className
      )}
      {...rest}
    >
      <div className="flex items-baseline justify-between gap-2 px-1">
        <span className="type-title text-foreground">{symbol}</span>
        <span
          className={cn(
            "flex items-center gap-1 font-mono text-base font-semibold numeric transition-colors duration-500",
            flash === "up" && "text-market-up",
            flash === "down" && "text-market-down",
            !flash && "text-foreground"
          )}
        >
          {flash ? (
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" className={cn("size-3.5", flash === "down" && "rotate-180")} aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7" /></svg>
          ) : null}
          {nf2.format(lastPrice)}
        </span>
      </div>

      {/* buyer/seller balance */}
      <div
        className="mt-2.5 flex h-2 overflow-hidden rounded-full ring-1 ring-inset ring-border/40"
        role="meter"
        aria-label="Buy-side share of visible depth"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={bidShare}
      >
        <span
          className="transition-all duration-500"
          style={{ width: `${bidShare}%`, background: "linear-gradient(90deg, color-mix(in oklab, var(--bid) 60%, transparent), var(--bid))" }}
        />
        <span
          className="flex-1"
          style={{ background: "linear-gradient(90deg, var(--ask), color-mix(in oklab, var(--ask) 60%, transparent))" }}
        />
      </div>
      <div className="mt-1 flex justify-between px-1 type-caption text-muted-foreground">
        <span>Buyers {bidShare}%</span>
        <span>Sellers {100 - bidShare}%</span>
      </div>

      <div className="mt-2 grid grid-cols-[auto_auto_1fr] px-2 type-overline text-muted-foreground">
        <span>Orders</span>
        <span className="ml-6">Qty</span>
        <span className="text-right">Price</span>
      </div>

      {/* Asks (worst to best, so the spread meets in the middle) */}
      <div className="mt-1 flex flex-col-reverse">
        {asks.map((a, i) => (
          <Row key={`ask-${i}`} side="ask" level={a} maxQty={maxQty} best={i === 0} onSelect={onLevelSelect} />
        ))}
      </div>

      <div className="my-1.5 flex items-center justify-between rounded-lg border border-border/50 bg-muted/50 px-2.5 py-1.5 type-meta">
        <span className="text-muted-foreground">
          Spread <span className="font-mono numeric text-foreground">{nf2.format(spread)}</span>
        </span>
        {atp ? (
          <span className="text-muted-foreground">
            ATP <span className="font-mono numeric text-foreground">{nf2.format(atp)}</span>
          </span>
        ) : null}
      </div>

      <div className="flex flex-col">
        {bids.map((b, i) => (
          <Row key={`bid-${i}`} side="bid" level={b} maxQty={maxQty} best={i === 0} onSelect={onLevelSelect} />
        ))}
      </div>

      <p className="mt-2 px-1 type-caption text-muted-foreground">
        Tap a level to prefill an order · simulated feed
      </p>
    </div>
  );
}

registry/default/fintech/sip-simulator.t:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Math                                                                 */
/* ------------------------------------------------------------------ */

export interface SipInputs {
  monthly: number;
  years: number;
  /** Expected annual return, %. */
  returnPct: number;
  /** Annual step-up of the contribution, %. */
  stepUpPct: number;
  /** Assumed inflation for the real-value line, %. */
  inflationPct: number;
}

export interface SipYearPoint {
  year: number;
  invested: number;
  value: number;
}

export function simulateSip({
  monthly,
  years,
  returnPct,
  stepUpPct,
}: Omit<SipInputs, "inflationPct">): SipYearPoint[] {
  const r = returnPct / 100 / 12;
  const points: SipYearPoint[] = [];
  let value = 0;
  let invested = 0;
  let contribution = monthly;
  for (let y = 1; y <= years; y++) {
    for (let m = 0; m < 12; m++) {
      value = value * (1 + r) + contribution;
      invested += contribution;
    }
    points.push({ year: y, invested, value });
    contribution *= 1 + stepUpPct / 100;
  }
  return points;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);
const lakh = (n: number) =>
  n >= 1e7 ? `₹${(n / 1e7).toFixed(2)}Cr` : n >= 1e5 ? `₹${(n / 1e5).toFixed(1)}L` : `₹${inr(n)}`;

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

export interface SipSimulatorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  defaults?: Partial<SipInputs>;
  /** Optional goal amount to mark on the chart. */
  goal?: number;
  ref?: React.Ref<HTMLDivElement>;
}

const W = 480;
const H = 170;
const PAD = { l: 8, r: 8, t: 12, b: 18 };

/**
 * SIP goal simulator: sliders drive a compounding projection; the growth
 * area redraws with a morphing path, the corpus rolls via NumberFlow and
 * the invested/growth split bar re-balances on every change.
 */
export function SipSimulator({
  defaults,
  goal,
  className,
  ref,
  ...rest
}: SipSimulatorProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [monthly, setMonthly] = React.useState(defaults?.monthly ?? 25_000);
  const [years, setYears] = React.useState(defaults?.years ?? 15);
  const [returnPct, setReturnPct] = React.useState(defaults?.returnPct ?? 12);
  const [stepUpPct, setStepUpPct] = React.useState(defaults?.stepUpPct ?? 5);
  const inflationPct = defaults?.inflationPct ?? 5;

  const points = React.useMemo(
    () => simulateSip({ monthly, years, returnPct, stepUpPct }),
    [monthly, years, returnPct, stepUpPct]
  );
  const final = points[points.length - 1];
  const growth = final.value - final.invested;
  const realValue = final.value / Math.pow(1 + inflationPct / 100, years);
  const growthShare = Math.round((growth / final.value) * 100);
  const goalYear = goal ? points.find((p) => p.value >= goal)?.year : undefined;

  /* Chart paths */
  const vMax = Math.max(final.value, goal ?? 0) * 1.05;
  const x = (year: number) => PAD.l + (year / years) * (W - PAD.l - PAD.r);
  const y = (v: number) => H - PAD.b - (v / vMax) * (H - PAD.t - PAD.b);
  const area = (key: "value" | "invested") =>
    `M${x(0)},${y(0)} ` +
    points.map((p) => `L${x(p.year)},${y(p[key])}`).join(" ") +
    ` L${x(years)},${y(0)} Z`;

  // Top edge of the value area, drawn as a glowing stroke.
  const valueLine =
    `M${x(0)},${y(0)} ` + points.map((p) => `L${x(p.year)},${y(p.value)}`).join(" ");

  const valueRef = React.useRef<SVGPathElement>(null);
  const investedRef = React.useRef<SVGPathElement>(null);
  const valueLineRef = React.useRef<SVGPathElement>(null);

  /* Paths morph to the new projection instead of snapping. */
  useGSAP(
    () => {
      const pairs: [SVGPathElement | null, string][] = [
        [valueRef.current, area("value")],
        [investedRef.current, area("invested")],
        [valueLineRef.current, valueLine],
      ];
      for (const [el, d] of pairs) {
        if (!el) continue;
        if (reduced) el.setAttribute("d", d);
        else gsap.to(el, { attr: { d }, duration: 0.5, ease: "power2.out", overwrite: true });
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    { dependencies: [points, reduced, goal] }
  );

  const slider = (
    label: string,
    value: number,
    set: (v: number) => void,
    min: number,
    max: number,
    step: number,
    fmt: (v: number) => string
  ) => (
    <label className="flex flex-col gap-1 text-xs">
      <span className="flex justify-between text-muted-foreground">
        {label}
        <span className="font-medium numeric text-foreground">{fmt(value)}</span>
      </span>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        aria-label={label}
        onChange={(e) => set(parseFloat(e.target.value))}
        className="accent-primary"
      />
    </label>
  );

  return (
    <div
      ref={rootRef}
      data-slot="sip-simulator"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <div>
          <p className="type-overline text-muted-foreground">
            Projected corpus · {years}y
          </p>
          <p className="type-metric text-foreground">
            <NumberFlow value={Math.round(final.value)} prefix="₹" locale="en-IN" trend />
          </p>
        </div>
        <div className="text-right type-meta text-muted-foreground">
          <p>
            Real value (at {inflationPct}% inflation):{" "}
            <span className="font-medium numeric text-foreground">{lakh(realValue)}</span>
          </p>
          {goal ? (
            <p>
              Goal {lakh(goal)}:{" "}
              {goalYear ? (
                <span className="font-medium text-success">reached in year {goalYear}</span>
              ) : (
                <span className="font-medium text-warning">not reached — raise SIP or horizon</span>
              )}
            </p>
          ) : null}
        </div>
      </div>

      {/* Chart */}
      <svg
        viewBox={`0 0 ${W} ${H}`}
        role="img"
        aria-label={`Projection: ₹${inr(final.invested)} invested grows to ₹${inr(final.value)} over ${years} years`}
        className="mt-3 w-full"
      >
        <defs>
          <linearGradient id={`sip-growth-${uid}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--market-up)" stopOpacity={0.35} />
            <stop offset="100%" stopColor="var(--market-up)" stopOpacity={0.04} />
          </linearGradient>
          <linearGradient id={`sip-invested-${uid}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--info)" stopOpacity={0.9} />
            <stop offset="100%" stopColor="var(--info)" stopOpacity={0.35} />
          </linearGradient>
          <filter id={`sip-glow-${uid}`} x="-5%" y="-40%" width="110%" height="180%">
            <feDropShadow dx="0" dy="1" stdDeviation="2.5" floodColor="var(--market-up)" floodOpacity="0.35" />
          </filter>
        </defs>
        <path ref={valueRef} d={area("value")} fill={`url(#sip-growth-${uid})`} />
        <path ref={investedRef} d={area("invested")} fill={`url(#sip-invested-${uid})`} />
        <path
          ref={valueLineRef}
          d={valueLine}
          fill="none"
          stroke="var(--market-up)"
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter={`url(#sip-glow-${uid})`}
        />
        {goal ? (
          <>
            <line
              x1={PAD.l}
              x2={W - PAD.r}
              y1={y(Math.min(goal, vMax))}
              y2={y(Math.min(goal, vMax))}
              strokeDasharray="4 4"
              className="stroke-warning"
            />
            <text x={W - PAD.r} y={y(Math.min(goal, vMax)) - 4} textAnchor="end" className="fill-warning text-[9px] font-medium">
              goal
            </text>
          </>
        ) : null}
        {[0.25, 0.5, 0.75, 1].map((f) => (
          <text
            key={f}
            x={x(years * f)}
            y={H - 5}
            textAnchor="middle"
            className="fill-muted-foreground text-[9px] tabular-nums"
          >
            {Math.round(years * f)}y
          </text>
        ))}
      </svg>

      {/* Invested vs growth split */}
      <div className="mt-1 flex h-2 overflow-hidden rounded-full ring-1 ring-inset ring-border/40" aria-hidden="true">
        <span
          className="transition-all duration-500"
          style={{
            width: `${100 - growthShare}%`,
            background: "linear-gradient(90deg, color-mix(in oklab, var(--info) 70%, transparent), var(--info))",
          }}
        />
        <span
          className="flex-1"
          style={{
            background: "linear-gradient(90deg, color-mix(in oklab, var(--market-up) 55%, transparent), var(--market-up))",
          }}
        />
      </div>
      <div className="mt-1 flex justify-between type-meta text-muted-foreground">
        <span>
          Invested <span className="font-medium numeric text-foreground">{lakh(final.invested)}</span>
        </span>
        <span>
          Growth <span className="font-medium numeric text-market-up">{lakh(growth)}</span> ({growthShare}%)
        </span>
      </div>

      {/* Controls */}
      <div className="mt-4 grid gap-x-6 gap-y-3 sm:grid-cols-2">
        {slider("Monthly SIP", monthly, setMonthly, 1_000, 200_000, 1_000, (v) => `₹${inr(v)}`)}
        {slider("Horizon", years, setYears, 1, 35, 1, (v) => `${v} years`)}
        {slider("Expected return", returnPct, setReturnPct, 4, 18, 0.5, (v) => `${v}% p.a.`)}
        {slider("Annual step-up", stepUpPct, setStepUpPct, 0, 15, 1, (v) => `${v}%`)}
      </div>
      <p className="mt-3 type-caption leading-4 text-muted-foreground">
        Illustration with constant returns — actual returns vary. Not
        investment advice.
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Spinner } from "@/registry/default/ui/spinner";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type PaymentScenario = "success" | "failed" | "refunded";

export interface PaymentStatusProps
  extends React.HTMLAttributes<HTMLDivElement> {
  amount: number;
  currency?: string;
  reference: string;
  method?: string;
  /** Which lifecycle to play. Default "success". */
  scenario?: PaymentScenario;
  /** Replays the timeline when this changes. */
  playKey?: React.Key;
  /** ms between stage transitions. Default 1000. */
  speed?: number;
  onSettled?: (scenario: PaymentScenario) => void;
  ref?: React.Ref<HTMLDivElement>;
}

interface Stage {
  key: string;
  label: string;
  detail: string;
  state: "done" | "active" | "pending" | "failed" | "refund";
}

const BASE_STAGES = [
  { key: "initiated", label: "Initiated", detail: "Payment request created" },
  { key: "authorised", label: "Authorised", detail: "Issuer approved the charge" },
  { key: "captured", label: "Captured", detail: "Funds reserved for settlement" },
  { key: "settled", label: "Settled", detail: "Funds credited to your account" },
] as const;

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

/**
 * One payment, its whole lifecycle: stages light up in sequence with
 * check-draws; failures stop the rail in red with a reason; refunds play
 * a second branch back to the customer.
 */
export function PaymentStatus({
  amount,
  currency = "₹",
  reference,
  method = "UPI",
  scenario = "success",
  playKey,
  speed = 1000,
  onSettled,
  className,
  ref,
  ...rest
}: PaymentStatusProps) {
  const reduced = useReducedMotion();
  // progress: number of completed base stages; then refund stages
  const failAt = 2; // capture fails in the failed scenario
  const totalBase = BASE_STAGES.length;
  const [progress, setProgress] = React.useState(0);
  const [refundProgress, setRefundProgress] = React.useState(0);

  React.useEffect(() => {
    let cancelled = false;
    setProgress(reduced ? totalBase : 0);
    setRefundProgress(0);
    if (reduced) {
      if (scenario === "failed") setProgress(failAt);
      if (scenario === "refunded") setRefundProgress(2);
      onSettled?.(scenario);
      return;
    }
    (async () => {
      const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
      const target = scenario === "failed" ? failAt : totalBase;
      for (let i = 1; i <= target; i++) {
        await wait(speed);
        if (cancelled) return;
        setProgress(i);
      }
      if (scenario === "refunded") {
        for (let i = 1; i <= 2; i++) {
          await wait(speed);
          if (cancelled) return;
          setRefundProgress(i);
        }
      }
      onSettled?.(scenario);
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scenario, playKey, speed, reduced]);

  const stages: Stage[] = BASE_STAGES.map((s, i) => {
    if (scenario === "failed" && i === failAt)
      return {
        ...s,
        label: "Capture failed",
        detail: "Issuer declined: insufficient funds (05)",
        state: progress >= failAt ? "failed" : progress === i ? "active" : "pending",
      };
    if (scenario === "failed" && i > failAt) return { ...s, state: "pending" };
    return {
      ...s,
      state: progress > i ? "done" : progress === i ? "active" : "pending",
    };
  });

  const refundStages: Stage[] =
    scenario === "refunded"
      ? [
          { key: "refund-init", label: "Refund initiated", detail: "Full amount reversed by merchant", state: refundProgress > 0 ? "refund" : progress >= totalBase && refundProgress === 0 ? "active" : "pending" },
          { key: "refund-done", label: "Refunded", detail: "5–7 working days to the source account", state: refundProgress > 1 ? "refund" : refundProgress === 1 ? "active" : "pending" },
        ]
      : [];

  const headline =
    scenario === "failed" && progress >= failAt
      ? { text: "Payment failed", tone: "text-destructive" }
      : scenario === "refunded" && refundProgress > 1
        ? { text: "Refunded", tone: "text-info" }
        : progress >= totalBase && scenario === "success"
          ? { text: "Settled", tone: "text-success" }
          : { text: "Processing", tone: "text-muted-foreground" };

  return (
    <div
      ref={ref}
      data-slot="payment-status"
      className={cn(
        "w-full max-w-sm rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      <div className="flex items-start justify-between gap-2">
        <div>
          <p className="type-metric numeric text-foreground">
            {currency}
            {new Intl.NumberFormat("en-IN", { minimumFractionDigits: 2 }).format(amount)}
          </p>
          <p className="mt-0.5 type-meta text-muted-foreground">
            {reference} · {method}
          </p>
        </div>
        <span className={cn("flex items-center gap-1.5 rounded-full bg-muted/60 px-2 py-0.5 text-xs font-semibold ring-1 ring-inset ring-border/50", headline.tone)} aria-live="polite">
          {headline.text}
        </span>
      </div>

      <ol className="mt-4 flex flex-col">
        {[...stages, ...refundStages].map((s, i, all) => (
          <StageRow key={s.key} stage={s} last={i === all.length - 1} />
        ))}
      </ol>

      {scenario === "failed" && progress >= failAt ? (
        <p className="mt-2 rounded-lg bg-destructive/10 px-2.5 py-1.5 type-meta leading-4 text-destructive">
          No funds were captured. The authorisation hold releases
          automatically within 24 hours — safe to retry with another method.
        </p>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Stage row                                                            */
/* ------------------------------------------------------------------ */

function StageRow({ stage, last }: { stage: Stage; last: boolean }) {
  const ref = React.useRef<HTMLLIElement>(null);
  const checkRef = React.useRef<SVGPathElement>(null);
  const reduced = useReducedMotion();
  const settled = stage.state === "done" || stage.state === "failed" || stage.state === "refund";

  useGSAP(
    () => {
      if (!checkRef.current || !settled) return;
      if (reduced) {
        gsap.set(checkRef.current, { strokeDashoffset: 0 });
        return;
      }
      gsap.fromTo(
        checkRef.current,
        { strokeDashoffset: 1 },
        { strokeDashoffset: 0, duration: 0.4, ease: "power2.out" }
      );
    },
    { dependencies: [settled, reduced], scope: ref }
  );

  return (
    <li ref={ref} className="flex gap-3">
      <div className="flex flex-col items-center">
        <span
          className={cn(
            "relative flex size-5 items-center justify-center rounded-full transition-colors duration-300",
            stage.state === "done" && "bg-success text-white",
            stage.state === "refund" && "bg-info text-white",
            stage.state === "failed" && "bg-destructive text-white",
            stage.state === "active" && "bg-primary/10",
            stage.state === "pending" && "bg-muted"
          )}
        >
          {settled ? (
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true">
              {stage.state === "failed" ? (
                <path ref={checkRef} d="M18 6 6 18M6 6l12 12" pathLength={1} strokeDasharray={1} strokeDashoffset={1} />
              ) : (
                <path ref={checkRef} d="M5 13l4 4L19 7" pathLength={1} strokeDasharray={1} strokeDashoffset={1} />
              )}
            </svg>
          ) : stage.state === "active" ? (
            <Spinner size="sm" />
          ) : null}
        </span>
        {!last ? (
          <span
            className={cn(
              "my-0.5 min-h-4 w-px flex-1 transition-colors duration-500",
              stage.state === "done" ? "bg-success/50" : stage.state === "refund" ? "bg-info/50" : "bg-border"
            )}
          />
        ) : null}
      </div>
      <div className="pb-3">
        <p
          className={cn(
            "text-sm leading-5",
            stage.state === "pending" ? "text-muted-foreground" : "font-medium text-foreground",
            stage.state === "failed" && "text-destructive"
          )}
        >
          {stage.label}
        </p>
        <p className="type-meta leading-4 text-muted-foreground">{stage.detail}</p>
      </div>
    </li>
  );
}

registry/default/health/medication-timel:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Badge } from "@/registry/default/ui/badge";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface Medication {
  name: string;
  dose: string;
  frequency: string;
  /** Day index (0-based) the course starts/ends within the visible window. */
  startDay: number;
  endDay: number;
  /** Adherence per day: taken, missed or upcoming. Index = day - startDay. */
  adherence: ("taken" | "missed" | "upcoming")[];
  /** Days until refill runs out, if low. */
  refillInDays?: number;
}

export interface MedicationInteraction {
  a: string;
  b: string;
  note: string;
}

export interface MedicationTimelineProps
  extends React.HTMLAttributes<HTMLDivElement> {
  medications: Medication[];
  interactions?: MedicationInteraction[];
  /** Days in the visible window. Default 28. */
  windowDays?: number;
  /** 0-based index of "today" within the window. Default 20. */
  today?: number;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_MEDICATIONS: Medication[] = [
  {
    name: "Metformin",
    dose: "500 mg",
    frequency: "2× daily",
    startDay: 0,
    endDay: 27,
    adherence: Array.from({ length: 28 }, (_, i) =>
      i > 20 ? "upcoming" : i === 6 || i === 14 ? "missed" : "taken"
    ),
  },
  {
    name: "Atorvastatin",
    dose: "10 mg",
    frequency: "1× nightly",
    startDay: 4,
    endDay: 27,
    adherence: Array.from({ length: 24 }, (_, i) =>
      i + 4 > 20 ? "upcoming" : i === 9 ? "missed" : "taken"
    ),
    refillInDays: 4,
  },
  {
    name: "Vitamin D3",
    dose: "60k IU",
    frequency: "weekly",
    startDay: 0,
    endDay: 27,
    adherence: Array.from({ length: 28 }, (_, i) =>
      i % 7 !== 0 ? "upcoming" : i > 20 ? "upcoming" : "taken"
    ),
  },
];

export const DEMO_INTERACTIONS: MedicationInteraction[] = [
  {
    a: "Metformin",
    b: "Atorvastatin",
    note: "Generally safe together; monitor for muscle pain and report it early.",
  },
];

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

/**
 * A month of medication at a glance: course bars grow in, adherence dots
 * cascade (missed doses in warning), refills flag before they run out and
 * interactions link the two rows they concern.
 */
export function MedicationTimeline({
  medications,
  interactions = [],
  windowDays = 28,
  today = 20,
  className,
  ref,
  ...rest
}: MedicationTimelineProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);
  const [selected, setSelected] = React.useState<string | null>(null);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-course]"));
      const dots = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-dose]"));
      if (reduced) {
        gsap.set(bars, { scaleX: 1, opacity: 1 });
        gsap.set(dots, { scale: 1, opacity: 1 });
        return;
      }
      gsap.fromTo(
        bars,
        { scaleX: 0, opacity: 0, transformOrigin: "left center" },
        { scaleX: 1, opacity: 1, duration: 0.6, ease: "power3.out", stagger: 0.12 }
      );
      gsap.fromTo(
        dots,
        { scale: 0, opacity: 0 },
        { scale: 1, opacity: 1, duration: 0.3, ease: "back.out(2)", stagger: 0.008, delay: 0.35 }
      );
    },
    { dependencies: [reduced, medications], scope: rootRef }
  );

  const pct = (day: number) => (day / (windowDays - 1)) * 100;
  const adherenceStats = (m: Medication) => {
    const past = m.adherence.filter((a) => a !== "upcoming");
    const taken = past.filter((a) => a === "taken").length;
    return { taken, past: past.length, pct: past.length ? Math.round((taken / past.length) * 100) : 100 };
  };

  return (
    <div
      ref={rootRef}
      data-slot="medication-timeline"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2">
        <h3 className="type-title text-foreground">Medications · last 4 weeks</h3>
        <span className="type-meta text-muted-foreground">tap a row for details</span>
      </div>

      <div className="relative mt-4 flex flex-col gap-5">
        {/* today line */}
        <span
          aria-hidden="true"
          className="absolute bottom-0 top-1 w-px"
          style={{
            left: `${pct(today)}%`,
            background: "linear-gradient(180deg, var(--info), color-mix(in oklab, var(--info) 20%, transparent))",
          }}
        />
        <span
          aria-hidden="true"
          className="absolute top-1 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-info"
          style={{ left: `${pct(today)}%`, boxShadow: "0 0 6px color-mix(in oklab, var(--info) 70%, transparent)" }}
        />
        <span
          className="absolute -top-1 -translate-x-1/2 text-[9px] font-medium uppercase text-info"
          style={{ left: `${pct(today)}%` }}
        >
          today
        </span>

        {medications.map((m) => {
          const stats = adherenceStats(m);
          const isSel = selected === m.name;
          return (
            <button
              key={m.name}
              type="button"
              aria-pressed={isSel}
              onClick={() => setSelected((s) => (s === m.name ? null : m.name))}
              className={cn(
                "group rounded-lg p-1 pt-2 text-left transition-colors duration-200",
                isSel ? "bg-muted/70" : "hover:bg-muted/40",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              <div className="flex items-baseline justify-between gap-2 px-1">
                <span className="text-xs font-medium text-foreground">
                  {m.name} <span className="text-muted-foreground">{m.dose} · {m.frequency}</span>
                </span>
                <span
                  className={cn(
                    "type-meta numeric",
                    stats.pct >= 90 ? "text-success" : stats.pct >= 75 ? "text-warning" : "text-risk-high"
                  )}
                >
                  {stats.pct}% adherence
                </span>
              </div>
              {/* course bar + dose dots */}
              <div className="relative mt-1.5 h-5 px-1">
                <span
                  data-course
                  aria-hidden="true"
                  className="absolute top-1/2 h-1.5 -translate-y-1/2 rounded-full"
                  style={{
                    left: `${pct(m.startDay)}%`,
                    width: `${pct(m.endDay) - pct(m.startDay)}%`,
                    background: "linear-gradient(90deg, color-mix(in oklab, var(--info) 22%, transparent), color-mix(in oklab, var(--success) 18%, transparent))",
                  }}
                />
                {m.adherence.map((a, i) => {
                  const day = m.startDay + i;
                  if (day >= windowDays) return null;
                  return (
                    <span
                      key={day}
                      data-dose
                      aria-hidden="true"
                      className={cn(
                        "absolute top-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rounded-full",
                        a === "taken" && "bg-success ring-2 ring-success/20",
                        a === "missed" && "bg-warning ring-2 ring-warning/30",
                        a === "upcoming" && "border border-border bg-background"
                      )}
                      style={{ left: `${pct(day)}%` }}
                    />
                  );
                })}
                {m.refillInDays != null ? (
                  <Badge
                    variant="outline"
                    pulse
                    className="absolute -top-1 right-0 text-[9px] text-warning"
                  >
                    Refill in {m.refillInDays}d
                  </Badge>
                ) : null}
              </div>
              {isSel ? (
                <p className="mt-1 px-1 type-meta leading-4 text-muted-foreground">
                  {stats.taken}/{stats.past} doses taken.{" "}
                  {m.adherence.includes("missed")
                    ? "Missed doses shown in amber — don't double up; take the next scheduled dose."
                    : "No missed doses in this window."}
                </p>
              ) : null}
            </button>
          );
        })}
      </div>

      {interactions.length > 0 ? (
        <div className="mt-4 flex flex-col gap-1.5">
          {interactions.map((ix) => (
            <p
              key={`${ix.a}-${ix.b}`}
              className="rounded-lg border border-info/30 bg-info/5 px-2.5 py-1.5 type-meta leading-4 text-foreground"
            >
              <span className="font-semibold">{ix.a} + {ix.b}:</span> {ix.note}
            </p>
          ))}
        </div>
      ) : null}
      <p className="mt-3 type-caption text-muted-foreground">
        Legend: green taken · amber missed · hollow upcoming. Informational —
        follow your prescriber&apos;s instructions.
      </p>
    </div>
  );
}

registry/default/health/clinical-risk.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface RiskFactor {
  label: string;
  /** Contribution weight, -1..1. Positive raises risk. */
  weight: number;
  detail?: string;
}

export interface ClinicalRiskProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title: string;
  /** Risk score 0..100. */
  score: number;
  factors: RiskFactor[];
  missingData?: string[];
  recommendation?: string;
  onEscalate?: () => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_CARDIO_RISK: Pick<
  ClinicalRiskProps,
  "title" | "score" | "factors" | "missingData" | "recommendation"
> = {
  title: "10-year cardiovascular risk",
  score: 34,
  factors: [
    { label: "LDL trending down", weight: -0.35, detail: "158 → 101 mg/dL over 9 months" },
    { label: "HbA1c 6.1%", weight: 0.4, detail: "Pre-diabetic range" },
    { label: "Blood pressure 138/88", weight: 0.5, detail: "Stage-1 hypertension range" },
    { label: "Non-smoker", weight: -0.3 },
    { label: "Family history", weight: 0.45, detail: "Parent with early CAD" },
  ],
  missingData: ["Recent lipoprotein(a)", "Resting ECG"],
  recommendation:
    "Risk is moderate and modifiable: blood-pressure control and continued LDL reduction have the largest effect. Re-score after the missing tests.",
};

const riskBand = (score: number) =>
  score < 25
    ? { label: "Low", cls: "text-risk-low", stroke: "stroke-risk-low" }
    : score < 55
      ? { label: "Moderate", cls: "text-risk-medium", stroke: "stroke-risk-medium" }
      : { label: "High", cls: "text-risk-high", stroke: "stroke-risk-high" };

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

/**
 * A clinician-review risk summary: the gauge arc sweeps to the score,
 * factor bars grow from the center (protective left, adverse right) and
 * the copy stays explicitly decision-support, not diagnosis.
 */
export function ClinicalRisk({
  title,
  score,
  factors,
  missingData = [],
  recommendation,
  onEscalate,
  className,
  ref,
  ...rest
}: ClinicalRiskProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const arcRef = React.useRef<SVGPathElement>(null);
  const scoreRef = React.useRef<HTMLSpanElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const band = riskBand(score);
  const maxW = Math.max(...factors.map((f) => Math.abs(f.weight)), 0.01);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-factor]"));
      if (reduced) {
        if (arcRef.current) gsap.set(arcRef.current, { strokeDashoffset: 1 - score / 100 });
        if (scoreRef.current) scoreRef.current.textContent = String(score);
        gsap.set(bars, { scaleX: 1, opacity: 1 });
        return;
      }
      if (arcRef.current)
        gsap.fromTo(
          arcRef.current,
          { strokeDashoffset: 1 },
          { strokeDashoffset: 1 - score / 100, duration: 1.1, ease: "power3.inOut" }
        );
      if (scoreRef.current) {
        const counter = { v: 0 };
        gsap.to(counter, {
          v: score,
          duration: 1.1,
          ease: "power3.inOut",
          onUpdate: () => {
            if (scoreRef.current) scoreRef.current.textContent = String(Math.round(counter.v));
          },
        });
      }
      gsap.fromTo(
        bars,
        { scaleX: 0, opacity: 0 },
        { scaleX: 1, opacity: 1, duration: 0.5, ease: "power3.out", stagger: 0.08, delay: 0.5 }
      );
    },
    { dependencies: [score, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="clinical-risk"
      className={cn(
        "w-full max-w-md rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      <h3 className="type-title text-foreground">{title}</h3>

      {/* Gauge */}
      <div className="mt-2 flex items-center gap-4">
        <div
          className="relative shrink-0"
          role="meter"
          aria-label={`${title}: ${score} of 100, ${band.label}`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={score}
        >
          <svg viewBox="0 0 100 62" className="w-32 overflow-visible">
            <defs>
              <linearGradient id={`gauge-${uid}`} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="var(--risk-low)" />
                <stop offset="50%" stopColor="var(--risk-medium)" />
                <stop offset="100%" stopColor="var(--risk-high)" />
              </linearGradient>
            </defs>
            <path
              d="M10,55 A45,45 0 0 1 90,55"
              fill="none"
              strokeWidth={9}
              strokeLinecap="round"
              className="stroke-muted/70"
            />
            <path
              ref={arcRef}
              d="M10,55 A45,45 0 0 1 90,55"
              fill="none"
              strokeWidth={9}
              strokeLinecap="round"
              pathLength={1}
              strokeDasharray={1}
              strokeDashoffset={1}
              stroke={`url(#gauge-${uid})`}
              style={{ filter: `drop-shadow(0 1px 4px color-mix(in oklab, ${band.label === "High" ? "var(--risk-high)" : band.label === "Moderate" ? "var(--risk-medium)" : "var(--risk-low)"} 45%, transparent))` }}
            />
          </svg>
          <div className="absolute inset-x-0 bottom-0 text-center">
            <span ref={scoreRef} className="type-metric numeric text-foreground">
              0
            </span>
            <span className="text-xs text-muted-foreground">/100</span>
          </div>
        </div>
        <div>
          <p className={cn("text-sm font-semibold", band.cls)}>{band.label} risk</p>
          <p className="mt-0.5 type-meta leading-4 text-muted-foreground">
            Decision support for clinician review — not a diagnosis.
          </p>
        </div>
      </div>

      {/* Factors: protective ← | → adverse */}
      <div className="mt-4">
        <div className="flex justify-between type-overline text-muted-foreground">
          <span>Protective</span>
          <span>Adverse</span>
        </div>
        <ul className="mt-1.5 flex flex-col gap-2">
          {factors.map((f) => {
            const adverse = f.weight > 0;
            const width = (Math.abs(f.weight) / maxW) * 50;
            return (
              <li key={f.label} className="text-xs">
                <div className="relative h-2.5 overflow-hidden rounded-full bg-muted/70 ring-1 ring-inset ring-border/40">
                  <span aria-hidden="true" className="absolute inset-y-0 left-1/2 z-10 w-px bg-border" />
                  <span
                    data-factor
                    className={cn(
                      "absolute inset-y-0 rounded-full",
                      adverse ? "left-1/2 origin-left" : "right-1/2 origin-right"
                    )}
                    style={{
                      width: `${width}%`,
                      background: adverse
                        ? "linear-gradient(90deg, color-mix(in oklab, var(--risk-high) 55%, transparent), var(--risk-high))"
                        : "linear-gradient(270deg, color-mix(in oklab, var(--risk-low) 55%, transparent), var(--risk-low))",
                    }}
                  />
                </div>
                <div className="mt-0.5 flex justify-between gap-2">
                  <span className="font-medium text-foreground">{f.label}</span>
                  {f.detail ? (
                    <span className="text-right text-muted-foreground">{f.detail}</span>
                  ) : null}
                </div>
              </li>
            );
          })}
        </ul>
      </div>

      {missingData.length > 0 ? (
        <p className="mt-3 rounded-lg bg-muted/60 px-2.5 py-1.5 type-meta leading-4 text-muted-foreground">
          <span className="font-semibold text-foreground">Missing data:</span>{" "}
          {missingData.join(", ")} — the score has wider uncertainty until these
          are available.
        </p>
      ) : null}

      {recommendation ? (
        <p className="mt-2 type-meta leading-5 text-foreground">{recommendation}</p>
      ) : null}

      <div className="mt-3 flex gap-2">
        <Button size="sm" variant="outline" className="flex-1" onClick={onEscalate}>
          Send to clinician review
        </Button>
      </div>
    </div>
  );
}

registry/default/health/vitals-monitor.t:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Synthetic ECG                                                        */
/* ------------------------------------------------------------------ */

/** One cardiac cycle sampled at phase 0..1: P wave, QRS complex, T wave. */
function ecgSample(phase: number): number {
  const g = (c: number, w: number, h: number) =>
    h * Math.exp(-((phase - c) ** 2) / (2 * w * w));
  return (
    g(0.18, 0.025, 0.12) + // P
    g(0.395, 0.016, -0.18) + // Q
    g(0.42, 0.014, 1) + // R
    g(0.445, 0.018, -0.28) + // S
    g(0.62, 0.045, 0.28) // T
  );
}

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface VitalsMonitorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  patient?: string;
  /** Baseline heart rate. Default 72. */
  heartRate?: number;
  spo2?: number;
  systolic?: number;
  diastolic?: number;
  temperature?: number;
  /** Simulate a tachycardia alarm: HR climbs and the card enters alarm state. */
  alarm?: boolean;
  /** HR above this triggers the alarm styling. Default 110. */
  hrAlarmAt?: number;
  ref?: React.Ref<HTMLDivElement>;
}

const W = 320;
const H = 72;
const SAMPLES = 240;

/**
 * A live patient vitals card: the ECG trace draws continuously with a
 * fading tail, the rate rolls via NumberFlow, and out-of-range values put
 * the whole card into a pulsing alarm state.
 */
export function VitalsMonitor({
  patient = "Bed 12",
  heartRate = 72,
  spo2 = 98,
  systolic = 122,
  diastolic = 78,
  temperature = 36.8,
  alarm = false,
  hrAlarmAt = 110,
  className,
  ref,
  ...rest
}: VitalsMonitorProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const pathRef = React.useRef<SVGPathElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [hr, setHr] = React.useState(heartRate);
  const targetHr = alarm ? Math.max(hrAlarmAt + 18, heartRate + 40) : heartRate;
  const inAlarm = hr >= hrAlarmAt;

  /* HR drifts toward its target with small jitter. */
  React.useEffect(() => {
    if (reduced) {
      setHr(targetHr);
      return;
    }
    const id = setInterval(() => {
      setHr((h) => {
        const drift = (targetHr - h) * 0.25;
        const jitter = (Math.random() - 0.5) * 2;
        return Math.round(h + drift + jitter);
      });
    }, 1200);
    return () => clearInterval(id);
  }, [targetHr, reduced]);

  /* Continuous trace: a ring buffer of samples advanced by rAF, drawn
     straight into the path's `d` — no React re-render per frame. */
  React.useEffect(() => {
    const path = pathRef.current;
    if (!path) return;
    const buf = new Array(SAMPLES).fill(0);
    let phase = 0;
    let raf = 0;
    let last = performance.now();
    let head = 0;

    const draw = () => {
      let d = "";
      for (let i = 0; i < SAMPLES; i++) {
        const v = buf[(head + i) % SAMPLES];
        const px = (i / (SAMPLES - 1)) * W;
        const py = H * 0.72 - v * H * 0.55;
        d += `${i === 0 ? "M" : "L"}${px.toFixed(1)},${py.toFixed(1)}`;
      }
      path.setAttribute("d", d);
    };

    if (reduced) {
      // Static two-beat strip instead of animation.
      for (let i = 0; i < SAMPLES; i++) buf[i] = ecgSample(((i / SAMPLES) * 2) % 1);
      draw();
      return;
    }

    const tick = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const beatsPerSec = hr / 60;
      // advance ~90 samples/sec worth of trace
      const advance = Math.max(1, Math.round(dt * 90));
      for (let i = 0; i < advance; i++) {
        phase = (phase + (beatsPerSec / 90) * 1) % 1;
        buf[head] = ecgSample(phase);
        head = (head + 1) % SAMPLES;
      }
      draw();
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [hr, reduced]);

  /* Alarm state pulses the card border. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      gsap.killTweensOf(root);
      if (inAlarm && !reduced) {
        gsap.to(root, {
          boxShadow: "0 0 0 3px color-mix(in oklab, var(--risk-high) 55%, transparent), var(--elevation-md)",
          duration: 0.7,
          ease: "power1.inOut",
          repeat: -1,
          yoyo: true,
        });
      } else {
        gsap.set(root, { clearProps: "boxShadow" });
      }
    },
    { dependencies: [inAlarm, reduced] }
  );

  const trace = inAlarm ? "var(--risk-high)" : "var(--success)";
  const tiles: { label: string; value: React.ReactNode; unit: string; bad?: boolean }[] = [
    { label: "SpO₂", value: spo2, unit: "%", bad: spo2 < 94 },
    { label: "BP", value: `${systolic}/${diastolic}`, unit: "mmHg", bad: systolic > 140 },
    { label: "Temp", value: temperature.toFixed(1), unit: "°C", bad: temperature >= 38 },
  ];

  return (
    <div
      ref={rootRef}
      data-slot="vitals-monitor"
      className={cn(
        "w-full max-w-sm rounded-3xl border bg-card p-4 shadow-md transition-colors duration-300",
        inAlarm ? "border-risk-high/60" : "border-border/60",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2 px-1">
        <span className="type-title text-foreground">{patient}</span>
        {inAlarm ? (
          <span className="flex items-center gap-1.5 rounded-full bg-risk-high/10 px-2 py-0.5 text-xs font-semibold text-risk-high" role="alert">
            <span className="relative flex size-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-risk-high opacity-60" />
              <span className="relative inline-flex size-2 rounded-full bg-risk-high" />
            </span>
            Tachycardia
          </span>
        ) : (
          <span className="flex items-center gap-1.5 rounded-full bg-success/10 px-2 py-0.5 text-xs font-medium text-success">
            <span className="size-1.5 rounded-full bg-success" />
            All vitals in range
          </span>
        )}
      </div>

      {/* ECG screen: a dark monitor surface in both themes, glowing trace,
          live HR read out over the top-right of the strip. */}
      <div
        className="relative mt-3 overflow-hidden rounded-2xl border border-white/10 bg-[hsl(230_25%_7%)] shadow-inner"
        style={{ "--trace": trace } as React.CSSProperties}
      >
        <svg viewBox={`0 0 ${W} ${H}`} className="w-full" aria-hidden="true">
          <defs>
            <filter id={`ecg-glow-${uid}`} x="-5%" y="-60%" width="110%" height="220%">
              <feDropShadow dx="0" dy="0" stdDeviation="1.6" floodColor={trace} floodOpacity="0.9" />
            </filter>
          </defs>
          {/* grid */}
          {Array.from({ length: 7 }, (_, i) => (
            <line key={`v${i}`} x1={(i + 1) * (W / 8)} x2={(i + 1) * (W / 8)} y1={0} y2={H} stroke="currentColor" strokeWidth={0.5} className="text-white/[0.06]" />
          ))}
          {Array.from({ length: 3 }, (_, i) => (
            <line key={`h${i}`} y1={(i + 1) * (H / 4)} y2={(i + 1) * (H / 4)} x1={0} x2={W} stroke="currentColor" strokeWidth={0.5} className="text-white/[0.06]" />
          ))}
          <path
            ref={pathRef}
            fill="none"
            strokeWidth={1.8}
            strokeLinejoin="round"
            strokeLinecap="round"
            stroke={trace}
            filter={`url(#ecg-glow-${uid})`}
          />
        </svg>
        {/* HR read-out, on a soft scrim so the trace never fights it */}
        <div className="absolute right-2 top-1.5 rounded-xl bg-[hsl(230_25%_7%)]/80 px-2.5 py-1 text-right backdrop-blur-sm">
          <span className="text-[9px] font-medium uppercase tracking-[0.15em] text-white/40">HR</span>
          <div className="-mt-0.5 flex items-baseline justify-end gap-1 font-semibold numeric" style={{ color: trace }}>
            <span className="text-2xl leading-none">
              <NumberFlow value={hr} />
            </span>
            <span className="type-caption text-white/40">bpm</span>
          </div>
        </div>
      </div>
      <p className="sr-only" aria-live="polite">
        Heart rate {hr} beats per minute{inAlarm ? ", tachycardia alarm active" : ""}.
      </p>

      {/* Tiles */}
      <div className="mt-3 grid grid-cols-3 gap-2">
        {tiles.map((t) => (
          <div
            key={t.label}
            className={cn(
              "relative overflow-hidden rounded-xl border px-3 py-2.5 shadow-xs transition-colors duration-300",
              t.bad ? "border-risk-high/40 bg-risk-high/[0.06]" : "border-border/60 bg-background/60"
            )}
          >
            <p className="type-overline text-muted-foreground">
              {t.label}
            </p>
            <p
              className={cn(
                "mt-0.5 text-lg font-semibold leading-none numeric",
                t.bad ? "text-risk-high" : "text-foreground"
              )}
            >
              {t.value}
            </p>
            <p className="mt-1 type-caption text-muted-foreground">{t.unit}</p>
          </div>
        ))}
      </div>
      <p className="mt-2.5 px-1 type-caption text-muted-foreground">
        Simulated telemetry for demonstration — not a medical device.
      </p>
    </div>
  );
}

registry/default/fintech/order-ticket.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { LayoutGroup, motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type OrderType = "market" | "limit" | "stop" | "stop-limit";

export interface PlacedOrder {
  side: "buy" | "sell";
  type: OrderType;
  qty: number;
  price?: number;
  triggerPrice?: number;
}

export interface OrderTicketProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  symbol: string;
  lastPrice: number;
  bestBid: number;
  bestAsk: number;
  lotSize?: number;
  /** Margin available to trade. Drives the risk-blocked state. */
  availableMargin?: number;
  /** Margin factor per unit of notional. Default 0.14 (index options-ish). */
  marginFactor?: number;
  onPlaced?: (order: PlacedOrder) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);
const nf2 = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

// Indian-broker conventions: SL = stop-loss limit (trigger + limit price),
// SL-M = stop-loss market (trigger, fills at market).
const TYPES: { key: OrderType; label: string }[] = [
  { key: "market", label: "Market" },
  { key: "limit", label: "Limit" },
  { key: "stop-limit", label: "SL" },
  { key: "stop", label: "SL-M" },
];

const spring = { type: "spring", stiffness: 480, damping: 38 } as const;

type Stage = "form" | "review" | "placing" | "filling" | "done";

/* ------------------------------------------------------------------ */
/* Ticket                                                               */
/* ------------------------------------------------------------------ */

/**
 * Advanced order ticket: buy/sell recolors the whole ticket, order types
 * reveal the fields they need, margin and charges roll live, over-margin
 * blocks the flow, and placement plays a partial-fill progress state.
 */
export function OrderTicket({
  symbol,
  lastPrice,
  bestBid,
  bestAsk,
  lotSize = 75,
  availableMargin = 250_000,
  marginFactor = 0.14,
  onPlaced,
  className,
  ref,
  ...rest
}: OrderTicketProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [side, setSide] = React.useState<"buy" | "sell">("buy");
  const [type, setType] = React.useState<OrderType>("limit");
  const [lots, setLots] = React.useState(1);
  const [price, setPrice] = React.useState(lastPrice.toFixed(2));
  const [trigger, setTrigger] = React.useState((lastPrice * 0.995).toFixed(2));
  const [chargesOpen, setChargesOpen] = React.useState(false);
  const [stage, setStage] = React.useState<Stage>("form");
  const [filled, setFilled] = React.useState(0);

  const qty = lots * lotSize;
  const effPrice =
    type === "market" ? (side === "buy" ? bestAsk : bestBid) : parseFloat(price) || 0;
  const notional = qty * effPrice;
  const margin = Math.round(notional * marginFactor);
  const brokerage = 20;
  const stt = Math.round(notional * 0.000625);
  const other = Math.round(notional * 0.000053) + 15;
  const charges = brokerage + stt + other;
  const overMargin = margin > availableMargin;
  const needsPrice = type === "limit" || type === "stop-limit";
  const needsTrigger = type === "stop" || type === "stop-limit";
  const sideColor = side === "buy" ? "var(--market-up)" : "var(--market-down)";

  const chargesRef = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!chargesRef.current) return;
      if (reduced) {
        gsap.set(chargesRef.current, { height: chargesOpen ? "auto" : 0, opacity: chargesOpen ? 1 : 0 });
        return;
      }
      gsap.to(chargesRef.current, {
        height: chargesOpen ? "auto" : 0,
        opacity: chargesOpen ? 1 : 0,
        duration: 0.3,
        ease: "power3.out",
      });
    },
    { dependencies: [chargesOpen, reduced] }
  );

  const place = async () => {
    setStage("placing");
    await new Promise((r) => setTimeout(r, 900));
    setStage("filling");
    // partial fill: 40% then complete
    setFilled(Math.round(qty * 0.4));
    await new Promise((r) => setTimeout(r, 1300));
    setFilled(qty);
    await new Promise((r) => setTimeout(r, 500));
    setStage("done");
    onPlaced?.({
      side,
      type,
      qty,
      ...(needsPrice ? { price: parseFloat(price) } : {}),
      ...(needsTrigger ? { triggerPrice: parseFloat(trigger) } : {}),
    });
  };

  const reset = () => {
    setStage("form");
    setFilled(0);
  };

  const numField = (
    label: string,
    value: string,
    set: (v: string) => void,
    disabled = false
  ) => (
    <label className="flex min-w-0 flex-1 flex-col gap-1.5 type-meta font-medium text-muted-foreground">
      {label}
      <input
        inputMode="decimal"
        value={value}
        disabled={disabled}
        aria-label={label}
        onChange={(e) => set(e.target.value.replace(/[^0-9.]/g, ""))}
        className={cn(
          "h-10 w-full min-w-0 rounded-xl border border-input bg-background px-3 font-mono text-sm numeric text-foreground shadow-xs",
          "transition-[border-color,box-shadow] duration-200 hover:border-ring/30",
          "focus-visible:outline-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/25",
          disabled && "opacity-50"
        )}
      />
    </label>
  );

  return (
    <div
      ref={rootRef}
      data-slot="order-ticket"
      className={cn(
        "relative w-full max-w-sm overflow-hidden rounded-3xl border bg-card p-5 shadow-md transition-colors duration-300",
        side === "buy" ? "border-market-up/30" : "border-market-down/30",
        className
      )}
      {...rest}
    >
      {/* Side-tinted top hairline */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-px transition-colors duration-300"
        style={{ background: `linear-gradient(90deg, transparent, ${sideColor}, transparent)` }}
      />

      {/* Header */}
      <div className="flex items-center justify-between gap-2">
        <span className="type-title text-foreground">{symbol}</span>
        <span className="flex items-center gap-1.5 font-mono text-xs numeric">
          <span className="rounded-md bg-bid/10 px-1.5 py-0.5 text-bid">{nf2.format(bestBid)}</span>
          <span className="text-muted-foreground">/</span>
          <span className="rounded-md bg-ask/10 px-1.5 py-0.5 text-ask">{nf2.format(bestAsk)}</span>
        </span>
      </div>

      {stage === "form" || stage === "review" ? (
        <LayoutGroup id={uid}>
          {/* Side toggle */}
          <div className="isolate mt-4 grid grid-cols-2 gap-1 rounded-xl bg-muted p-1" role="tablist" aria-label="Order side">
            {(["buy", "sell"] as const).map((s) => (
              <button
                key={s}
                role="tab"
                aria-selected={side === s}
                onClick={() => setSide(s)}
                className={cn(
                  "relative rounded-lg py-2 text-xs font-semibold uppercase tracking-wide transition-colors duration-200",
                  side === s ? "text-white" : "text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {side === s ? (
                  <motion.span
                    layoutId={`side-${uid}`}
                    transition={reduced ? { duration: 0 } : spring}
                    className="absolute inset-0 -z-10 rounded-lg shadow-sm"
                    style={{ background: s === "buy" ? "var(--market-up)" : "var(--market-down)" }}
                  />
                ) : null}
                {s}
              </button>
            ))}
          </div>

          {/* Order type */}
          <div className="isolate mt-2 flex gap-1 rounded-xl bg-muted p-1" role="tablist" aria-label="Order type">
            {TYPES.map((t) => (
              <button
                key={t.key}
                role="tab"
                aria-selected={type === t.key}
                onClick={() => setType(t.key)}
                className={cn(
                  "relative flex-1 rounded-lg px-1 py-1.5 type-meta font-medium transition-colors duration-200",
                  type === t.key ? "text-primary-foreground" : "text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {type === t.key ? (
                  <motion.span
                    layoutId={`type-${uid}`}
                    transition={reduced ? { duration: 0 } : spring}
                    className="absolute inset-0 -z-10 rounded-lg bg-primary shadow-sm"
                  />
                ) : null}
                {t.label}
              </button>
            ))}
          </div>

          {/* Qty + prices */}
          <div className="mt-4 flex gap-2">
            <label className="flex w-28 flex-col gap-1.5 type-meta font-medium text-muted-foreground">
              Lots ({lotSize}/lot)
              <div className="flex h-10 items-stretch gap-1 rounded-xl border border-input bg-background p-1 shadow-xs">
                <button
                  type="button"
                  aria-label="Decrease lots"
                  onClick={() => setLots((l) => Math.max(1, l - 1))}
                  className="flex aspect-square items-center justify-center rounded-lg text-foreground transition-colors hover:bg-muted active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" className="size-3.5" aria-hidden="true"><path d="M5 12h14" /></svg>
                </button>
                <span className="flex flex-1 items-center justify-center font-mono text-sm numeric text-foreground">
                  {lots}
                </span>
                <button
                  type="button"
                  aria-label="Increase lots"
                  onClick={() => setLots((l) => Math.min(20, l + 1))}
                  className="flex aspect-square items-center justify-center rounded-lg text-foreground transition-colors hover:bg-muted active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" className="size-3.5" aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg>
                </button>
              </div>
            </label>
            {needsTrigger ? numField("Trigger", trigger, setTrigger) : null}
            {numField(
              type === "market" ? "Price (mkt)" : "Price",
              type === "market" ? nf2.format(effPrice) : price,
              setPrice,
              type === "market"
            )}
          </div>

          {/* Margin */}
          <div className="mt-4 flex items-baseline justify-between text-xs">
            <span className="text-muted-foreground">Margin required</span>
            <span
              className={cn(
                "text-sm font-semibold numeric",
                overMargin ? "text-destructive" : "text-foreground"
              )}
            >
              <NumberFlow value={margin} prefix="₹" locale="en-IN" />
            </span>
          </div>
          <div className="mt-1.5 h-2 overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border/40" aria-hidden="true">
            <span
              className="block h-full rounded-full transition-[width] duration-500"
              style={{
                width: `${Math.min(100, (margin / availableMargin) * 100)}%`,
                background: overMargin
                  ? "linear-gradient(90deg, color-mix(in oklab, var(--destructive) 55%, transparent), var(--destructive))"
                  : `linear-gradient(90deg, color-mix(in oklab, ${sideColor} 50%, transparent), ${sideColor})`,
              }}
            />
          </div>
          <p className="mt-1.5 type-meta numeric text-muted-foreground">
            Available ₹{inr(availableMargin)}
            {overMargin ? (
              <span className="ml-1 font-medium text-destructive">
                — exceeds margin, reduce quantity
              </span>
            ) : null}
          </p>

          {/* Charges */}
          <button
            type="button"
            aria-expanded={chargesOpen}
            onClick={() => setChargesOpen((o) => !o)}
            className="mt-3 flex w-full items-center justify-between rounded-lg py-1 type-meta text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <span>Charges ≈ ₹{inr(charges)}</span>
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className={cn("size-3.5 transition-transform duration-300", chargesOpen && "rotate-180")} aria-hidden="true"><path d="M6 9l6 6 6-6" /></svg>
          </button>
          <div ref={chargesRef} className="overflow-hidden" style={{ height: 0, opacity: 0 }}>
            <dl className="flex flex-col gap-1 rounded-xl bg-muted/50 p-2.5 type-meta numeric text-muted-foreground">
              <div className="flex justify-between"><dt>Brokerage</dt><dd>₹{brokerage}</dd></div>
              <div className="flex justify-between"><dt>STT</dt><dd>₹{inr(stt)}</dd></div>
              <div className="flex justify-between"><dt>Exchange + GST + stamp</dt><dd>₹{inr(other)}</dd></div>
            </dl>
          </div>

          {/* Action */}
          {stage === "form" ? (
            <Button
              className={cn(
                "mt-4 w-full text-white shadow-sm",
                side === "buy"
                  ? "bg-market-up hover:bg-market-up/90"
                  : "bg-market-down hover:bg-market-down/90"
              )}
              disabled={overMargin || (needsPrice && !parseFloat(price))}
              onClick={() => setStage("review")}
            >
              Review {side} order
            </Button>
          ) : (
            <div className="mt-4 flex flex-col gap-2 rounded-2xl border border-border/60 bg-background/60 p-3.5">
              <p className="text-xs text-foreground">
                <span className={cn("font-semibold uppercase", side === "buy" ? "text-market-up" : "text-market-down")}>
                  {side}
                </span>{" "}
                {qty} {symbol} · {TYPES.find((t) => t.key === type)?.label}
                {needsPrice ? ` @ ₹${price}` : " @ market"}
                {needsTrigger ? ` · trigger ₹${trigger}` : ""}
              </p>
              <p className="type-meta numeric text-muted-foreground">
                Margin ₹{inr(margin)} + charges ₹{inr(charges)}
              </p>
              <div className="flex gap-2">
                <Button size="sm" variant="outline" onClick={() => setStage("form")}>
                  Edit
                </Button>
                <Button
                  size="sm"
                  className={cn(
                    "flex-1 text-white",
                    side === "buy"
                      ? "bg-market-up hover:bg-market-up/90"
                      : "bg-market-down hover:bg-market-down/90"
                  )}
                  onClick={place}
                >
                  Confirm
                </Button>
              </div>
            </div>
          )}
        </LayoutGroup>
      ) : (
        <FillState
          stage={stage}
          side={side}
          qty={qty}
          filled={filled}
          symbol={symbol}
          onReset={reset}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Placement / partial fill                                             */
/* ------------------------------------------------------------------ */

function FillState({
  stage,
  side,
  qty,
  filled,
  symbol,
  onReset,
}: {
  stage: Stage;
  side: "buy" | "sell";
  qty: number;
  filled: number;
  symbol: string;
  onReset: () => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const pct = Math.round((filled / qty) * 100);
  const sideColor = side === "buy" ? "var(--market-up)" : "var(--market-down)";

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 12, filter: "blur(6px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.4, ease: "power3.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );

  return (
    <div ref={ref} className="mt-5 flex flex-col items-center gap-3 py-2 text-center">
      <p className="text-sm font-medium text-foreground">
        {stage === "placing"
          ? "Placing order…"
          : stage === "filling"
            ? pct < 100
              ? "Partially filled"
              : "Filling…"
            : "Order complete"}
      </p>
      <div
        className="h-2.5 w-full overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border/40"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={qty}
        aria-valuenow={filled}
        aria-label="Fill progress"
      >
        <span
          className="block h-full rounded-full transition-[width] duration-700 ease-out"
          style={{
            width: `${stage === "placing" ? 4 : pct}%`,
            background: `linear-gradient(90deg, color-mix(in oklab, ${sideColor} 55%, transparent), ${sideColor})`,
          }}
        />
      </div>
      <p className="text-xs numeric text-muted-foreground">
        {filled}/{qty} {symbol}
        {stage === "filling" && pct < 100 ? " · working the rest at your limit" : ""}
      </p>
      {stage === "done" ? (
        <Button size="sm" variant="outline" onClick={onReset}>
          New order
        </Button>
      ) : null}
    </div>
  );
}

registry/default/fintech/strategy-builde:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { LayoutGroup, motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { blackScholes, smileIv } from "@/registry/default/lib/black-scholes";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

const pillSpring = { type: "spring", stiffness: 480, damping: 38 } as const;

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface StrategyLeg {
  side: "buy" | "sell";
  type: "call" | "put";
  strike: number;
  premium: number;
  delta: number;
  theta: number;
  vega: number;
}

export type StrategyKey =
  | "long-call"
  | "bull-call-spread"
  | "straddle"
  | "strangle"
  | "iron-condor";

export const STRATEGIES: Record<StrategyKey, { label: string; legs: (atm: number, step: number) => { side: "buy" | "sell"; type: "call" | "put"; strike: number }[] }> = {
  "long-call": {
    label: "Long Call",
    legs: (atm) => [{ side: "buy", type: "call", strike: atm }],
  },
  "bull-call-spread": {
    label: "Bull Call Spread",
    legs: (atm, step) => [
      { side: "buy", type: "call", strike: atm },
      { side: "sell", type: "call", strike: atm + 2 * step },
    ],
  },
  straddle: {
    label: "Straddle",
    legs: (atm) => [
      { side: "buy", type: "call", strike: atm },
      { side: "buy", type: "put", strike: atm },
    ],
  },
  strangle: {
    label: "Strangle",
    legs: (atm, step) => [
      { side: "buy", type: "call", strike: atm + 2 * step },
      { side: "buy", type: "put", strike: atm - 2 * step },
    ],
  },
  "iron-condor": {
    label: "Iron Condor",
    legs: (atm, step) => [
      { side: "sell", type: "put", strike: atm - 2 * step },
      { side: "buy", type: "put", strike: atm - 4 * step },
      { side: "sell", type: "call", strike: atm + 2 * step },
      { side: "buy", type: "call", strike: atm + 4 * step },
    ],
  },
};

export interface StrategyBuilderProps
  extends React.HTMLAttributes<HTMLDivElement> {
  spot: number;
  /** Days to expiry used to price the legs. Default 7. */
  dte?: number;
  /** Strike interval. Default 100. */
  step?: number;
  lotSize?: number;
  defaultStrategy?: StrategyKey;
  ref?: React.Ref<HTMLDivElement>;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);

/* ------------------------------------------------------------------ */
/* Builder                                                              */
/* ------------------------------------------------------------------ */

const W = 480;
const H = 190;
const PAD = { l: 10, r: 10, t: 14, b: 20 };

/**
 * Options strategy builder: pick a structure and the payoff curve morphs
 * to it — profit region in market-up, loss in market-down, breakevens
 * marked, leg Greeks totalled, and an expiry-spot scrubber that rolls the
 * P&L as you drag.
 */
export function StrategyBuilder({
  spot,
  dte = 7,
  step = 100,
  lotSize = 75,
  defaultStrategy = "bull-call-spread",
  className,
  ref,
  ...rest
}: StrategyBuilderProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const lineRef = React.useRef<SVGPathElement>(null);
  const areaRef = React.useRef<SVGPathElement>(null);
  const areaLossRef = React.useRef<SVGPathElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [strategy, setStrategy] = React.useState<StrategyKey>(defaultStrategy);
  const atm = Math.round(spot / step) * step;
  const [expirySpot, setExpirySpot] = React.useState(atm);

  /* Price the legs coherently. */
  const legs: StrategyLeg[] = React.useMemo(
    () =>
      STRATEGIES[strategy].legs(atm, step).map((l) => {
        const iv = smileIv(spot, l.strike);
        const g = blackScholes({ s: spot, k: l.strike, t: dte / 365, iv, side: l.type });
        const sign = l.side === "buy" ? 1 : -1;
        return {
          ...l,
          premium: g.price,
          delta: sign * g.delta,
          theta: sign * g.theta,
          vega: sign * g.vega,
        };
      }),
    [strategy, atm, step, spot, dte]
  );

  const payoffAt = React.useCallback(
    (s: number) =>
      legs.reduce((sum, l) => {
        const intrinsic = l.type === "call" ? Math.max(0, s - l.strike) : Math.max(0, l.strike - s);
        const sign = l.side === "buy" ? 1 : -1;
        return sum + sign * (intrinsic - l.premium);
      }, 0) * lotSize,
    [legs, lotSize]
  );

  /* Sample the payoff across ±10%. */
  const sMin = spot * 0.9;
  const sMax = spot * 1.1;
  const N = 80;
  const samples = React.useMemo(
    () =>
      Array.from({ length: N + 1 }, (_, i) => {
        const s = sMin + ((sMax - sMin) * i) / N;
        return { s, p: payoffAt(s) };
      }),
    [payoffAt, sMin, sMax]
  );
  const pMax = Math.max(...samples.map((d) => Math.abs(d.p)), 1);
  const x = (s: number) => PAD.l + ((s - sMin) / (sMax - sMin)) * (W - PAD.l - PAD.r);
  const y = (p: number) => H / 2 - (p / pMax) * (H / 2 - PAD.t);
  const zeroY = y(0);

  const linePath = samples
    .map((d, i) => `${i === 0 ? "M" : "L"}${x(d.s).toFixed(1)},${y(d.p).toFixed(1)}`)
    .join(" ");
  const areaPath = `${linePath} L${x(sMax).toFixed(1)},${zeroY} L${x(sMin).toFixed(1)},${zeroY} Z`;

  /* Breakevens: zero crossings. */
  const breakevens: number[] = [];
  for (let i = 1; i < samples.length; i++) {
    const a = samples[i - 1];
    const b = samples[i];
    if ((a.p <= 0 && b.p > 0) || (a.p >= 0 && b.p < 0)) {
      breakevens.push(a.s + ((0 - a.p) / (b.p - a.p)) * (b.s - a.s));
    }
  }

  const maxProfitRaw = Math.max(...samples.map((d) => d.p));
  const maxLossRaw = Math.min(...samples.map((d) => d.p));
  const edgeUp = samples[samples.length - 1].p >= maxProfitRaw - 1;
  const edgeDown = samples[0].p <= maxLossRaw + 1 && strategy !== "iron-condor";
  const netPremium = legs.reduce(
    (s, l) => s + (l.side === "buy" ? -1 : 1) * l.premium * lotSize,
    0
  );
  const totals = legs.reduce(
    (t, l) => ({ delta: t.delta + l.delta, theta: t.theta + l.theta, vega: t.vega + l.vega }),
    { delta: 0, theta: 0, vega: 0 }
  );

  /* The curve morphs between strategies. */
  useGSAP(
    () => {
      const items: [SVGPathElement | null, string][] = [
        [lineRef.current, linePath],
        [areaRef.current, areaPath],
        [areaLossRef.current, areaPath],
      ];
      for (const [el, d] of items) {
        if (!el) continue;
        if (reduced) el.setAttribute("d", d);
        else gsap.to(el, { attr: { d }, duration: 0.55, ease: "power3.inOut", overwrite: true });
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    { dependencies: [linePath, reduced] }
  );

  const pnlAtScrub = payoffAt(expirySpot);

  return (
    <div
      ref={rootRef}
      data-slot="strategy-builder"
      className={cn(
        "relative w-full max-w-xl overflow-hidden rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      {/* Strategy picker */}
      <LayoutGroup id={uid}>
        <div className="isolate flex flex-wrap gap-1.5" role="tablist" aria-label="Strategy">
          {(Object.keys(STRATEGIES) as StrategyKey[]).map((k) => (
            <button
              key={k}
              role="tab"
              aria-selected={strategy === k}
              onClick={() => setStrategy(k)}
              className={cn(
                "relative rounded-lg px-3 py-1.5 text-xs font-medium transition-colors duration-200",
                strategy === k ? "text-primary-foreground" : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              {strategy === k ? (
                <motion.span
                  layoutId={`strat-${uid}`}
                  transition={reduced ? { duration: 0 } : pillSpring}
                  className="absolute inset-0 -z-10 rounded-lg bg-primary shadow-sm"
                />
              ) : null}
              {STRATEGIES[k].label}
            </button>
          ))}
        </div>
      </LayoutGroup>

      {/* Payoff chart */}
      <svg
        viewBox={`0 0 ${W} ${H}`}
        className="mt-4 w-full"
        role="img"
        aria-label={`${STRATEGIES[strategy].label} payoff at expiry. Max profit ${edgeUp ? "unlimited" : `₹${inr(maxProfitRaw)}`}, max loss ${edgeDown ? "unlimited" : `₹${inr(Math.abs(maxLossRaw))}`}.`}
      >
        <defs>
          <clipPath id={`profit-clip-${uid}`}>
            <rect x={0} y={0} width={W} height={zeroY} />
          </clipPath>
          <clipPath id={`loss-clip-${uid}`}>
            <rect x={0} y={zeroY} width={W} height={H - zeroY} />
          </clipPath>
          <linearGradient id={`profit-fill-${uid}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--market-up)" stopOpacity={0.3} />
            <stop offset="100%" stopColor="var(--market-up)" stopOpacity={0.02} />
          </linearGradient>
          <linearGradient id={`loss-fill-${uid}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--market-down)" stopOpacity={0.02} />
            <stop offset="100%" stopColor="var(--market-down)" stopOpacity={0.3} />
          </linearGradient>
          <filter id={`line-glow-${uid}`} x="-5%" y="-40%" width="110%" height="180%">
            <feDropShadow dx="0" dy="1" stdDeviation="1.5" floodColor="var(--foreground)" floodOpacity="0.18" />
          </filter>
        </defs>
        <path ref={areaRef} d={areaPath} clipPath={`url(#profit-clip-${uid})`} fill={`url(#profit-fill-${uid})`} />
        <path ref={areaLossRef} d={areaPath} clipPath={`url(#loss-clip-${uid})`} fill={`url(#loss-fill-${uid})`} />
        <line x1={PAD.l} x2={W - PAD.r} y1={zeroY} y2={zeroY} className="stroke-border" strokeDasharray="2 3" />
        {/* spot + scrub markers */}
        <line x1={x(spot)} x2={x(spot)} y1={PAD.t} y2={H - PAD.b} strokeDasharray="3 3" className="stroke-muted-foreground/40" />
        <text x={x(spot)} y={H - 5} textAnchor="middle" className="fill-muted-foreground text-[9px]">spot</text>
        <line x1={x(expirySpot)} x2={x(expirySpot)} y1={PAD.t} y2={H - PAD.b} className="stroke-info" strokeWidth={1.25} />
        <circle cx={x(expirySpot)} cy={y(pnlAtScrub)} r={6} fill="var(--info)" opacity={0.25} />
        <circle cx={x(expirySpot)} cy={y(pnlAtScrub)} r={3.5} className="fill-info stroke-card" strokeWidth={2} style={{ filter: "drop-shadow(0 0 4px color-mix(in oklab, var(--info) 60%, transparent))" }} />
        {breakevens.map((b) => (
          <g key={b}>
            <line x1={x(b)} x2={x(b)} y1={zeroY - 6} y2={zeroY + 6} className="stroke-foreground" strokeWidth={1.5} />
            <text x={x(b)} y={zeroY - 9} textAnchor="middle" className="fill-foreground text-[9px] font-medium tabular-nums">
              {inr(Math.round(b))}
            </text>
          </g>
        ))}
        <path ref={lineRef} d={linePath} fill="none" strokeWidth={2.25} strokeLinejoin="round" className="stroke-primary" filter={`url(#line-glow-${uid})`} />
      </svg>

      {/* Expiry scrubber */}
      <div className="mt-2 flex items-center gap-3 text-xs text-muted-foreground">
        <span className="shrink-0">Expiry spot</span>
        <span className="relative flex h-6 flex-1 items-center">
          <span className="pointer-events-none absolute inset-x-0 top-1/2 h-1.5 -translate-y-1/2 rounded-full bg-muted ring-1 ring-inset ring-border/50" />
          <span
            className="pointer-events-none absolute left-0 top-1/2 h-1.5 -translate-y-1/2 rounded-full"
            style={{
              width: `${((expirySpot - Math.ceil(sMin / 10) * 10) / (Math.floor(sMax / 10) * 10 - Math.ceil(sMin / 10) * 10)) * 100}%`,
              background: pnlAtScrub >= 0
                ? "linear-gradient(90deg, color-mix(in oklab, var(--market-up) 50%, transparent), var(--market-up))"
                : "linear-gradient(90deg, color-mix(in oklab, var(--market-down) 50%, transparent), var(--market-down))",
            }}
          />
          <input
            type="range"
            min={Math.ceil(sMin / 10) * 10}
            max={Math.floor(sMax / 10) * 10}
            step={10}
            value={expirySpot}
            aria-label="Expiry spot"
            onChange={(e) => setExpirySpot(parseInt(e.target.value, 10))}
            className="peer absolute inset-0 z-20 w-full cursor-pointer appearance-none bg-transparent opacity-0"
          />
          <span
            className={cn(
              "pointer-events-none absolute top-1/2 z-10 size-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 bg-background shadow-md transition-colors peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-background",
              pnlAtScrub >= 0 ? "border-market-up" : "border-market-down"
            )}
            style={{ left: `${((expirySpot - Math.ceil(sMin / 10) * 10) / (Math.floor(sMax / 10) * 10 - Math.ceil(sMin / 10) * 10)) * 100}%` }}
          />
        </span>
        <span
          className={cn(
            "w-24 shrink-0 text-right font-semibold numeric",
            pnlAtScrub >= 0 ? "text-market-up" : "text-market-down"
          )}
        >
          <NumberFlow
            value={Math.abs(Math.round(pnlAtScrub))}
            prefix={pnlAtScrub >= 0 ? "+₹" : "−₹"}
            locale="en-IN"
          />
        </span>
      </div>

      {/* Stats */}
      <div className="mt-4 grid grid-cols-2 gap-2 text-xs sm:grid-cols-4">
        {([
          ["Max profit", edgeUp ? "Unlimited" : `₹${inr(maxProfitRaw)}`, "text-market-up", "var(--market-up)"],
          ["Max loss", edgeDown ? "Unlimited" : `₹${inr(Math.abs(maxLossRaw))}`, "text-market-down", "var(--market-down)"],
          ["Net premium", `${netPremium >= 0 ? "+" : "−"}₹${inr(Math.abs(netPremium))}`, netPremium >= 0 ? "text-market-up" : "text-foreground", "var(--info)"],
          ["Breakevens", breakevens.length ? breakevens.map((b) => inr(Math.round(b))).join(" / ") : "—", "text-foreground", "var(--foreground)"],
        ] as const).map(([label, value, cls, accent]) => (
          <div key={label} className="relative overflow-hidden rounded-xl border border-border/60 bg-background/60 px-3 py-2 shadow-xs">
            <span aria-hidden="true" className="absolute inset-y-2 left-0 w-0.5 rounded-full opacity-70" style={{ background: accent }} />
            <p className="pl-1.5 type-overline text-muted-foreground">{label}</p>
            <p className={cn("pl-1.5 font-semibold numeric", cls)}>{value}</p>
          </div>
        ))}
      </div>

      {/* Legs */}
      <ul className="mt-3 flex flex-col gap-1.5">
        {legs.map((l, i) => (
          <li
            key={`${l.side}-${l.type}-${l.strike}-${i}`}
            className="flex items-center justify-between gap-2 rounded-xl border border-border/60 bg-background/60 px-3 py-2 text-xs shadow-xs"
          >
            <span className="flex items-center gap-2">
              <span
                className={cn(
                  "rounded-md px-1.5 py-0.5 type-overline font-semibold ring-1 ring-inset",
                  l.side === "buy"
                    ? "bg-market-up/10 text-market-up ring-market-up/20"
                    : "bg-market-down/10 text-market-down ring-market-down/20"
                )}
              >
                {l.side}
              </span>
              <span className="font-medium text-foreground">
                {inr(l.strike)} {l.type.toUpperCase()}
              </span>
            </span>
            <span className="numeric text-muted-foreground">
              ₹{l.premium.toFixed(2)} · Δ {l.delta.toFixed(2)}
            </span>
          </li>
        ))}
      </ul>

      <p className="mt-2 flex flex-wrap justify-between gap-2 type-meta numeric text-muted-foreground">
        <span>
          Net Δ {totals.delta.toFixed(2)} · Θ ₹{(totals.theta * lotSize).toFixed(0)}/day · V ₹
          {(totals.vega * lotSize).toFixed(0)}/1% IV
        </span>
        <span>1 lot = {lotSize} · payoff at expiry · not advice</span>
      </p>
    </div>
  );
}

registry/default/fintech/bank-linking.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Badge } from "@/registry/default/ui/badge";
import { OTPInput } from "@/registry/default/fintech/otp-input";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface LinkableBank {
  id: string;
  name: string;
  /** Tailwind color class for the tile mark. */
  tone: string;
}

export interface LinkableAccount {
  id: string;
  label: string;
  masked: string;
  balance?: string;
}

export interface BankLinkingProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onComplete"> {
  banks?: LinkableBank[];
  accounts?: LinkableAccount[];
  /** The demo OTP that succeeds. Any other code shows the error state. */
  validOtp?: string;
  /** Consent validity shown on the review screen, in months. */
  consentMonths?: number;
  onLinked?: (detail: { bank: string; accountIds: string[] }) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_BANKS: LinkableBank[] = [
  { id: "hdfc", name: "HDFC Bank", tone: "bg-blue-600" },
  { id: "icici", name: "ICICI Bank", tone: "bg-orange-600" },
  { id: "sbi", name: "SBI", tone: "bg-sky-700" },
  { id: "axis", name: "Axis Bank", tone: "bg-rose-700" },
  { id: "kotak", name: "Kotak", tone: "bg-red-600" },
  { id: "yes", name: "Yes Bank", tone: "bg-indigo-600" },
];

export const DEMO_ACCOUNTS: LinkableAccount[] = [
  { id: "sav", label: "Savings", masked: "••6482", balance: "₹1,84,210" },
  { id: "sal", label: "Salary", masked: "••1039", balance: "₹52,904" },
];

const PERMISSIONS = [
  { key: "balance", label: "Account balance", detail: "Refreshed daily" },
  { key: "transactions", label: "Transactions", detail: "Last 12 months, then ongoing" },
  { key: "profile", label: "Account holder name", detail: "For verification only" },
] as const;

type Step = 0 | 1 | 2 | 3 | 4;

/* ------------------------------------------------------------------ */
/* Flow                                                                 */
/* ------------------------------------------------------------------ */

/**
 * Account-aggregator style bank linking: pick a bank, review exactly what
 * is shared and for how long, confirm with OTP, choose accounts, and land
 * on a connection-health card with reauthentication date.
 */
export function BankLinking({
  banks = DEMO_BANKS,
  accounts = DEMO_ACCOUNTS,
  validOtp = "246810",
  consentMonths = 12,
  onLinked,
  className,
  ref,
  ...rest
}: BankLinkingProps) {
  const reduced = useReducedMotion();
  const [step, setStep] = React.useState<Step>(0);
  const [bank, setBank] = React.useState<LinkableBank | null>(null);
  const [otpError, setOtpError] = React.useState(false);
  const [otpAttempt, setOtpAttempt] = React.useState(0);
  const [verifying, setVerifying] = React.useState(false);
  const [picked, setPicked] = React.useState<string[]>(accounts.map((a) => a.id));
  const [linking, setLinking] = React.useState(false);

  const panelRef = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!panelRef.current) return;
      if (reduced) {
        gsap.set(panelRef.current, { x: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        panelRef.current,
        { x: 24, opacity: 0, filter: "blur(6px)" },
        { x: 0, opacity: 1, filter: "blur(0px)", duration: 0.4, ease: "power3.out", clearProps: "filter" }
      );
    },
    { dependencies: [step], scope: panelRef }
  );

  const submitOtp = async (code: string) => {
    setVerifying(true);
    await new Promise((r) => setTimeout(r, 900));
    setVerifying(false);
    if (code !== validOtp) {
      setOtpError(true);
      // clear the cells for a fresh attempt once the shake has landed
      setTimeout(() => {
        setOtpError(false);
        setOtpAttempt((a) => a + 1);
      }, 1200);
      return;
    }
    setStep(3);
  };

  const finish = async () => {
    setLinking(true);
    await new Promise((r) => setTimeout(r, 1300));
    setLinking(false);
    setStep(4);
    if (bank) onLinked?.({ bank: bank.id, accountIds: picked });
  };

  const stepTitle = [
    "Choose your bank",
    "Review consent",
    "Verify it's you",
    "Select accounts",
    "Connected",
  ][step];

  return (
    <div
      ref={ref}
      data-slot="bank-linking"
      className={cn(
        "w-full max-w-sm rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2">
        <h3 className="type-title text-foreground">{stepTitle}</h3>
        <span className="type-meta numeric text-muted-foreground">
          {Math.min(step + 1, 5)}/5
        </span>
      </div>
      <div className="mt-2.5 h-1.5 overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border/40" aria-hidden="true">
        <span
          className="block h-full rounded-full transition-all duration-500 ease-out"
          style={{
            width: `${((step + 1) / 5) * 100}%`,
            background: "linear-gradient(90deg, color-mix(in oklab, var(--primary) 55%, transparent), var(--primary))",
          }}
        />
      </div>

      <div ref={panelRef} className="mt-4">
        {step === 0 ? (
          <div className="grid grid-cols-3 gap-2">
            {banks.map((b) => (
              <button
                key={b.id}
                type="button"
                onClick={() => {
                  setBank(b);
                  setStep(1);
                }}
                className="group/bank flex flex-col items-center gap-2 rounded-2xl border border-border/60 bg-background/60 p-3.5 shadow-xs transition-[transform,box-shadow,border-color,background-color] duration-200 ease-out-expo hover:-translate-y-0.5 hover:border-ring/30 hover:shadow-md active:translate-y-0 active:scale-[0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring motion-reduce:hover:translate-y-0"
              >
                <span
                  aria-hidden="true"
                  className={cn(
                    "flex size-9 items-center justify-center rounded-full type-meta font-bold text-white shadow-sm ring-1 ring-inset ring-white/15 transition-transform duration-200 group-hover/bank:scale-105 motion-reduce:group-hover/bank:scale-100",
                    b.tone
                  )}
                >
                  {b.name[0]}
                </span>
                <span className="type-meta font-medium text-foreground">{b.name}</span>
              </button>
            ))}
          </div>
        ) : null}

        {step === 1 && bank ? (
          <div className="flex flex-col gap-3">
            <p className="text-xs text-muted-foreground">
              <span className="font-medium text-foreground">{bank.name}</span> will share the
              following, read-only, for {consentMonths} months. You can revoke
              any time.
            </p>
            <ul className="flex flex-col gap-1.5">
              {PERMISSIONS.map((p) => (
                <li
                  key={p.key}
                  className="flex items-start justify-between gap-2 rounded-lg border border-border bg-background px-2.5 py-2 text-xs"
                >
                  <span className="font-medium text-foreground">{p.label}</span>
                  <span className="text-right text-muted-foreground">{p.detail}</span>
                </li>
              ))}
            </ul>
            <p className="type-meta leading-4 text-muted-foreground">
              We never see your bank credentials — the OTP goes to the number
              your bank has on record.
            </p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(0)}>
                Back
              </Button>
              <Button className="flex-1" onClick={() => setStep(2)}>
                Agree & continue
              </Button>
            </div>
          </div>
        ) : null}

        {step === 2 && bank ? (
          <div className="flex flex-col items-center gap-3">
            <p className="text-xs text-muted-foreground">
              Enter the 6-digit code sent by {bank.name}
              <span className="ml-1 rounded bg-muted px-1 py-0.5 font-mono type-caption">
                demo: {validOtp}
              </span>
            </p>
            <OTPInput key={otpAttempt} length={6} error={otpError} onComplete={submitOtp} />
            <p aria-live="polite" className="min-h-4 type-meta">
              {verifying ? (
                <span className="text-muted-foreground">Verifying…</span>
              ) : otpError ? (
                <span className="font-medium text-destructive">
                  That code didn&apos;t match — try again.
                </span>
              ) : null}
            </p>
            <Button variant="outline" size="sm" onClick={() => setStep(1)}>
              Back
            </Button>
          </div>
        ) : null}

        {step === 3 ? (
          <div className="flex flex-col gap-3">
            <ul className="flex flex-col gap-1.5">
              {accounts.map((a) => {
                const on = picked.includes(a.id);
                return (
                  <li key={a.id}>
                    <button
                      type="button"
                      role="checkbox"
                      aria-checked={on}
                      onClick={() =>
                        setPicked((p) =>
                          on ? p.filter((x) => x !== a.id) : [...p, a.id]
                        )
                      }
                      className={cn(
                        "flex w-full items-center justify-between gap-2 rounded-xl border px-3 py-2.5 text-left transition-all duration-200",
                        on ? "border-primary bg-primary/5" : "border-border bg-background",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      )}
                    >
                      <span>
                        <span className="block text-sm font-medium text-foreground">
                          {a.label} {a.masked}
                        </span>
                        {a.balance ? (
                          <span className="type-meta numeric text-muted-foreground">
                            {a.balance}
                          </span>
                        ) : null}
                      </span>
                      <span
                        aria-hidden="true"
                        className={cn(
                          "flex size-5 items-center justify-center rounded-full border-2 transition-colors duration-200",
                          on ? "border-primary bg-primary text-primary-foreground" : "border-border"
                        )}
                      >
                        {on ? (
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3">
                            <path d="M5 13l4 4L19 7" />
                          </svg>
                        ) : null}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
            <Button
              className="w-full"
              disabled={picked.length === 0}
              loading={linking}
              onClick={finish}
            >
              Link {picked.length} account{picked.length === 1 ? "" : "s"}
            </Button>
          </div>
        ) : null}

        {step === 4 && bank ? (
          <div className="flex flex-col gap-3">
            <div className="flex items-center gap-3 rounded-xl border border-success/40 bg-success/5 p-3">
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-9 items-center justify-center rounded-full text-xs font-bold text-white",
                  bank.tone
                )}
              >
                {bank.name[0]}
              </span>
              <div className="flex-1">
                <p className="type-title text-foreground">{bank.name}</p>
                <p className="type-meta text-muted-foreground">
                  {picked.length} account{picked.length === 1 ? "" : "s"} · synced just now
                </p>
              </div>
              <Badge variant="success" pulse>
                Healthy
              </Badge>
            </div>
            <dl className="flex flex-col gap-1 rounded-xl border border-border bg-background p-3 type-meta numeric text-muted-foreground">
              <div className="flex justify-between">
                <dt>Consent valid until</dt>
                <dd className="text-foreground">
                  {new Date(Date.now() + consentMonths * 30 * 864e5).toLocaleDateString("en-GB", { month: "short", year: "numeric" })}
                </dd>
              </div>
              <div className="flex justify-between">
                <dt>Next auto-sync</dt>
                <dd className="text-foreground">Tomorrow, 6:00 AM</dd>
              </div>
              <div className="flex justify-between">
                <dt>Reauthentication</dt>
                <dd className="text-foreground">Not needed for {consentMonths} months</dd>
              </div>
            </dl>
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                setStep(0);
                setBank(null);
                setPicked(accounts.map((a) => a.id));
              }}
            >
              Link another bank
            </Button>
          </div>
        ) : null}
      </div>
    </div>
  );
}

registry/default/fintech/expense-feed.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { LayoutGroup, motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Badge } from "@/registry/default/ui/badge";

const filterSpring = { type: "spring", stiffness: 480, damping: 38 } as const;

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type ExpenseCategory =
  | "food"
  | "transport"
  | "subscriptions"
  | "shopping"
  | "utilities"
  | "income";

export interface ExpenseItem {
  id: string;
  merchant: string;
  day: string;
  amount: number;
  category: ExpenseCategory;
  /** Nth consecutive monthly charge → subscription badge. */
  recurringMonth?: number;
  /** Marks an unusually large charge with the multiple vs usual. */
  unusualMultiple?: number;
  /** Refund linked to an earlier transaction id. */
  refundOf?: string;
}

export interface ExpenseFeedProps
  extends React.HTMLAttributes<HTMLDivElement> {
  items?: ExpenseItem[];
  currency?: string;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_EXPENSES: ExpenseItem[] = [
  { id: "t1", merchant: "Swiggy", day: "Today", amount: -412, category: "food" },
  { id: "t2", merchant: "Netflix", day: "Today", amount: -649, category: "subscriptions", recurringMonth: 7 },
  { id: "t3", merchant: "Uber", day: "Today", amount: -284, category: "transport" },
  { id: "t4", merchant: "Croma", day: "Yesterday", amount: -42_499, category: "shopping", unusualMultiple: 9 },
  { id: "t5", merchant: "Salary · Acme Corp", day: "Yesterday", amount: 145_000, category: "income" },
  { id: "t6", merchant: "Spotify", day: "Yesterday", amount: -119, category: "subscriptions", recurringMonth: 14 },
  { id: "t7", merchant: "BESCOM", day: "Mon 8 Jul", amount: -1_840, category: "utilities" },
  { id: "t8", merchant: "Croma (refund)", day: "Mon 8 Jul", amount: 4_500, category: "shopping", refundOf: "t4" },
  { id: "t9", merchant: "Blinkit", day: "Mon 8 Jul", amount: -876, category: "food" },
];

const CATEGORY_META: Record<ExpenseCategory, { label: string; dot: string }> = {
  food: { label: "Food", dot: "bg-amber-500" },
  transport: { label: "Transport", dot: "bg-sky-500" },
  subscriptions: { label: "Subscriptions", dot: "bg-violet-500" },
  shopping: { label: "Shopping", dot: "bg-rose-500" },
  utilities: { label: "Utilities", dot: "bg-teal-500" },
  income: { label: "Income", dot: "bg-emerald-500" },
};

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(Math.abs(n));

/* ------------------------------------------------------------------ */
/* Feed                                                                 */
/* ------------------------------------------------------------------ */

/**
 * An expense feed that understands itself: merchants are categorised,
 * subscriptions counted, unusual charges flagged with how unusual they
 * are, refunds linked back to the original transaction — and category
 * filters re-cascade the list.
 */
export function ExpenseFeed({
  items = DEMO_EXPENSES,
  currency = "₹",
  className,
  ref,
  ...rest
}: ExpenseFeedProps) {
  const reduced = useReducedMotion();
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [filter, setFilter] = React.useState<ExpenseCategory | "all">("all");
  const [query, setQuery] = React.useState("");
  const [linked, setLinked] = React.useState<string | null>(null);

  const visible = items.filter(
    (i) =>
      (filter === "all" || i.category === filter) &&
      i.merchant.toLowerCase().includes(query.toLowerCase())
  );
  const days = [...new Set(visible.map((i) => i.day))];
  const usedCategories = [...new Set(items.map((i) => i.category))];

  /* Rows cascade in whenever the visible set changes. */
  useGSAP(
    () => {
      const list = listRef.current;
      if (!list) return;
      const rows = gsap.utils.toArray<HTMLElement>(list.querySelectorAll("[data-row]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 10, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.3, ease: "power2.out", stagger: 0.035, overwrite: true }
      );
    },
    { dependencies: [filter, query, reduced], scope: listRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="expense-feed"
      className={cn(
        "w-full max-w-md rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      {/* Search + filters */}
      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search merchants…"
        aria-label="Search transactions"
        className="h-10 w-full rounded-xl border border-input bg-background px-3.5 text-sm text-foreground shadow-xs transition-[border-color,box-shadow] duration-200 placeholder:text-muted-foreground/60 hover:border-ring/30 focus-visible:outline-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/25"
      />
      <LayoutGroup id={uid}>
        <div className="isolate mt-2.5 flex flex-wrap gap-1.5">
          {(["all", ...usedCategories] as const).map((c) => (
            <button
              key={c}
              type="button"
              aria-pressed={filter === c}
              onClick={() => setFilter(c as ExpenseCategory | "all")}
              className={cn(
                "relative flex items-center gap-1.5 rounded-full px-3 py-1 type-meta font-medium transition-colors duration-200",
                filter === c ? "text-primary-foreground" : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              {filter === c ? (
                <motion.span
                  layoutId={`ef-${uid}`}
                  transition={reduced ? { duration: 0 } : filterSpring}
                  className="absolute inset-0 -z-10 rounded-full bg-primary shadow-sm"
                />
              ) : (
                <span className="absolute inset-0 -z-10 rounded-full bg-muted" />
              )}
              {c !== "all" ? (
                <span
                  aria-hidden="true"
                  className={cn("size-1.5 rounded-full", CATEGORY_META[c as ExpenseCategory].dot)}
                />
              ) : null}
              {c === "all" ? "All" : CATEGORY_META[c as ExpenseCategory].label}
            </button>
          ))}
        </div>
      </LayoutGroup>

      {/* Feed */}
      <div ref={listRef} className="mt-3 flex flex-col gap-3">
        {days.length === 0 ? (
          <p className="rounded-lg bg-muted/50 px-3 py-6 text-center text-xs text-muted-foreground">
            Nothing matches — clear the search or pick another category.
          </p>
        ) : null}
        {days.map((day) => (
          <div key={day}>
            <p className="px-1 type-overline text-muted-foreground">
              {day}
            </p>
            <ul className="mt-1 flex flex-col gap-1">
              {visible
                .filter((i) => i.day === day)
                .map((i) => {
                  const meta = CATEGORY_META[i.category];
                  const isLinkTarget = linked === i.id || (linked != null && i.refundOf === linked);
                  return (
                    <li key={i.id} data-row>
                      <div
                        className={cn(
                          "flex items-center gap-2.5 rounded-xl border px-3 py-2.5 shadow-xs transition-colors duration-300",
                          i.unusualMultiple
                            ? "border-warning/50 bg-warning/5"
                            : isLinkTarget
                              ? "border-info/60 bg-info/5"
                              : "border-border/60 bg-background/60"
                        )}
                      >
                        <span
                          aria-hidden="true"
                          className={cn(
                            "flex size-7 shrink-0 items-center justify-center rounded-full type-caption font-bold text-white",
                            meta.dot
                          )}
                        >
                          {i.merchant[0]}
                        </span>
                        <div className="min-w-0 flex-1">
                          <p className="truncate text-sm font-medium text-foreground">
                            {i.merchant}
                          </p>
                          <p className="flex flex-wrap items-center gap-1.5 type-caption text-muted-foreground">
                            {meta.label}
                            {i.recurringMonth ? (
                              <Badge variant="secondary" className="px-1 py-0 text-[9px]">
                                Subscription · month {i.recurringMonth}
                              </Badge>
                            ) : null}
                            {i.unusualMultiple ? (
                              <span className="font-medium text-warning">
                                {i.unusualMultiple}× your usual here
                              </span>
                            ) : null}
                            {i.refundOf ? (
                              <button
                                type="button"
                                onClick={() =>
                                  setLinked((l) => (l === i.refundOf ? null : i.refundOf!))
                                }
                                className="font-medium text-info underline-offset-2 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                              >
                                refund — show original
                              </button>
                            ) : null}
                          </p>
                        </div>
                        <span
                          className={cn(
                            "shrink-0 font-mono text-sm numeric",
                            i.amount > 0 ? "font-semibold text-market-up" : "text-foreground"
                          )}
                        >
                          {i.amount > 0 ? "+" : "−"}
                          {currency}
                          {inr(i.amount)}
                        </span>
                      </div>
                    </li>
                  );
                })}
            </ul>
          </div>
        ))}
      </div>
    </div>
  );
}

registry/default/enterprise/reconciliati:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface ReconPair {
  id: string;
  ledger: { ref: string; desc: string; amount: number };
  statement: { ref: string; desc: string; amount: number };
  /** Match confidence 0–1. */
  confidence: number;
}

export interface ReconciliationProps
  extends React.HTMLAttributes<HTMLDivElement> {
  pairs?: ReconPair[];
  /** Confidence at or above which "Accept all" applies. Default 0.95. */
  bulkThreshold?: number;
  onResolve?: (id: string, action: "accept" | "reject") => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_RECON: ReconPair[] = [
  {
    id: "r1",
    ledger: { ref: "INV-2041", desc: "Acme Corp · services", amount: 118_000 },
    statement: { ref: "NEFT-88123", desc: "ACME CORP PVT LTD", amount: 118_000 },
    confidence: 0.99,
  },
  {
    id: "r2",
    ledger: { ref: "INV-2044", desc: "Globex · retainer", amount: 90_000 },
    statement: { ref: "IMPS-11407", desc: "GLOBEX INDIA", amount: 90_000 },
    confidence: 0.97,
  },
  {
    id: "r3",
    ledger: { ref: "INV-2038", desc: "Initech · milestone 2", amount: 2_40_000 },
    statement: { ref: "RTGS-55019", desc: "INITECH SOLUTIONS", amount: 2_38_820 },
    confidence: 0.74,
  },
  {
    id: "r4",
    ledger: { ref: "INV-2047", desc: "Umbrella · onboarding", amount: 56_500 },
    statement: { ref: "UPI-99231", desc: "UMBRELA SVCS", amount: 56_500 },
    confidence: 0.88,
  },
];

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);

/* ------------------------------------------------------------------ */
/* Workspace                                                            */
/* ------------------------------------------------------------------ */

/**
 * Two-sided reconciliation: suggested ledger↔statement matches with
 * confidence, amount differences called out to the rupee, accept/reject
 * per pair (accepted pairs collapse away), bulk-accept above a threshold
 * and a live matched meter.
 */
export function Reconciliation({
  pairs = DEMO_RECON,
  bulkThreshold = 0.95,
  onResolve,
  className,
  ref,
  ...rest
}: ReconciliationProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [resolved, setResolved] = React.useState<Record<string, "accept" | "reject">>({});
  const open = pairs.filter((p) => !resolved[p.id]);
  const accepted = Object.values(resolved).filter((v) => v === "accept").length;
  const matchedPct = Math.round((accepted / pairs.length) * 100);
  const bulkable = open.filter((p) => p.confidence >= bulkThreshold);

  const resolve = (id: string, action: "accept" | "reject") => {
    const el = rootRef.current?.querySelector<HTMLElement>(`[data-pair="${id}"]`);
    const commit = () => {
      setResolved((r) => ({ ...r, [id]: action }));
      onResolve?.(id, action);
    };
    if (reduced || !el) {
      commit();
      return;
    }
    gsap.to(el, {
      x: action === "accept" ? 32 : -32,
      opacity: 0,
      height: 0,
      marginBottom: 0,
      duration: 0.35,
      ease: "power2.in",
      onComplete: commit,
    });
  };

  const bulkAccept = () => {
    for (const p of bulkable) resolve(p.id, "accept");
  };

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-pair]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 14, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.4, ease: "power3.out", stagger: 0.08 }
      );
    },
    { scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="reconciliation"
      className={cn(
        "w-full max-w-2xl rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      {/* Header + meter */}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="type-title text-foreground">
          Bank reconciliation · July
        </h3>
        <Button
          size="sm"
          variant="outline"
          disabled={bulkable.length === 0}
          onClick={bulkAccept}
        >
          Accept all ≥{Math.round(bulkThreshold * 100)}% ({bulkable.length})
        </Button>
      </div>
      <div
        className="mt-3 h-2 overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border/40"
        role="meter"
        aria-label="Matched share"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={matchedPct}
      >
        <span
          className="block h-full rounded-full transition-all duration-500 ease-out"
          style={{
            width: `${matchedPct}%`,
            background: "linear-gradient(90deg, color-mix(in oklab, var(--success) 55%, transparent), var(--success))",
          }}
        />
      </div>
      <p className="mt-1 type-meta numeric text-muted-foreground">
        {accepted}/{pairs.length} matched · {open.length} awaiting review
      </p>

      {/* Pairs */}
      <div className="mt-3 flex flex-col">
        {open.length === 0 ? (
          <div className="rounded-2xl border border-success/40 bg-success/[0.06] px-3 py-8 text-center shadow-xs">
            <p className="text-sm font-medium text-success">All matched</p>
            <p className="mt-0.5 type-meta text-muted-foreground">
              Decisions are logged to the audit trail with your user and timestamp.
            </p>
          </div>
        ) : null}
        {open.map((p) => {
          const diff = p.statement.amount - p.ledger.amount;
          const high = p.confidence >= bulkThreshold;
          return (
            <div key={p.id} data-pair={p.id} className="mb-2 overflow-hidden">
              <div
                className={cn(
                  "rounded-2xl border p-3.5 shadow-xs transition-colors duration-300",
                  diff !== 0 ? "border-warning/40 bg-warning/[0.03]" : "border-border/60 bg-background/40"
                )}
              >
                <div className="grid items-center gap-2 sm:grid-cols-[1fr_auto_1fr]">
                  {/* Ledger side */}
                  <div className="min-w-0 rounded-xl border border-border/50 bg-muted/40 px-3 py-2.5">
                    <p className="type-overline text-muted-foreground">
                      Ledger · {p.ledger.ref}
                    </p>
                    <p className="truncate text-xs font-medium text-foreground">{p.ledger.desc}</p>
                    <p className="font-mono text-sm numeric text-foreground">₹{inr(p.ledger.amount)}</p>
                  </div>
                  {/* Confidence link with connectors */}
                  <div className="relative flex items-center justify-center py-1">
                    <span aria-hidden="true" className="absolute right-1/2 top-1/2 hidden h-px w-3 -translate-y-1/2 bg-border sm:block" />
                    <span aria-hidden="true" className="absolute left-1/2 top-1/2 hidden h-px w-3 -translate-y-1/2 bg-border sm:block" />
                    <span
                      className={cn(
                        "relative rounded-full px-2 py-0.5 type-caption font-semibold numeric ring-1 ring-inset",
                        high
                          ? "bg-success/12 text-success ring-success/25"
                          : p.confidence >= 0.8
                            ? "bg-warning/12 text-warning ring-warning/25"
                            : "bg-risk-high/12 text-risk-high ring-risk-high/25"
                      )}
                    >
                      {Math.round(p.confidence * 100)}%
                    </span>
                  </div>
                  {/* Statement side */}
                  <div className="min-w-0 rounded-xl border border-border/50 bg-muted/40 px-3 py-2.5 sm:text-right">
                    <p className="type-overline text-muted-foreground">
                      Statement · {p.statement.ref}
                    </p>
                    <p className="truncate text-xs font-medium text-foreground">{p.statement.desc}</p>
                    <p className="font-mono text-sm numeric text-foreground">₹{inr(p.statement.amount)}</p>
                  </div>
                </div>
                <div className="mt-3 flex items-center justify-between gap-2">
                  <p className="type-meta numeric">
                    {diff === 0 ? (
                      <span className="flex items-center gap-1 text-muted-foreground">
                        <span className="size-1.5 rounded-full bg-success" />
                        Amounts agree exactly
                      </span>
                    ) : (
                      <span className="font-medium text-warning">
                        Δ ₹{inr(Math.abs(diff))} {diff < 0 ? "short" : "over"} — likely bank charges; verify before accepting
                      </span>
                    )}
                  </p>
                  <div className="flex gap-1.5">
                    <Button size="sm" variant="outline" onClick={() => resolve(p.id, "reject")}>
                      Reject
                    </Button>
                    <Button
                      size="sm"
                      className="bg-success text-white shadow-sm hover:bg-success/90"
                      onClick={() => resolve(p.id, "accept")}
                    >
                      Accept match
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

