"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { LayoutGroup, motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

const bandSpring = { type: "spring", stiffness: 480, damping: 38 } as const;

/** Custom range slider: designed track, gradient fill and a focus-ringed
 *  thumb over a hidden native input (keeps keyboard + a11y). */
function Slider({
  label,
  value,
  onChange,
  min,
  max,
  step,
  format,
}: {
  label: string;
  value: number;
  onChange: (v: number) => void;
  min: number;
  max: number;
  step: number;
  format: (v: number) => string;
}) {
  const pct = ((value - min) / (max - min)) * 100;
  return (
    <label className="flex flex-col gap-1.5 text-xs">
      <span className="flex justify-between text-muted-foreground">
        {label}
        <span className="font-semibold numeric text-foreground">{format(value)}</span>
      </span>
      <span className="relative flex h-5 items-center">
        <span className="pointer-events-none absolute inset-x-0 top-1/2 h-1.5 -translate-y-1/2 rounded-full bg-muted ring-1 ring-inset ring-border/50" />
        <span
          className="pointer-events-none absolute left-0 top-1/2 h-1.5 -translate-y-1/2 rounded-full"
          style={{
            width: `${pct}%`,
            background: "linear-gradient(90deg, color-mix(in oklab, var(--primary) 45%, transparent), var(--primary))",
          }}
        />
        <input
          type="range"
          min={min}
          max={max}
          step={step}
          value={value}
          aria-label={label}
          onChange={(e) => onChange(parseInt(e.target.value, 10))}
          className="peer absolute inset-0 z-20 w-full cursor-pointer appearance-none bg-transparent opacity-0"
        />
        <span
          className="pointer-events-none absolute top-1/2 z-10 size-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-primary bg-background shadow-md peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-background"
          style={{ left: `${pct}%` }}
        />
      </span>
    </label>
  );
}

/* ------------------------------------------------------------------ */
/* Model + math                                                         */
/* ------------------------------------------------------------------ */

export interface LoanEligibilityProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** Annual interest rate by credit band, %. */
  rates?: { excellent: number; good: number; fair: number };
  /** Processing fee, % of principal. */
  processingFeePct?: number;
  /** FOIR ceiling used for the approval read. Default 0.5. */
  foirLimit?: number;
  ref?: React.Ref<HTMLDivElement>;
}

export type CreditBand = "excellent" | "good" | "fair";

/** Standard amortised EMI. */
export function emi(principal: number, annualRatePct: number, months: number) {
  const r = annualRatePct / 12 / 100;
  if (r === 0) return principal / months;
  const f = Math.pow(1 + r, months);
  return (principal * r * f) / (f - 1);
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);
const lakh = (n: number) =>
  n >= 1e5 ? `₹${(n / 1e5).toFixed(1)}L` : `₹${inr(n)}`;

const BANDS: { key: CreditBand; label: string; range: string }[] = [
  { key: "excellent", label: "750+", range: "Excellent" },
  { key: "good", label: "700–749", range: "Good" },
  { key: "fair", label: "650–699", range: "Fair" },
];

const DOCUMENTS = [
  "PAN + Aadhaar",
  "3 months' salary slips",
  "6 months' bank statement",
  "Employment certificate",
];

/* ------------------------------------------------------------------ */
/* Composer                                                             */
/* ------------------------------------------------------------------ */

/**
 * Loan eligibility composer: amount/tenure/income/obligations sliders
 * drive the EMI, the FOIR meter shows exactly why the answer is what it
 * is, and the approval read moves between likely/borderline/unlikely
 * with the reason spelled out.
 */
export function LoanEligibility({
  rates = { excellent: 10.5, good: 12.25, fair: 14.5 },
  processingFeePct = 1.5,
  foirLimit = 0.5,
  className,
  ref,
  ...rest
}: LoanEligibilityProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [amount, setAmount] = React.useState(800_000);
  const [months, setMonths] = React.useState(48);
  const [income, setIncome] = React.useState(95_000);
  const [obligations, setObligations] = React.useState(12_000);
  const [band, setBand] = React.useState<CreditBand>("good");

  const rate = rates[band];
  const monthly = emi(amount, rate, months);
  const totalInterest = monthly * months - amount;
  const processingFee = (amount * processingFeePct) / 100;
  const foir = (monthly + obligations) / income;

  const verdict =
    foir <= foirLimit * 0.8
      ? { label: "Approval likely", cls: "text-success", hue: "var(--success)" }
      : foir <= foirLimit
        ? { label: "Borderline", cls: "text-warning", hue: "var(--warning)" }
        : { label: "Unlikely at this size", cls: "text-risk-high", hue: "var(--risk-high)" };

  // Max amount that keeps FOIR at the limit, for the suggestion line.
  const headroom = Math.max(0, income * foirLimit - obligations);
  const perRupee = emi(100_000, rate, months) / 100_000;
  const maxEligible = Math.floor(headroom / perRupee / 10_000) * 10_000;

  /* FOIR meter tweens to each new position. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const fill = root.querySelector<HTMLElement>("[data-foir]");
      if (!fill) return;
      const pct = Math.min(100, foir * 100);
      if (reduced) gsap.set(fill, { width: `${pct}%` });
      else gsap.to(fill, { width: `${pct}%`, duration: 0.5, ease: "power3.out", overwrite: true });
    },
    { dependencies: [foir, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="loan-eligibility"
      className={cn(
        "w-full max-w-md rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      {/* Headline EMI */}
      <div className="flex items-baseline justify-between gap-2">
        <div>
          <p className="type-overline text-muted-foreground">
            Monthly EMI
          </p>
          <p className="type-metric text-foreground">
            <NumberFlow value={Math.round(monthly)} prefix="₹" locale="en-IN" trend />
          </p>
        </div>
        <p className={cn("text-sm font-semibold", verdict.cls)} aria-live="polite">
          {verdict.label}
        </p>
      </div>

      {/* FOIR meter */}
      <div className="mt-2">
        <div
          className="relative h-2 overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border/40"
          role="meter"
          aria-label="Fixed-obligation to income ratio"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(foir * 100)}
        >
          <span
            data-foir
            className="block h-full rounded-full"
            style={{
              width: 0,
              background: `linear-gradient(90deg, color-mix(in oklab, ${verdict.hue} 55%, transparent), ${verdict.hue})`,
            }}
          />
          <span
            aria-hidden="true"
            className="absolute inset-y-0 z-10 w-0.5 bg-foreground/60"
            style={{ left: `${foirLimit * 100}%` }}
          />
        </div>
        <p className="mt-1 type-meta numeric text-muted-foreground">
          Obligations {(foir * 100).toFixed(0)}% of income · lenders cap near{" "}
          {(foirLimit * 100).toFixed(0)}%
          {foir > foirLimit && maxEligible > 0 ? (
            <span className="font-medium text-foreground">
              {" "}
              — {lakh(maxEligible)} would fit at this tenure
            </span>
          ) : null}
        </p>
      </div>

      {/* Controls */}
      <div className="mt-5 flex flex-col gap-3.5">
        <Slider label="Loan amount" value={amount} onChange={setAmount} min={100_000} max={3_000_000} step={50_000} format={lakh} />
        <Slider label="Tenure" value={months} onChange={setMonths} min={12} max={84} step={6} format={(v) => `${v} months`} />
        <Slider label="Monthly income" value={income} onChange={setIncome} min={25_000} max={400_000} step={5_000} format={(v) => `₹${inr(v)}`} />
        <Slider label="Existing EMIs" value={obligations} onChange={setObligations} min={0} max={100_000} step={1_000} format={(v) => `₹${inr(v)}`} />
        <div className="flex items-center justify-between gap-2 text-xs">
          <span className="text-muted-foreground">Credit score</span>
          <LayoutGroup id={uid}>
            <div className="isolate flex gap-1 rounded-xl bg-muted p-1" role="tablist" aria-label="Credit band">
              {BANDS.map((b) => (
                <button
                  key={b.key}
                  role="tab"
                  aria-selected={band === b.key}
                  onClick={() => setBand(b.key)}
                  className={cn(
                    "relative rounded-lg px-2.5 py-1 type-meta font-medium numeric transition-colors duration-200",
                    band === b.key ? "text-primary-foreground" : "text-muted-foreground hover:text-foreground",
                    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  )}
                  title={b.range}
                >
                  {band === b.key ? (
                    <motion.span
                      layoutId={`band-${uid}`}
                      transition={reduced ? { duration: 0 } : bandSpring}
                      className="absolute inset-0 -z-10 rounded-lg bg-primary shadow-sm"
                    />
                  ) : null}
                  {b.label}
                </button>
              ))}
            </div>
          </LayoutGroup>
        </div>
      </div>

      {/* Cost breakdown */}
      <dl className="mt-5 flex flex-col gap-1.5 rounded-2xl border border-border/60 bg-background/60 p-3.5 text-xs numeric shadow-xs">
        <div className="flex justify-between">
          <dt className="text-muted-foreground">Interest rate ({BANDS.find((b) => b.key === band)?.range})</dt>
          <dd className="text-foreground">{rate.toFixed(2)}% p.a.</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-muted-foreground">Total interest over {months}m</dt>
          <dd className="text-foreground">₹{inr(Math.round(totalInterest))}</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-muted-foreground">Processing fee ({processingFeePct}%)</dt>
          <dd className="text-foreground">₹{inr(Math.round(processingFee))}</dd>
        </div>
      </dl>

      {/* Documents */}
      <div className="mt-3">
        <p className="type-meta font-medium text-foreground">You&apos;ll need</p>
        <ul className="mt-1 flex flex-wrap gap-1.5">
          {DOCUMENTS.map((d) => (
            <li
              key={d}
              className="rounded-full bg-muted px-2.5 py-1 type-caption text-muted-foreground ring-1 ring-inset ring-border/50"
            >
              {d}
            </li>
          ))}
        </ul>
      </div>
      <p className="mt-2 type-caption text-muted-foreground">
        Indicative only — the lender&apos;s own bureau pull and policy decide.
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { LayoutGroup, motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

const toggleSpring = { type: "spring", stiffness: 480, damping: 38 } as const;

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type ToolCallStatus = "ok" | "error" | "denied";

export interface InspectedToolCall {
  id: string;
  tool: string;
  /** Human summary of what the call did. */
  summary: string;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  durationMs: number;
  status: ToolCallStatus;
  permission: "allowed" | "asked" | "denied";
  retryOf?: string;
}

export interface ToolCallInspectorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  calls?: InspectedToolCall[];
  onRetry?: (id: string) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_TOOL_CALLS: InspectedToolCall[] = [
  {
    id: "c1",
    tool: "search_orders",
    summary: "Found order #8412 for asha@example.com",
    args: { email: "asha@example.com", status: "paid" },
    result: { id: 8412, total: 2499, currency: "INR" },
    durationMs: 312,
    status: "ok",
    permission: "allowed",
  },
  {
    id: "c2",
    tool: "payments.refund",
    summary: "First refund attempt hit a gateway timeout",
    args: { txn: "txn_9f2c", amount: 2499, reason: "customer_request" },
    error: "504 gateway timeout after 8000ms",
    durationMs: 8000,
    status: "error",
    permission: "asked",
  },
  {
    id: "c3",
    tool: "payments.refund",
    summary: "Retry succeeded — refund refund_51ab initiated",
    args: { txn: "txn_9f2c", amount: 2499, reason: "customer_request" },
    result: { refund: "refund_51ab", state: "initiated" },
    durationMs: 1240,
    status: "ok",
    permission: "asked",
    retryOf: "c2",
  },
  {
    id: "c4",
    tool: "db.delete_customer",
    summary: "Blocked: destructive call outside the approved scope",
    args: { id: 8412 },
    durationMs: 4,
    status: "denied",
    permission: "denied",
  },
];

const STATUS_META: Record<ToolCallStatus, { cls: string; label: string; hue: string }> = {
  ok: { cls: "bg-success/12 text-success ring-1 ring-inset ring-success/20", label: "ok", hue: "var(--success)" },
  error: { cls: "bg-destructive/12 text-destructive ring-1 ring-inset ring-destructive/20", label: "error", hue: "var(--destructive)" },
  denied: { cls: "bg-warning/12 text-warning ring-1 ring-inset ring-warning/20", label: "denied", hue: "var(--warning)" },
};

/* ------------------------------------------------------------------ */
/* Inspector                                                            */
/* ------------------------------------------------------------------ */

/**
 * A transcript of what the agent actually did: every tool call with its
 * permission, duration bar, and a human ↔ raw toggle — the raw view is
 * the exact JSON, the human view is what you'd tell a teammate.
 */
export function ToolCallInspector({
  calls = DEMO_TOOL_CALLS,
  onRetry,
  className,
  ref,
  ...rest
}: ToolCallInspectorProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [raw, setRaw] = React.useState(false);
  const [openId, setOpenId] = React.useState<string | null>(null);
  const maxMs = Math.max(...calls.map((c) => c.durationMs), 1);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-call]"));
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-duration]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        for (const bar of bars) gsap.set(bar, { width: `${Number(bar.dataset.duration) * 100}%` });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 10, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.35, ease: "power2.out", stagger: 0.07 }
      );
      for (const bar of bars) {
        gsap.fromTo(
          bar,
          { width: 0 },
          { width: `${Number(bar.dataset.duration) * 100}%`, duration: 0.6, ease: "power3.out", delay: 0.3 }
        );
      }
    },
    { scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="tool-call-inspector"
      className={cn(
        "w-full max-w-xl rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-2">
        <h3 className="type-title text-foreground">
          Tool calls <span className="text-muted-foreground">({calls.length})</span>
        </h3>
        <LayoutGroup id={uid}>
          <div className="isolate flex rounded-xl bg-muted p-1" role="tablist" aria-label="View mode">
            {(["human", "raw"] as const).map((v) => (
              <button
                key={v}
                role="tab"
                aria-selected={(v === "raw") === raw}
                onClick={() => setRaw(v === "raw")}
                className={cn(
                  "relative rounded-lg px-3 py-1 type-meta font-medium capitalize transition-colors duration-200",
                  (v === "raw") === raw ? "text-foreground" : "text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {(v === "raw") === raw ? (
                  <motion.span
                    layoutId={`tci-${uid}`}
                    transition={reduced ? { duration: 0 } : toggleSpring}
                    className="absolute inset-0 -z-10 rounded-lg bg-background shadow-sm"
                  />
                ) : null}
                {v}
              </button>
            ))}
          </div>
        </LayoutGroup>
      </div>

      {/* Calls */}
      <ul className="mt-3 flex flex-col gap-1.5">
        {calls.map((c) => {
          const meta = STATUS_META[c.status];
          const open = openId === c.id;
          return (
            <li key={c.id} data-call>
              <div
                className={cn(
                  "relative overflow-hidden rounded-2xl border shadow-xs transition-colors duration-200",
                  c.status === "error"
                    ? "border-destructive/40 bg-destructive/[0.04]"
                    : c.status === "denied"
                      ? "border-warning/40 bg-warning/[0.03]"
                      : "border-border/60 bg-background/60"
                )}
              >
                <span
                  aria-hidden="true"
                  className="absolute inset-y-2.5 left-0 w-0.5 rounded-full opacity-70"
                  style={{ background: meta.hue }}
                />
                <button
                  type="button"
                  aria-expanded={open}
                  onClick={() => setOpenId((o) => (o === c.id ? null : c.id))}
                  className="w-full py-2.5 pl-3.5 pr-3 text-left transition-colors duration-200 hover:bg-muted/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                >
                  <div className="flex items-center gap-2">
                    <code className="truncate font-mono text-xs font-semibold text-foreground">
                      {c.tool}
                    </code>
                    <span className={cn("rounded-md px-1.5 py-0.5 text-[9px] font-semibold uppercase", meta.cls)}>
                      {meta.label}
                    </span>
                    {c.permission === "asked" ? (
                      <span className="rounded-md bg-info/12 px-1.5 py-0.5 text-[9px] font-semibold uppercase text-info ring-1 ring-inset ring-info/20">
                        user approved
                      </span>
                    ) : null}
                    {c.retryOf ? (
                      <span className="rounded-md bg-muted px-1.5 py-0.5 text-[9px] font-semibold uppercase text-muted-foreground ring-1 ring-inset ring-border/60">
                        retry
                      </span>
                    ) : null}
                    <span className="ml-auto shrink-0 font-mono type-caption numeric text-muted-foreground">
                      {c.durationMs >= 1000 ? `${(c.durationMs / 1000).toFixed(1)}s` : `${c.durationMs}ms`}
                    </span>
                  </div>
                  {/* duration bar */}
                  <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border/40" aria-hidden="true">
                    <span
                      data-duration={c.durationMs / maxMs}
                      className="block h-full rounded-full"
                      style={{
                        width: 0,
                        background: `linear-gradient(90deg, color-mix(in oklab, ${meta.hue} 45%, transparent), ${meta.hue})`,
                      }}
                    />
                  </div>
                  <p className="mt-1.5 type-meta leading-4 text-muted-foreground">
                    {raw ? (
                      <code className="font-mono">{JSON.stringify(c.args)}</code>
                    ) : (
                      c.summary
                    )}
                  </p>
                </button>

                {open ? <CallDetail call={c} raw={raw} reduced={reduced} onRetry={onRetry} /> : null}
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function CallDetail({
  call,
  raw,
  reduced,
  onRetry,
}: {
  call: InspectedToolCall;
  raw: boolean;
  reduced: boolean;
  onRetry?: (id: string) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { height: "auto", opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { height: 0, opacity: 0 },
        { height: "auto", opacity: 1, duration: 0.3, ease: "power3.out", clearProps: "height" }
      );
    },
    { scope: ref }
  );

  return (
    <div ref={ref} className="overflow-hidden">
      <div className="border-t border-border/60 py-2 pl-3.5 pr-3">
        {raw ? (
          <pre className="overflow-x-auto rounded-lg bg-muted/60 p-2 font-mono type-caption leading-4 text-foreground">
            {JSON.stringify(
              { tool: call.tool, args: call.args, ...(call.result ? { result: call.result } : {}), ...(call.error ? { error: call.error } : {}) },
              null,
              2
            )}
          </pre>
        ) : (
          <div className="flex flex-col gap-1 type-meta leading-4">
            {call.result != null ? (
              <p className="text-foreground">
                <span className="font-medium">Result:</span>{" "}
                {typeof call.result === "object" ? JSON.stringify(call.result) : String(call.result)}
              </p>
            ) : null}
            {call.error ? (
              <p className="text-destructive">
                <span className="font-medium">Error:</span> {call.error}
              </p>
            ) : null}
            {call.status === "denied" ? (
              <p className="text-warning">
                Denied by policy before execution — no side effects occurred.
              </p>
            ) : null}
          </div>
        )}
        {call.status === "error" ? (
          <div className="mt-2">
            <Button size="sm" variant="outline" onClick={() => onRetry?.(call.id)}>
              Retry call
            </Button>
          </div>
        ) : null}
      </div>
    </div>
  );
}

registry/default/ai/approval-gate.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type ApprovalState =
  | "pending"
  | "approved"
  | "modified"
  | "rejected"
  | "expired";

export interface ApprovalGateProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** What the agent wants to do, imperative. */
  action: string;
  /** The risky payload the human is approving — editable via Modify. */
  payload: string;
  details?: [string, string][];
  /** Seconds until the request expires. Default 60. */
  expiresInSec?: number;
  onDecision?: (state: ApprovalState, payload: string) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const STATE_META: Record<
  ApprovalState,
  { label: string; cls: string; border: string }
> = {
  pending: { label: "Awaiting approval", cls: "text-agent-waiting", border: "border-agent-waiting/50" },
  approved: { label: "Approved", cls: "text-success", border: "border-success/50" },
  modified: { label: "Approved with edits", cls: "text-success", border: "border-success/50" },
  rejected: { label: "Rejected", cls: "text-muted-foreground", border: "border-border" },
  expired: { label: "Expired — agent paused", cls: "text-destructive", border: "border-destructive/50" },
};

/* ------------------------------------------------------------------ */
/* Gate                                                                 */
/* ------------------------------------------------------------------ */

/**
 * The human approval gate: an agent's outward-facing action paused for a
 * person. The expiry bar drains in real time; Approve, Reject, or Modify
 * the payload and approve the edited version — every terminal state is
 * designed, including "nobody answered".
 */
export function ApprovalGate({
  action,
  payload,
  details = [],
  expiresInSec = 60,
  onDecision,
  className,
  ref,
  ...rest
}: ApprovalGateProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const barRef = React.useRef<HTMLSpanElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [state, setState] = React.useState<ApprovalState>("pending");
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(payload);
  const [remaining, setRemaining] = React.useState(expiresInSec);

  const decide = (next: ApprovalState) => {
    setState(next);
    setEditing(false);
    onDecision?.(next, draft);
  };

  /* Countdown: the bar drains linearly; hitting zero expires the gate. */
  React.useEffect(() => {
    if (state !== "pending") return;
    const id = setInterval(() => {
      setRemaining((r) => {
        if (r <= 1) {
          clearInterval(id);
          setState("expired");
          onDecision?.("expired", draft);
          return 0;
        }
        return r - 1;
      });
    }, 1000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state]);

  useGSAP(
    () => {
      if (!barRef.current) return;
      const pct = (remaining / expiresInSec) * 100;
      if (reduced) gsap.set(barRef.current, { width: `${pct}%` });
      else gsap.to(barRef.current, { width: `${pct}%`, duration: 1, ease: "none", overwrite: true });
    },
    { dependencies: [remaining, expiresInSec, reduced] }
  );

  const meta = STATE_META[state];
  const settled = state !== "pending";

  return (
    <div
      ref={rootRef}
      data-slot="approval-gate"
      className={cn(
        "w-full max-w-md rounded-3xl border bg-card p-5 shadow-md transition-colors duration-300",
        meta.border,
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="type-overline text-muted-foreground">
            Agent requests approval
          </p>
          <p className="text-sm font-semibold leading-5 text-foreground">{action}</p>
        </div>
        <span className={cn("flex shrink-0 items-center gap-1.5 text-xs font-semibold", meta.cls)} aria-live="polite">
          {state === "pending" ? (
            <span className="relative flex size-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-agent-waiting opacity-60" />
              <span className="relative inline-flex size-2 rounded-full bg-agent-waiting" />
            </span>
          ) : null}
          {meta.label}
        </span>
      </div>

      {/* Payload */}
      <div className="mt-3">
        {editing ? (
          <textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            rows={4}
            aria-label="Edit the payload before approving"
            className="w-full rounded-lg border border-input bg-background p-2.5 type-meta leading-5 text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          />
        ) : (
          <blockquote
            className={cn(
              "rounded-xl border border-l-2 bg-muted/40 px-3.5 py-2.5 type-meta leading-5 shadow-xs",
              draft !== payload ? "border-l-info border-border/60 text-foreground" : "border-l-border border-border/60 text-foreground",
              state === "rejected" && "opacity-50"
            )}
          >
            {draft}
            {draft !== payload ? (
              <span className="mt-1 block type-caption font-medium text-info">
                edited by reviewer
              </span>
            ) : null}
          </blockquote>
        )}
      </div>

      {/* Details */}
      {details.length > 0 ? (
        <dl className="mt-2 flex flex-col gap-0.5 type-meta numeric">
          {details.map(([k, v]) => (
            <div key={k} className="flex justify-between gap-2">
              <dt className="text-muted-foreground">{k}</dt>
              <dd className="text-right text-foreground">{v}</dd>
            </div>
          ))}
        </dl>
      ) : null}

      {/* Expiry / outcome */}
      {state === "pending" ? (
        <>
          <div className="mt-4 h-1.5 overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border/40" aria-hidden="true">
            <span
              ref={barRef}
              className="block h-full rounded-full"
              style={{
                width: "100%",
                background: remaining / expiresInSec > 0.33
                  ? "linear-gradient(90deg, color-mix(in oklab, var(--agent-waiting) 55%, transparent), var(--agent-waiting))"
                  : "linear-gradient(90deg, color-mix(in oklab, var(--destructive) 55%, transparent), var(--destructive))",
              }}
            />
          </div>
          <p className="mt-1 type-caption numeric text-muted-foreground">
            Expires in {remaining}s — the agent stays paused, nothing is sent
            without a decision.
          </p>
          <div className="mt-3 flex gap-2">
            {editing ? (
              <>
                <Button size="sm" variant="outline" onClick={() => { setDraft(payload); setEditing(false); }}>
                  Discard edits
                </Button>
                <Button size="sm" className="flex-1" onClick={() => decide("modified")}>
                  Approve edited version
                </Button>
              </>
            ) : (
              <>
                <Button size="sm" variant="outline" onClick={() => decide("rejected")}>
                  Reject
                </Button>
                <Button size="sm" variant="outline" onClick={() => setEditing(true)}>
                  Modify
                </Button>
                <Button size="sm" className="flex-1 bg-success text-white shadow-sm hover:bg-success/90" onClick={() => decide("approved")}>
                  Approve
                </Button>
              </>
            )}
          </div>
        </>
      ) : (
        <p className="mt-3 rounded-lg bg-muted/50 px-2.5 py-1.5 type-meta leading-4 text-muted-foreground">
          {state === "approved" && "The agent is executing the approved action."}
          {state === "modified" && "The agent is executing your edited version — the original was not sent."}
          {state === "rejected" && "Nothing was sent. The agent will report the rejection and stop this branch."}
          {state === "expired" && "No decision arrived in time. The action was not taken; the agent is waiting for a human to resume."}
        </p>
      )}
    </div>
  );
}

registry/default/ai/grounded-answer.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface AnswerSource {
  id: string;
  title: string;
  quote: string;
  meta: string;
}

export interface AnswerClaim {
  text: string;
  sourceIds: string[];
  /** Grounding confidence 0–1; low values render with a caution tint. */
  confidence: number;
  /** Set when sources disagree — surfaced, never averaged away. */
  contradiction?: string;
}

export interface GroundedAnswerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  question: string;
  claims?: AnswerClaim[];
  sources?: AnswerSource[];
  missingEvidence?: string[];
  onFeedback?: (helpful: boolean) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_ANSWER: Pick<
  GroundedAnswerProps,
  "question" | "claims" | "sources" | "missingEvidence"
> = {
  question: "What is our refund SLA for UPI payments?",
  claims: [
    {
      text: "Refunds for UPI payments must be initiated within 24 hours of the customer request.",
      sourceIds: ["s1"],
      confidence: 0.95,
    },
    {
      text: "Once initiated, the credit reaches the customer in 5–7 working days.",
      sourceIds: ["s1", "s2"],
      confidence: 0.88,
      contradiction:
        "The 2023 help-centre page still says 3–5 days; the 2025 policy supersedes it.",
    },
    {
      text: "For failed (not refunded) UPI transactions, auto-reversal is required within T+1 day.",
      sourceIds: ["s3"],
      confidence: 0.72,
    },
  ],
  sources: [
    { id: "s1", title: "Refund policy v4 (2025)", quote: "UPI refunds: initiate ≤ 24h from request; settlement 5–7 working days.", meta: "policies/refunds.md · updated 12 Mar 2025" },
    { id: "s2", title: "Help centre — refunds", quote: "You'll usually see the money back in 3–5 business days.", meta: "help.acme.in/refunds · 2023, stale" },
    { id: "s3", title: "NPCI circular 129", quote: "Failed transactions shall be auto-reversed within T+1.", meta: "external · applies to failures, not refunds" },
  ],
  missingEvidence: ["No source covers refunds for international UPI (UPI One World)."],
};

/* ------------------------------------------------------------------ */
/* Answer                                                               */
/* ------------------------------------------------------------------ */

/**
 * An answer that shows its work: every claim carries citation chips that
 * light up the exact source and quote, contradictions are called out
 * inline instead of averaged away, and what the sources don't cover is
 * stated plainly.
 */
export function GroundedAnswer({
  question,
  claims = DEMO_ANSWER.claims!,
  sources = DEMO_ANSWER.sources!,
  missingEvidence = DEMO_ANSWER.missingEvidence!,
  onFeedback,
  className,
  ref,
  ...rest
}: GroundedAnswerProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [activeSource, setActiveSource] = React.useState<string | null>(null);
  const [feedback, setFeedback] = React.useState<null | boolean>(null);
  const srcIndex = Object.fromEntries(sources.map((s, i) => [s.id, i + 1]));

  /* Claims blur in sequentially, like a considered answer. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-claim]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 10, opacity: 0, filter: "blur(5px)" },
        { y: 0, opacity: 1, filter: "blur(0px)", duration: 0.4, ease: "power3.out", stagger: 0.12, clearProps: "filter" }
      );
    },
    { scope: rootRef }
  );

  /* Selecting a citation pulses the matching source card. */
  const focusSource = (id: string) => {
    setActiveSource((s) => (s === id ? null : id));
    if (reduced || !rootRef.current) return;
    const card = rootRef.current.querySelector<HTMLElement>(`[data-source="${id}"]`);
    if (card)
      gsap.fromTo(card, { scale: 1 }, { scale: 1.02, duration: 0.15, yoyo: true, repeat: 1, ease: "power2.out" });
  };

  return (
    <div
      ref={rootRef}
      data-slot="grounded-answer"
      className={cn(
        "w-full max-w-xl rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      <p className="type-overline text-muted-foreground">
        Question
      </p>
      <p className="text-sm font-medium text-foreground">{question}</p>

      {/* Claims */}
      <div className="mt-3 flex flex-col gap-2">
        {claims.map((c, i) => (
          <div
            key={i}
            data-claim
            className={cn(
              "rounded-lg px-3 py-2 type-label leading-6",
              c.confidence < 0.8 ? "bg-warning/5" : "bg-muted/40"
            )}
          >
            <span className="text-foreground">{c.text}</span>{" "}
            {c.sourceIds.map((sid) => (
              <button
                key={sid}
                type="button"
                aria-pressed={activeSource === sid}
                aria-label={`Show source ${srcIndex[sid]}`}
                onClick={() => focusSource(sid)}
                className={cn(
                  "mx-0.5 inline-flex size-4 items-center justify-center rounded align-text-top text-[9px] font-semibold transition-colors duration-200",
                  activeSource === sid
                    ? "bg-primary text-primary-foreground"
                    : "bg-info/15 text-info hover:bg-info/25",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {srcIndex[sid]}
              </button>
            ))}
            <span
              className={cn(
                "ml-1 align-middle type-caption numeric",
                c.confidence < 0.8 ? "font-medium text-warning" : "text-muted-foreground"
              )}
            >
              {(c.confidence * 100).toFixed(0)}%
            </span>
            {c.contradiction ? (
              <p className="mt-1 border-l-2 border-warning pl-2 type-meta leading-4 text-warning">
                Sources disagree: {c.contradiction}
              </p>
            ) : null}
          </div>
        ))}
      </div>

      {/* Missing evidence */}
      {missingEvidence.length > 0 ? (
        <p className="mt-2 rounded-lg border border-dashed border-border px-3 py-1.5 type-meta leading-4 text-muted-foreground">
          <span className="font-medium text-foreground">Not covered by any source:</span>{" "}
          {missingEvidence.join(" ")}
        </p>
      ) : null}

      {/* Sources */}
      <p className="mt-3 type-overline text-muted-foreground">
        Sources
      </p>
      <ol className="mt-1.5 flex flex-col gap-1.5">
        {sources.map((s) => (
          <li
            key={s.id}
            data-source={s.id}
            className={cn(
              "rounded-xl border px-3 py-2.5 shadow-xs transition-colors duration-300",
              activeSource === s.id ? "border-primary/50 bg-primary/[0.05]" : "border-border/60 bg-background/60"
            )}
          >
            <p className="flex items-baseline gap-1.5 text-xs font-medium text-foreground">
              <span className="flex size-4 shrink-0 items-center justify-center rounded bg-info/15 text-[9px] font-semibold text-info ring-1 ring-inset ring-info/20">
                {srcIndex[s.id]}
              </span>
              {s.title}
            </p>
            <p className="mt-0.5 type-meta italic leading-4 text-muted-foreground">
              “{s.quote}”
            </p>
            <p className="mt-0.5 type-caption text-muted-foreground">{s.meta}</p>
          </li>
        ))}
      </ol>

      {/* Feedback */}
      <div className="mt-3 flex items-center justify-between border-t border-border pt-2">
        <span className="type-caption text-muted-foreground">
          Confidence is per claim, not per answer — low-confidence claims are tinted.
        </span>
        <div className="flex gap-1" aria-live="polite">
          {feedback === null ? (
            (["yes", "no"] as const).map((v) => (
              <button
                key={v}
                type="button"
                aria-label={v === "yes" ? "Helpful" : "Not helpful"}
                onClick={() => {
                  setFeedback(v === "yes");
                  onFeedback?.(v === "yes");
                }}
                className="rounded-md border border-border px-2 py-1 type-meta text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                {v === "yes" ? "Helpful" : "Not helpful"}
              </button>
            ))
          ) : (
            <span className="type-meta text-success">Thanks — recorded.</span>
          )}
        </div>
      </div>
    </div>
  );
}

registry/default/fintech/card-payment.ts:
"use client";

import * as React from "react";
import { motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model + brand detection                                              */
/* ------------------------------------------------------------------ */

export type CardBrand = "visa" | "mastercard" | "amex" | "rupay" | "unknown";

export interface CardPaymentProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  /** Amount to charge, minor-unit agnostic; formatted with the currency. */
  amount: number;
  currency?: string;
  locale?: string;
  /** Called with the (demo) card details on a successful charge. */
  onPaid?: (detail: { brand: CardBrand; last4: string; amount: number }) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const BRAND_META: Record<
  CardBrand,
  { label: string; cvvLen: number; gaps: number[]; max: number; gradient: string }
> = {
  visa: { label: "VISA", cvvLen: 3, gaps: [4, 8, 12], max: 16, gradient: "linear-gradient(135deg, hsl(222 89% 40%), hsl(244 76% 58%))" },
  mastercard: { label: "Mastercard", cvvLen: 3, gaps: [4, 8, 12], max: 16, gradient: "linear-gradient(135deg, hsl(20 90% 45%), hsl(0 72% 45%))" },
  amex: { label: "AMEX", cvvLen: 4, gaps: [4, 10], max: 15, gradient: "linear-gradient(135deg, hsl(190 80% 38%), hsl(172 66% 40%))" },
  rupay: { label: "RuPay", cvvLen: 3, gaps: [4, 8, 12], max: 16, gradient: "linear-gradient(135deg, hsl(158 64% 34%), hsl(200 80% 42%))" },
  unknown: { label: "", cvvLen: 3, gaps: [4, 8, 12], max: 16, gradient: "linear-gradient(135deg, hsl(240 6% 22%), hsl(240 8% 34%))" },
};

function detectBrand(digits: string): CardBrand {
  if (/^3[47]/.test(digits)) return "amex";
  if (/^4/.test(digits)) return "visa";
  if (/^(5[1-5]|2[2-7])/.test(digits)) return "mastercard";
  if (/^(60|65|81|82|508)/.test(digits)) return "rupay";
  return "unknown";
}

function luhn(digits: string): boolean {
  let sum = 0;
  let alt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = parseInt(digits[i], 10);
    if (alt) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    alt = !alt;
  }
  return sum % 10 === 0 && digits.length >= 15;
}

function group(digits: string, gaps: number[]): string {
  let out = "";
  for (let i = 0; i < digits.length; i++) {
    if (gaps.includes(i) && i !== 0) out += " ";
    out += digits[i];
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Brand marks                                                          */
/* ------------------------------------------------------------------ */

function BrandMark({ brand }: { brand: CardBrand }) {
  if (brand === "visa" || brand === "amex" || brand === "rupay") {
    return (
      <span className="text-sm font-bold italic tracking-tight text-white">
        {BRAND_META[brand].label}
      </span>
    );
  }
  if (brand === "mastercard") {
    return (
      <span className="flex items-center" aria-label="Mastercard">
        <span className="size-6 rounded-full bg-[hsl(0_72%_55%)]" />
        <span className="-ml-2.5 size-6 rounded-full bg-[hsl(38_92%_55%)] mix-blend-hard-light" />
      </span>
    );
  }
  return <span className="text-xs font-medium text-white/50">CARD</span>;
}

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

type Stage = "idle" | "processing" | "success";

/**
 * Add-card and pay: a live 3D card face detects the brand as you type,
 * flips to reveal the CVV strip when you focus the security field, and the
 * pay button runs a processing → paid morph. Luhn and expiry are validated
 * before the charge is allowed.
 */
export function CardPayment({
  amount,
  currency = "₹",
  locale = "en-IN",
  onPaid,
  className,
  ref,
  ...rest
}: CardPaymentProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [number, setNumber] = React.useState("");
  const [name, setName] = React.useState("");
  const [expiry, setExpiry] = React.useState("");
  const [cvv, setCvv] = React.useState("");
  const [flipped, setFlipped] = React.useState(false);
  const [stage, setStage] = React.useState<Stage>("idle");

  const brand = detectBrand(number);
  const meta = BRAND_META[brand];

  const setDigits = (raw: string) =>
    setNumber(raw.replace(/\D/g, "").slice(0, meta.max));

  const setExp = (raw: string) => {
    const d = raw.replace(/\D/g, "").slice(0, 4);
    setExpiry(d.length >= 3 ? `${d.slice(0, 2)}/${d.slice(2)}` : d);
  };

  const [mm, yy] = expiry.split("/");
  const expiryValid =
    mm != null &&
    yy != null &&
    yy.length === 2 &&
    +mm >= 1 &&
    +mm <= 12 &&
    // not in the past (assume 20YY)
    new Date(2000 + +yy, +mm) > new Date();

  const numberValid = luhn(number);
  const cvvValid = cvv.length === meta.cvvLen;
  const canPay =
    numberValid && expiryValid && cvvValid && name.trim().length > 1 && stage === "idle";

  const format = (n: number) =>
    new Intl.NumberFormat(locale, { minimumFractionDigits: 2 }).format(n);

  const pay = async () => {
    if (!canPay) return;
    setStage("processing");
    await new Promise((r) => setTimeout(r, reduced ? 400 : 1600));
    setStage("success");
    onPaid?.({ brand, last4: number.slice(-4), amount });
  };

  // Card display strings
  const displayNumber = React.useMemo(() => {
    const filled = number.padEnd(meta.max, "•");
    return group(filled, meta.gaps);
  }, [number, meta.max, meta.gaps]);

  const field =
    "h-10 w-full rounded-xl border border-input bg-background px-3 text-sm text-foreground shadow-xs transition-[border-color,box-shadow] duration-200 placeholder:text-muted-foreground/60 hover:border-ring/30 focus-visible:outline-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/25";

  return (
    <div
      ref={rootRef}
      data-slot="card-payment"
      className={cn(
        "w-full max-w-sm rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      {/* Live card face */}
      <div className="[perspective:1200px]">
        <motion.div
          className="relative aspect-[1.586/1] w-full [transform-style:preserve-3d]"
          animate={{ rotateY: flipped ? 180 : 0 }}
          transition={reduced ? { duration: 0 } : { type: "spring", stiffness: 260, damping: 26 }}
        >
          {/* Front */}
          <div
            className="absolute inset-0 flex flex-col justify-between overflow-hidden rounded-2xl p-4 text-white shadow-lg [backface-visibility:hidden]"
            style={{ background: meta.gradient }}
          >
            <div
              aria-hidden="true"
              className="pointer-events-none absolute -right-8 -top-10 size-40 rounded-full bg-white/10 blur-2xl"
            />
            <div className="relative flex items-start justify-between">
              {/* chip */}
              <div className="grid h-7 w-9 grid-cols-3 grid-rows-3 gap-px overflow-hidden rounded-md bg-gradient-to-br from-yellow-200 to-yellow-400 p-1">
                {Array.from({ length: 9 }).map((_, i) => (
                  <span key={i} className="rounded-[1px] bg-yellow-500/40" />
                ))}
              </div>
              <BrandMark brand={brand} />
            </div>
            <div className="relative font-mono text-lg tracking-[0.12em] numeric text-white/95 [text-shadow:0_1px_2px_rgb(0_0_0/0.25)]">
              {displayNumber}
            </div>
            <div className="type-overline relative flex items-end justify-between ">
              <span className="max-w-[65%] truncate">
                <span className="block text-[8px] text-white/50">Card holder</span>
                {name || "YOUR NAME"}
              </span>
              <span className="text-right">
                <span className="block text-[8px] text-white/50">Expires</span>
                {expiry || "MM/YY"}
              </span>
            </div>
          </div>

          {/* Back */}
          <div
            className="absolute inset-0 flex flex-col overflow-hidden rounded-2xl text-white shadow-lg [backface-visibility:hidden] [transform:rotateY(180deg)]"
            style={{ background: meta.gradient }}
          >
            <div className="mt-4 h-9 w-full bg-black/70" />
            <div className="mt-4 px-4">
              <div className="flex h-8 items-center justify-end rounded bg-white px-2 font-mono text-sm numeric text-zinc-900">
                {cvv.padEnd(meta.cvvLen, "•")}
              </div>
              <p className="mt-1 text-right text-[9px] text-white/60">CVV</p>
            </div>
            <div className="mt-auto flex items-center justify-between p-4 text-[9px] text-white/50">
              <span>Security code on the back of your card</span>
              <BrandMark brand={brand} />
            </div>
          </div>
        </motion.div>
      </div>

      {stage === "success" ? (
        <PaidState amount={amount} currency={currency} format={format} last4={number.slice(-4)} reduced={reduced} />
      ) : (
        <form
          className="mt-5 flex flex-col gap-3"
          onSubmit={(e) => {
            e.preventDefault();
            void pay();
          }}
        >
          <label className="flex flex-col gap-1.5 type-meta font-medium text-muted-foreground">
            Card number
            <div className="relative">
              <input
                inputMode="numeric"
                autoComplete="cc-number"
                aria-label="Card number"
                placeholder="1234 5678 9012 3456"
                value={group(number, meta.gaps)}
                onChange={(e) => setDigits(e.target.value)}
                className={cn(field, "font-mono numeric", number && !numberValid && "border-destructive/60")}
              />
              {number && numberValid ? (
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" className="absolute right-3 top-1/2 size-4 -translate-y-1/2 text-success" aria-hidden="true"><path d="M5 13l4 4L19 7" /></svg>
              ) : null}
            </div>
          </label>

          <label className="flex flex-col gap-1.5 type-meta font-medium text-muted-foreground">
            Cardholder name
            <input
              autoComplete="cc-name"
              aria-label="Cardholder name"
              placeholder="Asha Verma"
              value={name}
              onChange={(e) => setName(e.target.value.replace(/[^a-zA-Z\s.]/g, "").toUpperCase())}
              className={field}
            />
          </label>

          <div className="flex gap-3">
            <label className="flex flex-1 flex-col gap-1.5 type-meta font-medium text-muted-foreground">
              Expiry
              <input
                inputMode="numeric"
                autoComplete="cc-exp"
                aria-label="Expiry date"
                placeholder="MM/YY"
                value={expiry}
                onChange={(e) => setExp(e.target.value)}
                className={cn(field, "font-mono numeric", expiry.length === 5 && !expiryValid && "border-destructive/60")}
              />
            </label>
            <label className="flex flex-1 flex-col gap-1.5 type-meta font-medium text-muted-foreground">
              CVV
              <input
                inputMode="numeric"
                autoComplete="cc-csc"
                aria-label="Security code"
                placeholder={"•".repeat(meta.cvvLen)}
                value={cvv}
                onFocus={() => setFlipped(true)}
                onBlur={() => setFlipped(false)}
                onChange={(e) => setCvv(e.target.value.replace(/\D/g, "").slice(0, meta.cvvLen))}
                className={cn(field, "font-mono numeric")}
              />
            </label>
          </div>

          <button
            type="submit"
            disabled={!canPay && stage === "idle"}
            aria-disabled={!canPay}
            className={cn(
              "mt-1 flex h-11 items-center justify-center gap-2 rounded-xl bg-primary text-sm font-semibold text-primary-foreground",
              "shadow-[inset_0_1px_0_0_hsl(0_0%_100%/0.12),var(--elevation-sm)]",
              "transition-[transform,box-shadow,opacity] duration-200 ease-out-expo",
              "hover:-translate-y-px active:translate-y-0 active:scale-[0.99]",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ring-offset-background",
              "disabled:pointer-events-none disabled:opacity-50 motion-reduce:hover:translate-y-0"
            )}
          >
            {stage === "processing" ? (
              <>
                <svg viewBox="0 0 24 24" fill="none" className="size-4 animate-spin [animation-duration:0.8s]" aria-hidden="true">
                  <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeDasharray="60 200" />
                </svg>
                Processing…
              </>
            ) : (
              <>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="size-4" aria-hidden="true">
                  <rect x="2" y="5" width="20" height="14" rx="2" /><path d="M2 10h20" />
                </svg>
                Pay {currency}{format(amount)}
              </>
            )}
          </button>
          <p className="flex items-center justify-center gap-1.5 type-caption text-muted-foreground">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true"><rect x="3" y="11" width="18" height="11" rx="2" /><path d="M7 11V7a5 5 0 0 1 10 0v4" /></svg>
            Encrypted. Demo only — do not enter a real card.
          </p>
        </form>
      )}
    </div>
  );
}

function PaidState({
  amount,
  currency,
  format,
  last4,
  reduced,
}: {
  amount: number;
  currency: string;
  format: (n: number) => string;
  last4: string;
  reduced: boolean;
}) {
  return (
    <motion.div
      className="mt-5 flex flex-col items-center gap-2 py-4 text-center"
      initial={reduced ? false : { opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ type: "spring", stiffness: 380, damping: 30 }}
    >
      <span className="flex size-12 items-center justify-center rounded-full bg-success/12 text-success ring-1 ring-inset ring-success/25">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" className="size-6" aria-hidden="true">
          <path
            d="M5 13l4 4L19 7"
            pathLength={1}
            strokeDasharray={1}
            strokeDashoffset={reduced ? 0 : 1}
            style={reduced ? undefined : { animation: "duku-draw 0.5s 0.1s ease-out forwards" }}
          />
        </svg>
      </span>
      <p className="type-title text-foreground">
        Paid {currency}
        {format(amount)}
      </p>
      <p className="type-meta text-muted-foreground">
        Charged to card ending {last4}. A receipt is on its way.
      </p>
      <style>{`@keyframes duku-draw { to { stroke-dashoffset: 0 } }`}</style>
    </motion.div>
  );
}

registry/default/fintech/chart-trading.t:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { useControllableState } from "@/registry/default/lib/use-controllable-state";
import { Button } from "@/registry/default/ui/button";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface Candle {
  /** Axis label for the bucket, e.g. "10:15". */
  label: string;
  o: number;
  h: number;
  l: number;
  c: number;
  /** Quantity traded in the bucket. */
  v: number;
}

export interface BookLevel {
  price: number;
  qty: number;
}

export interface ChartOrder {
  side: "buy" | "sell";
  type: "limit" | "market";
  qty: number;
  /** The order line for a limit, the touching quote for a market order. */
  price: number;
}

export type CheckStatus = "ok" | "warn" | "risk";

export interface PreTradeCheck {
  key: string;
  label: string;
  value: string;
  status: CheckStatus;
  /** Shown only when the check is not clean, so the panel stays quiet. */
  note: string;
  /** 0–100; renders an inline meter under the row. */
  meter?: number;
}

export interface ChartTradingProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  symbol: string;
  exchange?: string;
  /** Candles for the active timeframe, oldest first. */
  candles: Candle[];
  lastPrice: number;
  /** Best-first (descending price) bid levels. */
  bids: BookLevel[];
  /** Best-first (ascending price) ask levels. */
  asks: BookLevel[];
  prevClose: number;
  /** Session volume-weighted average price; drawn as a dashed line. */
  vwap?: number;
  /** Session traded quantity. Defaults to the sum of the candles on screen. */
  volume?: number;
  /** Defaults to the candle extremes. */
  dayHigh?: number;
  dayLow?: number;
  upperCircuit?: number;
  lowerCircuit?: number;
  timeframes?: string[];
  timeframe?: string;
  defaultTimeframe?: string;
  onTimeframeChange?: (timeframe: string) => void;
  lotSize?: number;
  maxLots?: number;
  tick?: number;
  onLimitPriceChange?: (price: number) => void;
  onPlace?: (order: ChartOrder) => void;
  ref?: React.Ref<HTMLDivElement>;
}

/* ------------------------------------------------------------------ */
/* Geometry + formatting                                                */
/* ------------------------------------------------------------------ */

const VIEW_W = 320;
/** Right-hand gutter reserved for the price axis, LTP and order pills. */
const AXIS_W = 48;
const PLOT_W = VIEW_W - AXIS_W;
const AXIS_PCT = (AXIS_W / VIEW_W) * 100;
const PRICE_H = 148;
const VOL_TOP = 158;
const VOL_H = 32;
const VIEW_H = 190;
const PAD = 9;

const nf2 = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
const nf0 = new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 });

/** Indian short scale, because 1,24,50,000 in a legend is unreadable. */
function volFmt(n: number) {
  if (n >= 1e7) return `${(n / 1e7).toFixed(2)}Cr`;
  if (n >= 1e5) return `${(n / 1e5).toFixed(2)}L`;
  if (n >= 1e3) return `${(n / 1e3).toFixed(1)}K`;
  return nf0.format(n);
}

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

/** Deterministic LCG, so demo data is identical on server and client. */
function rng(seed: number) {
  let s = (seed || 1) >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export function generateCandles({
  base = 1543.4,
  count = 46,
  seed = 11,
  vol = 0.0035,
  drift = 0.0003,
  stepMinutes = 5,
  labelFor,
}: {
  base?: number;
  count?: number;
  seed?: number;
  vol?: number;
  drift?: number;
  stepMinutes?: number;
  /** Override the clock labels, e.g. dates for a daily series. */
  labelFor?: (index: number, count: number) => string;
} = {}): Candle[] {
  const rand = rng(seed);
  const out: Candle[] = [];
  let price = base * (1 - drift * count);
  for (let i = 0; i < count; i++) {
    const o = price;
    const move = (rand() - 0.48) * 2 * vol * o + drift * o;
    const c = o + move;
    const wick = (rand() * 0.6 + 0.2) * vol * o;
    const h = Math.max(o, c) + wick;
    const l = Math.min(o, c) - wick * (rand() * 0.8 + 0.3);
    // Volume follows the move: big candles trade big.
    const v = Math.round(
      (2400 + rand() * 5200) * (1 + (Math.abs(move) / (vol * o)) * 1.4)
    );
    // Session opens 09:15 IST.
    const mins = 9 * 60 + 15 + i * stepMinutes;
    const label =
      labelFor?.(i, count) ??
      `${String(Math.floor(mins / 60) % 24).padStart(2, "0")}:${String(mins % 60).padStart(2, "0")}`;
    out.push({ label, o, h, l, c, v });
    price = c;
  }
  // Land the series exactly on `base` so a live last price continues the
  // tape instead of opening a gap against it.
  const shift = base - out[out.length - 1].c;
  return out.map((k) => ({
    ...k,
    o: +(k.o + shift).toFixed(2),
    h: +(k.h + shift).toFixed(2),
    l: +(k.l + shift).toFixed(2),
    c: +(k.c + shift).toFixed(2),
  }));
}

export function generateBook(mid: number, tick = 0.05, levels = 5) {
  const mk = (side: 1 | -1): BookLevel[] =>
    Array.from({ length: levels }, (_, i) => {
      const seed = Math.sin((mid + side * (i + 1)) * 9.71) * 10_000;
      const r = seed - Math.floor(seed);
      return {
        price: +(mid + side * tick * (i + 1)).toFixed(2),
        qty: Math.round(280 + r * 3800),
      };
    });
  return { bids: mk(-1), asks: mk(1) };
}

const STATUS_COLOR: Record<CheckStatus, string> = {
  ok: "var(--success)",
  warn: "var(--warning)",
  risk: "var(--destructive)",
};

/* ------------------------------------------------------------------ */
/* Pre-trade checks                                                     */
/* ------------------------------------------------------------------ */

function walkBook(levels: BookLevel[], qty: number) {
  let left = qty;
  let cost = 0;
  for (const l of levels) {
    const take = Math.min(left, l.qty);
    cost += take * l.price;
    left -= take;
    if (left <= 0) break;
  }
  const filled = qty - left;
  return { avg: filled > 0 ? cost / filled : 0, filled };
}

function buildChecks({
  side,
  type,
  qty,
  limit,
  lastPrice,
  bids,
  asks,
  dayHigh,
  dayLow,
  prevClose,
  upperCircuit,
  lowerCircuit,
}: {
  side: "buy" | "sell";
  type: "limit" | "market";
  qty: number;
  limit: number;
  lastPrice: number;
  bids: BookLevel[];
  asks: BookLevel[];
  dayHigh: number;
  dayLow: number;
  prevClose: number;
  upperCircuit?: number;
  lowerCircuit?: number;
}): PreTradeCheck[] {
  const bestBid = bids[0]?.price ?? lastPrice;
  const bestAsk = asks[0]?.price ?? lastPrice;
  const spread = Math.max(0, bestAsk - bestBid);
  const spreadBps = lastPrice ? (spread / lastPrice) * 10_000 : 0;

  const bidQty = bids.reduce((s, b) => s + b.qty, 0);
  const askQty = asks.reduce((s, a) => s + a.qty, 0);
  const bidShare = bidQty + askQty ? (bidQty / (bidQty + askQty)) * 100 : 50;
  /** Depth stacked behind your intent: bids support a buy, asks cap it. */
  const withYou = side === "buy" ? bidShare : 100 - bidShare;

  // You lift asks to buy and hit bids to sell.
  const fillSide = side === "buy" ? asks : bids;
  const reachable =
    type === "market"
      ? fillSide.slice(0, 3).reduce((s, l) => s + l.qty, 0)
      : fillSide
          .filter((l) => (side === "buy" ? l.price <= limit : l.price >= limit))
          .reduce((s, l) => s + l.qty, 0);
  const coverage = qty ? reachable / qty : 0;

  const touch = side === "buy" ? bestAsk : bestBid;
  const { avg, filled } = walkBook(fillSide, qty);
  const impactBps =
    filled > 0 && touch ? (Math.abs(avg - touch) / touch) * 10_000 : 0;

  const range = Math.max(0.01, dayHigh - dayLow);
  const pos = clamp(((lastPrice - dayLow) / range) * 100, 0, 100);
  // Buying into the day's high (or selling the low) is the expensive end.
  const posAgainstYou = side === "buy" ? pos : 100 - pos;
  const rangePct = prevClose ? (range / prevClose) * 100 : 0;

  const checks: PreTradeCheck[] = [
    {
      key: "spread",
      label: "Spread",
      value: `₹${nf2.format(spread)} · ${spreadBps.toFixed(1)} bps`,
      status: spreadBps < 5 ? "ok" : spreadBps < 15 ? "warn" : "risk",
      note:
        spreadBps < 15
          ? `Paying the spread costs ~₹${nf2.format((spread / 2) * qty)} on this size.`
          : "Wide spread — a limit inside the quote beats crossing it.",
    },
    {
      key: "depth",
      label: type === "market" ? "Depth at touch" : "Liquidity at your price",
      value:
        reachable === 0
          ? "Rests in book"
          : `${nf0.format(reachable)} vs ${nf0.format(qty)} qty`,
      status:
        reachable === 0 ? "warn" : coverage >= 2 ? "ok" : coverage >= 1 ? "warn" : "risk",
      note:
        reachable === 0
          ? `Your limit sits behind the market — it queues at ₹${nf2.format(limit)} instead of filling.`
          : coverage >= 2
            ? ""
            : coverage >= 1
              ? "Barely covered — expect the tail to fill in pieces."
              : `Only ${Math.round(coverage * 100)}% of your size is available; the rest walks the book.`,
      meter: Math.min(100, coverage * 50),
    },
    {
      key: "impact",
      label: "Impact cost",
      value:
        type === "limit" && reachable === 0
          ? "Capped by limit"
          : `${impactBps.toFixed(1)} bps · ₹${nf0.format(Math.abs(avg - touch) * filled)}`,
      status:
        type === "limit" && reachable === 0
          ? "ok"
          : impactBps < 6
            ? "ok"
            : impactBps < 20
              ? "warn"
              : "risk",
      note:
        impactBps < 6
          ? ""
          : `Your size moves the average fill to ₹${nf2.format(avg)} — split it or work the limit.`,
    },
    {
      key: "pressure",
      label: "Book pressure",
      value: `${Math.round(bidShare)}% buyers`,
      status: withYou >= 45 ? "ok" : withYou >= 32 ? "warn" : "risk",
      note:
        withYou >= 45
          ? ""
          : `Resting depth leans ${side === "buy" ? "sell" : "buy"}-side — you're trading into it.`,
      meter: bidShare,
    },
    {
      key: "range",
      label: "Day range position",
      value: `${Math.round(pos)}% of ₹${nf2.format(dayLow)}–${nf2.format(dayHigh)}`,
      status: posAgainstYou > 92 ? "risk" : posAgainstYou > 78 ? "warn" : "ok",
      note:
        posAgainstYou > 78
          ? `${side === "buy" ? "Buying" : "Selling"} at the ${side === "buy" ? "top" : "bottom"} of the day — no room left in your favour.`
          : "",
      meter: pos,
    },
    {
      key: "vol",
      label: "Session volatility",
      value: `${rangePct.toFixed(2)}% range`,
      status: rangePct < 2 ? "ok" : rangePct < 4 ? "warn" : "risk",
      note:
        rangePct < 2
          ? ""
          : "Fast tape — a market order can slip well past the quote you saw.",
    },
  ];

  if (upperCircuit != null && lowerCircuit != null) {
    const toBand =
      Math.min(upperCircuit - lastPrice, lastPrice - lowerCircuit) / lastPrice * 100;
    checks.push({
      key: "circuit",
      label: "Circuit headroom",
      value: `${toBand.toFixed(1)}% to band`,
      status: toBand < 1.5 ? "risk" : toBand < 4 ? "warn" : "ok",
      note:
        toBand < 4
          ? `Bands at ₹${nf2.format(lowerCircuit)}–${nf2.format(upperCircuit)}; trading halts if price locks.`
          : "",
    });
  }

  return checks;
}

/* ------------------------------------------------------------------ */
/* Depth rail                                                           */
/* ------------------------------------------------------------------ */

function DepthRow({
  side,
  level,
  maxQty,
  active,
  onPick,
}: {
  side: "bid" | "ask";
  level: BookLevel;
  maxQty: number;
  active: boolean;
  onPick: (price: number) => void;
}) {
  const barRef = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const pct = Math.round((level.qty / maxQty) * 100);

  /* Bars breathe to each new resting quantity instead of re-drawing. */
  useGSAP(
    () => {
      if (!barRef.current) return;
      if (reduced) {
        gsap.set(barRef.current, { width: `${pct}%` });
        return;
      }
      gsap.to(barRef.current, {
        width: `${pct}%`,
        duration: 0.7,
        ease: "power2.out",
        overwrite: "auto",
      });
    },
    { dependencies: [pct, reduced] }
  );

  return (
    <button
      type="button"
      onClick={() => onPick(level.price)}
      aria-label={`Set order price to ${nf2.format(level.price)} — ${side} depth ${nf0.format(level.qty)}`}
      className={cn(
        "relative flex w-full items-center justify-between gap-2 rounded-md px-1.5 py-1 font-mono type-caption numeric transition-colors duration-150",
        "hover:bg-muted/70 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
        active && "bg-muted"
      )}
    >
      <span
        ref={barRef}
        aria-hidden="true"
        className="absolute inset-y-0.5 left-0 rounded-md"
        style={{
          width: 0,
          background: `linear-gradient(90deg, color-mix(in oklab, var(--${side}) 24%, transparent), color-mix(in oklab, var(--${side}) 5%, transparent))`,
        }}
      />
      <span className={cn("relative", side === "bid" ? "text-bid" : "text-ask")}>
        {nf2.format(level.price)}
      </span>
      <span className="relative text-muted-foreground">{nf0.format(level.qty)}</span>
    </button>
  );
}

/* ------------------------------------------------------------------ */
/* Check row                                                            */
/* ------------------------------------------------------------------ */

function CheckRow({ check }: { check: PreTradeCheck }) {
  const dotRef = React.useRef<HTMLSpanElement>(null);
  const meterRef = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const color = STATUS_COLOR[check.status];

  /* The dot pops when a check flips verdict — the one thing worth noticing. */
  useGSAP(
    () => {
      if (!dotRef.current || reduced) return;
      gsap.fromTo(
        dotRef.current,
        { scale: 0.4 },
        { scale: 1, duration: 0.45, ease: "back.out(3)" }
      );
    },
    { dependencies: [check.status, reduced] }
  );

  useGSAP(
    () => {
      if (!meterRef.current || check.meter == null) return;
      const width = `${clamp(check.meter, 0, 100)}%`;
      if (reduced) {
        gsap.set(meterRef.current, { width });
        return;
      }
      gsap.to(meterRef.current, {
        width,
        duration: 0.5,
        ease: "power3.out",
        overwrite: "auto",
      });
    },
    { dependencies: [check.meter, reduced] }
  );

  return (
    <li
      data-slot="check"
      data-status={check.status}
      className="rounded-xl border border-border/50 bg-background/60 px-2.5 py-2"
    >
      <div className="flex items-baseline justify-between gap-2">
        <span className="flex min-w-0 items-center gap-1.5 type-meta text-muted-foreground">
          <span
            ref={dotRef}
            aria-hidden="true"
            className="size-1.5 shrink-0 rounded-full"
            style={{ background: color }}
          />
          <span>{check.label}</span>
          {/* Status is a colour for sighted users; spell it out for the rest. */}
          <span className="sr-only">
            {check.status === "ok"
              ? "clear"
              : check.status === "warn"
                ? "worth noting"
                : "needs a look"}
          </span>
        </span>
        <span
          className="shrink-0 font-mono type-caption numeric"
          style={{ color: check.status === "ok" ? "var(--foreground)" : color }}
        >
          {check.value}
        </span>
      </div>
      {check.meter != null ? (
        <span
          aria-hidden="true"
          className="mt-1.5 block h-1 overflow-hidden rounded-full bg-muted"
        >
          <span
            ref={meterRef}
            className="block h-full rounded-full"
            style={{ width: 0, background: color }}
          />
        </span>
      ) : null}
      {check.status !== "ok" && check.note ? (
        <p className="mt-1 type-caption text-muted-foreground">{check.note}</p>
      ) : null}
    </li>
  );
}

/* ------------------------------------------------------------------ */
/* Chart trading                                                        */
/* ------------------------------------------------------------------ */

/**
 * Chart-first trading terminal: candles draw in on load and re-stagger on
 * every timeframe switch, a draggable order line sets the limit price
 * straight on the chart, the depth rail breathes with the book, and a
 * pre-trade panel re-scores spread, liquidity, impact, book pressure,
 * range position and volatility against the side you are about to take.
 */
export function ChartTrading({
  symbol,
  exchange = "NSE",
  candles,
  lastPrice,
  bids,
  asks,
  prevClose,
  vwap,
  volume,
  dayHigh,
  dayLow,
  upperCircuit,
  lowerCircuit,
  timeframes = ["1m", "5m", "15m", "1D"],
  timeframe,
  defaultTimeframe,
  onTimeframeChange,
  lotSize = 1,
  maxLots = 50,
  tick = 0.05,
  onLimitPriceChange,
  onPlace,
  className,
  ref,
  ...rest
}: ChartTradingProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);
  const chartWrapRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [tf, setTf] = useControllableState<string>({
    value: timeframe,
    defaultValue: defaultTimeframe ?? timeframes[1] ?? timeframes[0],
    onChange: onTimeframeChange,
  });
  const [side, setSide] = React.useState<"buy" | "sell">("buy");
  const [type, setType] = React.useState<"limit" | "market">("limit");
  const [lots, setLots] = React.useState(2);
  const [stage, setStage] = React.useState<"idle" | "confirm" | "placing" | "placed">("idle");
  const [placed, setPlaced] = React.useState<ChartOrder | null>(null);

  const snap = React.useCallback(
    (p: number) => +(Math.round(p / tick) * tick).toFixed(2),
    [tick]
  );

  const [limit, setLimit] = React.useState(() => snap(lastPrice));
  const [touched, setTouched] = React.useState(false);
  const limitRef = React.useRef(limit);
  limitRef.current = limit;
  const commitLimit = React.useCallback(
    (price: number) => {
      const next = snap(price);
      setTouched(true);
      if (next === limitRef.current) return;
      limitRef.current = next;
      setLimit(next);
      onLimitPriceChange?.(next);
    },
    [snap, onLimitPriceChange]
  );

  /* ---------------- scales ---------------- */

  /* Day range drives the checks; the plot domain follows the candles on
     screen, so a multi-day timeframe still fits inside the pane. */
  const high = dayHigh ?? Math.max(lastPrice, ...candles.map((c) => c.h));
  const low = dayLow ?? Math.min(lastPrice, ...candles.map((c) => c.l));

  const { lo, hi } = React.useMemo(() => {
    const rawHi = Math.max(lastPrice, vwap ?? lastPrice, ...candles.map((c) => c.h));
    const rawLo = Math.min(lastPrice, vwap ?? lastPrice, ...candles.map((c) => c.l));
    const pad = Math.max((rawHi - rawLo) * 0.08, tick * 4);
    return { lo: rawLo - pad, hi: rawHi + pad };
  }, [candles, lastPrice, vwap, tick]);

  const yOf = React.useCallback(
    (p: number) => PAD + (1 - (p - lo) / (hi - lo)) * (PRICE_H - PAD * 2),
    [lo, hi]
  );
  const priceAt = React.useCallback(
    (y: number) => lo + (1 - (y - PAD) / (PRICE_H - PAD * 2)) * (hi - lo),
    [lo, hi]
  );
  const topPct = React.useCallback((p: number) => (yOf(p) / VIEW_H) * 100, [yOf]);

  /* ---------------- derived ---------------- */

  const qty = lots * lotSize;
  const bestBid = bids[0]?.price ?? lastPrice;
  const bestAsk = asks[0]?.price ?? lastPrice;
  const touchPrice = side === "buy" ? bestAsk : bestBid;
  const effPrice = type === "market" ? touchPrice : limit;

  /* Until you move it yourself, the order line tracks the quote you would
     actually trade against — the ask to buy, the bid to sell. */
  React.useEffect(() => {
    if (touched) return;
    const seeded = snap(touchPrice);
    limitRef.current = seeded;
    setLimit(seeded);
  }, [touchPrice, touched, snap]);

  const change = lastPrice - prevClose;
  const changePct = prevClose ? (change / prevClose) * 100 : 0;
  const up = change >= 0;
  const sideColor = side === "buy" ? "var(--market-up)" : "var(--market-down)";
  const sessionVol = React.useMemo(
    () => volume ?? candles.reduce((s, c) => s + c.v, 0),
    [volume, candles]
  );

  const checks = React.useMemo(
    () =>
      buildChecks({
        side,
        type,
        qty,
        limit,
        lastPrice,
        bids,
        asks,
        dayHigh: high,
        dayLow: low,
        prevClose,
        upperCircuit,
        lowerCircuit,
      }),
    [side, type, qty, limit, lastPrice, bids, asks, high, low, prevClose, upperCircuit, lowerCircuit]
  );
  const risks = checks.filter((c) => c.status === "risk").length;
  const warns = checks.filter((c) => c.status === "warn").length;
  const verdict = risks ? "risk" : warns ? "warn" : ("ok" as CheckStatus);

  /* ---------------- candle geometry ---------------- */

  const maxVol = Math.max(1, ...candles.map((c) => c.v));
  const slot = PLOT_W / Math.max(1, candles.length);
  const bodyW = Math.max(1.2, slot * 0.62);

  const candleLayer = React.useMemo(
    () =>
      candles.map((c, i) => {
        const cx = slot * (i + 0.5);
        const rising = c.c >= c.o;
        const color = rising ? "var(--market-up)" : "var(--market-down)";
        const yHigh = yOf(c.h);
        const yLow = yOf(c.l);
        const yTop = yOf(Math.max(c.o, c.c));
        const yBot = yOf(Math.min(c.o, c.c));
        const volH = (c.v / maxVol) * VOL_H;
        return (
          <g key={`${c.label}-${i}`} data-candle="" style={{ opacity: 1 }}>
            <line
              x1={cx}
              x2={cx}
              y1={yHigh}
              y2={yLow}
              stroke={color}
              strokeWidth={1}
              vectorEffect="non-scaling-stroke"
            />
            <rect
              x={cx - bodyW / 2}
              y={yTop}
              width={bodyW}
              height={Math.max(0.8, yBot - yTop)}
              fill={color}
              opacity={rising ? 0.95 : 1}
            />
            <rect
              data-vol=""
              x={cx - bodyW / 2}
              y={VOL_TOP + (VOL_H - volH)}
              width={bodyW}
              height={Math.max(0.5, volH)}
              fill={color}
              opacity={0.3}
            />
          </g>
        );
      }),
    [candles, slot, bodyW, yOf, maxVol]
  );

  /* ---------------- entrance + timeframe switch ---------------- */

  useGSAP(
    () => {
      const bodies = gsap.utils.toArray<SVGGElement>(
        plotRef.current?.querySelectorAll("[data-candle]") ?? []
      );
      if (!bodies.length) return;
      if (reduced) {
        gsap.set(bodies, { opacity: 1, scaleY: 1 });
        gsap.set("[data-vwap]", { scaleX: 1, opacity: 1 });
        return;
      }
      const tl = gsap.timeline();
      tl.fromTo(
        bodies,
        { scaleY: 0.04, opacity: 0, transformOrigin: "50% 50%" },
        {
          scaleY: 1,
          opacity: 1,
          duration: 0.5,
          ease: "power2.out",
          stagger: { each: 0.012, from: "start" },
          clearProps: "transform",
        }
      );
      tl.fromTo(
        "[data-vwap]",
        { scaleX: 0, opacity: 0, transformOrigin: "0% 50%" },
        { scaleX: 1, opacity: 1, duration: 0.9, ease: "power2.inOut" },
        0.15
      );
      tl.fromTo(
        "[data-axis-label]",
        { opacity: 0, x: 6 },
        { opacity: 1, x: 0, duration: 0.4, ease: "power2.out", stagger: 0.05 },
        0.35
      );
    },
    { dependencies: [tf, reduced], scope: plotRef }
  );

  /* Checks re-cascade whenever the side or order type changes the scoring. */
  useGSAP(
    () => {
      if (reduced) return;
      gsap.fromTo(
        "[data-slot='check']",
        { y: 8, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.4, ease: "power3.out", stagger: 0.05 }
      );
    },
    { dependencies: [side, type, reduced], scope: rootRef }
  );

  /* Last price pill flashes with the tick direction. */
  const [flash, setFlash] = React.useState<"up" | "down" | null>(null);
  const prevLast = React.useRef(lastPrice);
  React.useEffect(() => {
    if (reduced || lastPrice === prevLast.current) {
      prevLast.current = lastPrice;
      return;
    }
    setFlash(lastPrice > prevLast.current ? "up" : "down");
    prevLast.current = lastPrice;
    const t = setTimeout(() => setFlash(null), 600);
    return () => clearTimeout(t);
  }, [lastPrice, reduced]);

  /* ---------------- crosshair ---------------- */

  const [hoverIdx, setHoverIdx] = React.useState<number | null>(null);
  const hoverRef = React.useRef<number | null>(null);
  const vLineRef = React.useRef<HTMLDivElement>(null);
  const hLineRef = React.useRef<HTMLDivElement>(null);
  const hLabelRef = React.useRef<HTMLSpanElement>(null);
  const xTo = React.useRef<((v: number) => void) | null>(null);
  const yTo = React.useRef<((v: number) => void) | null>(null);

  useGSAP(() => {
    if (!vLineRef.current || !hLineRef.current) return;
    const cfg = { duration: reduced ? 0 : 0.12, ease: "power3.out" };
    xTo.current = gsap.quickTo(vLineRef.current, "x", cfg);
    yTo.current = gsap.quickTo(hLineRef.current, "y", cfg);
  }, [reduced]);

  const moveCrosshair = (e: React.PointerEvent) => {
    const el = chartWrapRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    // The axis gutter is outside the plot, so normalise x against it.
    const plotW = (rect.width * PLOT_W) / VIEW_W;
    const fx = clamp((e.clientX - rect.left) / plotW, 0, 1);
    const fy = clamp((e.clientY - rect.top) / rect.height, 0, 1);
    const idx = clamp(Math.floor(fx * candles.length), 0, candles.length - 1);
    if (idx !== hoverRef.current) {
      hoverRef.current = idx;
      setHoverIdx(idx);
    }
    const price = clamp(priceAt(fy * VIEW_H), lo, hi);
    xTo.current?.((slot * (idx + 0.5) * rect.width) / VIEW_W);
    yTo.current?.((yOf(price) * rect.height) / VIEW_H);
    if (hLabelRef.current) hLabelRef.current.textContent = nf2.format(price);
  };

  const leaveCrosshair = () => {
    hoverRef.current = null;
    setHoverIdx(null);
  };

  const legend = candles[hoverIdx ?? candles.length - 1];

  /* ---------------- order line drag ---------------- */

  const [dragging, setDragging] = React.useState(false);

  const priceFromClientY = (clientY: number) => {
    const el = chartWrapRef.current;
    if (!el) return limit;
    const rect = el.getBoundingClientRect();
    const fy = clamp((clientY - rect.top) / rect.height, 0, 1);
    return clamp(priceAt(fy * VIEW_H), lo, hi);
  };

  const onHandleDown = (e: React.PointerEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    setDragging(true);
  };
  const onHandleMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    commitLimit(priceFromClientY(e.clientY));
  };
  const onHandleUp = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
    setDragging(false);
  };
  const onHandleKey = (e: React.KeyboardEvent) => {
    const step = e.shiftKey ? tick * 10 : tick;
    if (e.key === "ArrowUp") commitLimit(limit + step);
    else if (e.key === "ArrowDown") commitLimit(limit - step);
    else if (e.key === "PageUp") commitLimit(limit + tick * 20);
    else if (e.key === "PageDown") commitLimit(limit - tick * 20);
    else if (e.key === "Home") commitLimit(lastPrice);
    else return;
    e.preventDefault();
  };

  /* ---------------- fill marker ---------------- */

  const markerRef = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!markerRef.current || !placed) return;
      if (reduced) {
        gsap.set(markerRef.current, { opacity: 1, scale: 1 });
        return;
      }
      gsap.fromTo(
        markerRef.current,
        { opacity: 0, scale: 0.6, x: 10 },
        { opacity: 1, scale: 1, x: 0, duration: 0.5, ease: "back.out(2.4)" }
      );
    },
    { dependencies: [placed, reduced] }
  );

  const place = async () => {
    if (stage === "placed") {
      setStage("idle");
      setPlaced(null);
      return;
    }
    if (verdict === "risk" && stage === "idle") {
      setStage("confirm");
      return;
    }
    setStage("placing");
    const order: ChartOrder = { side, type, qty, price: snap(effPrice) };
    await new Promise((r) => setTimeout(r, 850));
    setPlaced(order);
    setStage("placed");
    onPlace?.(order);
  };

  const maxDepthQty = Math.max(
    1,
    ...bids.map((b) => b.qty),
    ...asks.map((a) => a.qty)
  );

  const axisPrices = [hi, (hi + lo) / 2, lo];

  return (
    <div
      ref={rootRef}
      data-slot="chart-trading"
      style={{ "--side": sideColor } as React.CSSProperties}
      className={cn(
        "w-full max-w-3xl rounded-3xl border border-border/60 bg-card p-4 shadow-md sm:p-5",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className="type-title text-foreground">{symbol}</span>
            <span className="rounded-md border border-border/60 px-1.5 py-0.5 type-caption text-muted-foreground">
              {exchange}
            </span>
          </div>
          <p className="mt-0.5 type-caption text-muted-foreground">
            Vol {volFmt(sessionVol)} · VWAP{" "}
            <span className="font-mono numeric">{vwap ? nf2.format(vwap) : "—"}</span>
          </p>
        </div>
        <div className="text-right">
          <span
            className={cn(
              "block font-mono type-metric numeric transition-colors duration-500",
              flash === "up" && "text-market-up",
              flash === "down" && "text-market-down",
              !flash && "text-foreground"
            )}
          >
            <NumberFlow value={lastPrice} decimals={2} locale="en-IN" />
          </span>
          <span
            className="inline-flex items-center gap-1 type-meta numeric"
            style={{ color: up ? "var(--market-up)" : "var(--market-down)" }}
          >
            <svg
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
              className={cn("size-3", !up && "rotate-180")}
              aria-hidden="true"
            >
              <path d="M12 19V5M5 12l7-7 7 7" />
            </svg>
            {nf2.format(Math.abs(change))} ({changePct.toFixed(2)}%)
          </span>
        </div>
      </div>

      {/* Timeframes */}
      <div
        className="mt-3 flex gap-1 rounded-xl bg-muted p-1"
        role="tablist"
        aria-label="Timeframe"
      >
        {timeframes.map((t) => (
          <button
            key={t}
            role="tab"
            aria-selected={tf === t}
            onClick={() => setTf(t)}
            className={cn(
              "flex-1 rounded-lg px-2 py-1.5 type-meta font-medium transition-colors duration-200",
              tf === t
                ? "bg-background text-foreground shadow-xs"
                : "text-muted-foreground hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            {t}
          </button>
        ))}
      </div>

      {/* Chart + depth */}
      <div className="mt-3 flex flex-col gap-3 lg:flex-row">
        <div ref={plotRef} className="min-w-0 flex-1">
          {/* OHLC legend: pinned, so the tooltip can never overflow the card. */}
          <div className="flex flex-wrap items-baseline gap-x-2.5 gap-y-0.5 px-0.5 font-mono type-caption numeric text-muted-foreground">
            <span className="text-foreground">{legend?.label}</span>
            <span>O {nf2.format(legend?.o ?? 0)}</span>
            <span>H {nf2.format(legend?.h ?? 0)}</span>
            <span>L {nf2.format(legend?.l ?? 0)}</span>
            <span
              style={{
                color:
                  (legend?.c ?? 0) >= (legend?.o ?? 0)
                    ? "var(--market-up)"
                    : "var(--market-down)",
              }}
            >
              C {nf2.format(legend?.c ?? 0)}
            </span>
            <span>Vol {volFmt(legend?.v ?? 0)}</span>
          </div>

          <div
            ref={chartWrapRef}
            className="relative mt-1 h-[240px] select-none sm:h-[280px]"
          >
            <svg
              viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
              preserveAspectRatio="none"
              className="absolute inset-0 size-full"
              aria-hidden="true"
            >
              {/* price grid */}
              {[0, 1, 2, 3].map((i) => (
                <line
                  key={i}
                  x1={0}
                  x2={PLOT_W}
                  y1={PAD + (i / 3) * (PRICE_H - PAD * 2)}
                  y2={PAD + (i / 3) * (PRICE_H - PAD * 2)}
                  stroke="var(--border)"
                  strokeWidth={1}
                  opacity={0.5}
                  vectorEffect="non-scaling-stroke"
                />
              ))}
              <line
                x1={0}
                x2={PLOT_W}
                y1={VOL_TOP + VOL_H}
                y2={VOL_TOP + VOL_H}
                stroke="var(--border)"
                strokeWidth={1}
                opacity={0.6}
                vectorEffect="non-scaling-stroke"
              />
              {vwap != null ? (
                <line
                  data-vwap=""
                  x1={0}
                  x2={PLOT_W}
                  y1={yOf(vwap)}
                  y2={yOf(vwap)}
                  stroke="var(--foreground)"
                  strokeWidth={1}
                  strokeDasharray="1 3"
                  opacity={0.45}
                  vectorEffect="non-scaling-stroke"
                />
              ) : null}
              {candleLayer}
            </svg>

            {/* Price axis labels (HTML, so text never stretches with the svg) */}
            <div
              className="pointer-events-none absolute inset-y-0 right-0"
              style={{ width: `${AXIS_PCT}%` }}
            >
              {axisPrices.map((p) => (
                <span
                  key={p}
                  data-axis-label=""
                  className="absolute left-1 -translate-y-1/2 font-mono type-caption numeric text-muted-foreground"
                  style={{ top: `${topPct(p)}%` }}
                >
                  {nf2.format(p)}
                </span>
              ))}
            </div>

            {/* Last traded price */}
            <div
              className="pointer-events-none absolute inset-x-0 z-10 -translate-y-1/2 transition-[top] duration-500 ease-out motion-reduce:transition-none"
              style={{ top: `${topPct(lastPrice)}%` }}
            >
              <span
                className="absolute left-0 top-0 h-px bg-foreground/25"
                style={{ right: `${AXIS_PCT}%` }}
              />
              <span
                className="absolute right-0 top-0 -translate-y-1/2 rounded px-1 py-px font-mono type-caption font-medium numeric text-background transition-colors duration-500"
                style={{ background: up ? "var(--market-up)" : "var(--market-down)" }}
              >
                {nf2.format(lastPrice)}
              </span>
            </div>

            {/* Order line + drag handle. Sits above the interaction surface so
                the handle keeps the pointer once a drag starts. */}
            <div
              className={cn(
                "pointer-events-none absolute inset-x-0 z-30 -translate-y-1/2",
                dragging
                  ? "transition-none"
                  : "transition-[top] duration-300 ease-out motion-reduce:transition-none"
              )}
              style={{ top: `${topPct(effPrice)}%` }}
            >
              <span
                aria-hidden="true"
                className="absolute left-0 top-0 h-0 border-t border-dashed"
                style={{ right: `${AXIS_PCT}%`, borderColor: sideColor }}
              />
              <div
                role="slider"
                tabIndex={0}
                aria-label={`${side} order price`}
                aria-orientation="vertical"
                aria-valuemin={snap(lo)}
                aria-valuemax={snap(hi)}
                aria-valuenow={snap(effPrice)}
                aria-valuetext={`₹${nf2.format(effPrice)}`}
                aria-disabled={type === "market"}
                onPointerDown={type === "limit" ? onHandleDown : undefined}
                onPointerMove={type === "limit" ? onHandleMove : undefined}
                onPointerUp={onHandleUp}
                onPointerCancel={onHandleUp}
                onKeyDown={type === "limit" ? onHandleKey : undefined}
                className={cn(
                  "pointer-events-auto absolute left-0 top-0 flex -translate-y-1/2 touch-none items-center gap-1 rounded-md px-1.5 py-px font-mono type-caption font-medium numeric text-background shadow-sm",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background",
                  type === "limit" ? "cursor-ns-resize" : "cursor-default opacity-80"
                )}
                style={{ background: sideColor }}
              >
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={2.5}
                  strokeLinecap="round"
                  className="size-2.5"
                  aria-hidden="true"
                >
                  <path d="M8 9l4-4 4 4M8 15l4 4 4-4" />
                </svg>
                {side === "buy" ? "B" : "S"} {nf2.format(effPrice)}
              </div>
            </div>

            {/* Placed-order marker */}
            {placed ? (
              <div
                ref={markerRef}
                /* Above the order line, so its own dashes don't strike the
                   label, and clear of the axis gutter. */
                className="pointer-events-none absolute z-40 -translate-y-1/2"
                style={{
                  top: `${topPct(placed.price)}%`,
                  right: `calc(${AXIS_PCT}% + 6px)`,
                  opacity: 0,
                }}
              >
                <span
                  className="flex items-center gap-1 rounded-md border px-1.5 py-px font-mono type-caption numeric"
                  style={{
                    borderColor: `color-mix(in oklab, var(--placed) 45%, transparent)`,
                    background: `color-mix(in oklab, var(--placed) 14%, var(--card))`,
                    color: "var(--placed)",
                    ["--placed" as string]:
                      placed.side === "buy" ? "var(--market-up)" : "var(--market-down)",
                  }}
                >
                  {placed.side === "buy" ? "▲" : "▼"} {nf0.format(placed.qty)} @{" "}
                  {nf2.format(placed.price)}
                </span>
              </div>
            ) : null}

            {/* Crosshair */}
            <div
              className={cn(
                "pointer-events-none absolute inset-0 z-10 transition-opacity duration-200",
                hoverIdx == null ? "opacity-0" : "opacity-100"
              )}
            >
              <div
                ref={vLineRef}
                className="absolute inset-y-0 left-0 w-px border-l border-dashed border-foreground/30"
              />
              <div ref={hLineRef} className="absolute inset-x-0 top-0">
                <span
                  className="absolute left-0 top-0 h-0 border-t border-dashed border-foreground/30"
                  style={{ right: `${AXIS_PCT}%` }}
                />
                <span
                  ref={hLabelRef}
                  className="absolute right-0 top-0 -translate-y-1/2 rounded bg-foreground px-1 py-px font-mono type-caption numeric text-background"
                />
              </div>
            </div>

            {/* Interaction surface: hover reads the tape, click sets the limit. */}
            <div
              className="absolute inset-y-0 left-0 z-20 cursor-crosshair"
              style={{ right: `${AXIS_PCT}%` }}
              onPointerMove={moveCrosshair}
              onPointerLeave={leaveCrosshair}
              onPointerDown={(e) => {
                if (type !== "limit") return;
                commitLimit(priceFromClientY(e.clientY));
              }}
            />
          </div>
        </div>

        {/* Depth rail */}
        <div
          data-slot="depth-rail"
          className="shrink-0 rounded-2xl border border-border/50 bg-background/50 p-2 lg:w-44"
        >
          <div className="flex items-baseline justify-between px-1 type-overline text-muted-foreground">
            <span>Depth</span>
            <span>Qty</span>
          </div>
          <div className="mt-1 flex flex-col-reverse">
            {asks.map((a, i) => (
              <DepthRow
                key={`a-${i}`}
                side="ask"
                level={a}
                maxQty={maxDepthQty}
                active={snap(effPrice) === a.price}
                onPick={commitLimit}
              />
            ))}
          </div>
          <div className="my-1 flex items-center justify-between rounded-md bg-muted/60 px-1.5 py-1 type-caption text-muted-foreground">
            <span>Spread</span>
            <span className="font-mono numeric text-foreground">
              {nf2.format(Math.max(0, bestAsk - bestBid))}
            </span>
          </div>
          <div className="flex flex-col">
            {bids.map((b, i) => (
              <DepthRow
                key={`b-${i}`}
                side="bid"
                level={b}
                maxQty={maxDepthQty}
                active={snap(effPrice) === b.price}
                onPick={commitLimit}
              />
            ))}
          </div>
          <p className="mt-1.5 px-1 type-caption text-muted-foreground">
            Tap a level to move your order there.
          </p>
        </div>
      </div>

      {/* Pre-trade checks */}
      <div className="mt-4 rounded-2xl border border-border/50 bg-muted/30 p-3">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="type-overline text-muted-foreground">Before you trade</p>
          <span
            className="inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 type-caption font-medium"
            style={{
              color: STATUS_COLOR[verdict],
              borderColor: `color-mix(in oklab, ${STATUS_COLOR[verdict]} 35%, transparent)`,
              background: `color-mix(in oklab, ${STATUS_COLOR[verdict]} 10%, transparent)`,
            }}
          >
            <span
              aria-hidden="true"
              className="size-1.5 rounded-full"
              style={{ background: STATUS_COLOR[verdict] }}
            />
            {verdict === "ok"
              ? "Clear to place"
              : verdict === "warn"
                ? `${warns} to note`
                : `${risks} need${risks > 1 ? "" : "s"} a look`}
          </span>
        </div>
        <ul className="mt-2 grid gap-2 sm:grid-cols-2">
          {checks.map((c) => (
            <CheckRow key={c.key} check={c} />
          ))}
        </ul>
      </div>

      {/* Ticket */}
      <div className="mt-4 flex flex-wrap items-end gap-2">
        <div
          className="flex gap-1 rounded-xl bg-muted p-1"
          role="tablist"
          aria-label="Order side"
        >
          {(["buy", "sell"] as const).map((s) => (
            <button
              key={s}
              role="tab"
              aria-selected={side === s}
              onClick={() => {
                setSide(s);
                setStage("idle");
              }}
              className={cn(
                "rounded-lg px-3 py-1.5 type-meta font-semibold uppercase tracking-wide transition-colors duration-200",
                side === s ? "text-background shadow-sm" : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
              style={
                side === s
                  ? { background: s === "buy" ? "var(--market-up)" : "var(--market-down)" }
                  : undefined
              }
            >
              {s}
            </button>
          ))}
        </div>

        <div
          className="flex gap-1 rounded-xl bg-muted p-1"
          role="tablist"
          aria-label="Order type"
        >
          {(["limit", "market"] as const).map((t) => (
            <button
              key={t}
              role="tab"
              aria-selected={type === t}
              onClick={() => {
                setType(t);
                setStage("idle");
              }}
              className={cn(
                "rounded-lg px-3 py-1.5 type-meta font-medium capitalize transition-colors duration-200",
                type === t
                  ? "bg-background text-foreground shadow-xs"
                  : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              {t}
            </button>
          ))}
        </div>

        <label className="flex flex-col gap-1 type-caption text-muted-foreground">
          Lots ({lotSize}/lot)
          <div className="flex h-9 items-stretch gap-1 rounded-xl border border-input bg-background p-1 shadow-xs">
            <button
              type="button"
              aria-label="Decrease lots"
              onClick={() => setLots((l) => Math.max(1, l - 1))}
              className="flex aspect-square items-center justify-center rounded-lg text-foreground transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" className="size-3.5" aria-hidden="true"><path d="M5 12h14" /></svg>
            </button>
            <span className="flex min-w-8 items-center justify-center font-mono type-meta numeric text-foreground">
              {lots}
            </span>
            <button
              type="button"
              aria-label="Increase lots"
              onClick={() => setLots((l) => Math.min(maxLots, l + 1))}
              className="flex aspect-square items-center justify-center rounded-lg text-foreground transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" className="size-3.5" aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg>
            </button>
          </div>
        </label>

        <div className="ml-auto flex items-end gap-2">
          <p className="pb-1 text-right type-caption text-muted-foreground">
            {nf0.format(qty)} qty ·{" "}
            <span className="font-mono numeric text-foreground">
              ₹{nf2.format(effPrice)}
            </span>
            <br />≈ ₹{nf0.format(qty * effPrice)}
          </p>
          <Button
            className="text-background shadow-sm hover:opacity-90"
            style={{ background: sideColor }}
            loading={stage === "placing"}
            disabled={stage === "placing"}
            onClick={place}
          >
            {stage === "placed"
              ? "Place another"
              : stage === "confirm"
                ? "Place anyway"
                : `${side === "buy" ? "Buy" : "Sell"} ${type === "market" ? "at market" : nf2.format(limit)}`}
          </Button>
        </div>
      </div>

      {/* Confirm / placed strip */}
      {stage === "confirm" ? (
        <div
          className="mt-3 flex flex-wrap items-center justify-between gap-2 rounded-xl border px-3 py-2 type-meta"
          style={{
            borderColor: "color-mix(in oklab, var(--destructive) 35%, transparent)",
            background: "color-mix(in oklab, var(--destructive) 8%, transparent)",
          }}
          role="alert"
        >
          <span className="text-foreground">
            {risks} check{risks > 1 ? "s" : ""} flagged this order —{" "}
            {checks.find((c) => c.status === "risk")?.label.toLowerCase()} first.
          </span>
          <Button size="sm" variant="outline" onClick={() => setStage("idle")}>
            Let me adjust
          </Button>
        </div>
      ) : null}

      {stage === "placed" && placed ? (
        <p className="mt-3 rounded-xl border border-border/60 bg-background/60 px-3 py-2 type-meta text-muted-foreground">
          <span
            className="font-semibold uppercase"
            style={{ color: sideColor }}
          >
            {placed.side}
          </span>{" "}
          {nf0.format(placed.qty)} {symbol} · {placed.type} @ ₹
          {nf2.format(placed.price)} — working on the chart at that level.
        </p>
      ) : null}

      <p className="mt-3 type-caption text-muted-foreground">
        Drag the {side === "buy" ? "buy" : "sell"} line (or click the chart) to set
        your price · arrow keys nudge by a tick, shift for ten · simulated feed
      </p>
    </div>
  );
}

registry/default/fintech/penny-drop.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type PennyDropStatus = "idle" | "verifying" | "verified" | "mismatch" | "failed";

export interface PennyDropResult {
  /** Beneficiary name the bank returned for the account. */
  beneficiaryName: string;
  bank: string;
  /** Name-match score 0–1 vs the expected name, if one was supplied. */
  matchScore: number;
  status: Extract<PennyDropStatus, "verified" | "mismatch" | "failed">;
}

export interface PennyDropProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  /** Name you expect the account to belong to; drives the match read. */
  expectedName?: string;
  /** Resolve the verification. Defaults to a deterministic demo. */
  onVerify?: (input: { account: string; ifsc: string }) => Promise<PennyDropResult>;
  ref?: React.Ref<HTMLDivElement>;
}

/** IFSC → bank name, first four letters. A tiny demo lookup. */
const IFSC_BANKS: Record<string, string> = {
  HDFC: "HDFC Bank",
  ICIC: "ICICI Bank",
  SBIN: "State Bank of India",
  UTIB: "Axis Bank",
  KKBK: "Kotak Mahindra Bank",
  YESB: "Yes Bank",
  PUNB: "Punjab National Bank",
};

function bankFromIfsc(ifsc: string): string | null {
  return IFSC_BANKS[ifsc.slice(0, 4).toUpperCase()] ?? null;
}

/** Simple token-overlap name similarity, 0–1. */
function nameScore(a: string, b: string): number {
  const norm = (s: string) =>
    s.toLowerCase().replace(/[^a-z\s]/g, "").split(/\s+/).filter(Boolean);
  const x = norm(a);
  const y = new Set(norm(b));
  if (!x.length) return 0;
  const hit = x.filter((t) => y.has(t)).length;
  return hit / x.length;
}

const IFSC_RE = /^[A-Z]{4}0[A-Z0-9]{6}$/;

const DEMO_NAME = "ASHA VERMA";

/* ------------------------------------------------------------------ */
/* Stages                                                               */
/* ------------------------------------------------------------------ */

const STAGES = [
  { key: "init", label: "Initiating a ₹1 deposit", done: "₹1 credited to the account" },
  { key: "fetch", label: "Reading the account holder name", done: "Name returned by the bank" },
  { key: "match", label: "Matching the name", done: "Name match complete" },
] as const;

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

/**
 * Penny-drop bank verification: a ₹1 deposit confirms an account exists and
 * returns the registered holder name. The stages reveal in sequence, the
 * beneficiary name is fetched, and the match against the expected name is
 * scored — verified, or flagged as a mismatch.
 */
export function PennyDrop({
  expectedName,
  onVerify,
  className,
  ref,
  ...rest
}: PennyDropProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const stagesRef = React.useRef<HTMLOListElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [account, setAccount] = React.useState("");
  const [ifsc, setIfsc] = React.useState("");
  const [status, setStatus] = React.useState<PennyDropStatus>("idle");
  const [reached, setReached] = React.useState(-1); // last completed stage index
  const [result, setResult] = React.useState<PennyDropResult | null>(null);

  const bank = bankFromIfsc(ifsc);
  const accountValid = account.length >= 9 && account.length <= 18;
  const ifscValid = IFSC_RE.test(ifsc);
  const canVerify = accountValid && ifscValid && status === "idle";

  const defaultVerify = React.useCallback(
    async (): Promise<PennyDropResult> => {
      const beneficiaryName = DEMO_NAME;
      const score = expectedName ? nameScore(expectedName, beneficiaryName) : 1;
      return {
        beneficiaryName,
        bank: bank ?? "Your bank",
        matchScore: score,
        status: score >= 0.5 ? "verified" : "mismatch",
      };
    },
    [expectedName, bank]
  );

  const verify = async () => {
    if (!canVerify) return;
    setStatus("verifying");
    setReached(-1);
    setResult(null);
    const step = reduced ? 200 : 900;
    for (let i = 0; i < STAGES.length; i++) {
      await new Promise((r) => setTimeout(r, step));
      setReached(i);
    }
    try {
      const res = await (onVerify ?? defaultVerify)({ account, ifsc });
      await new Promise((r) => setTimeout(r, reduced ? 100 : 350));
      setResult(res);
      setStatus(res.status);
    } catch {
      setStatus("failed");
    }
  };

  const reset = () => {
    setStatus("idle");
    setReached(-1);
    setResult(null);
  };

  // Stage rows cascade in when verification starts.
  useGSAP(
    () => {
      if (status !== "verifying" && status !== "verified" && status !== "mismatch") return;
      const rows = gsap.utils.toArray<HTMLElement>(
        stagesRef.current?.querySelectorAll("[data-stage]") ?? []
      );
      if (!rows.length || reduced) return;
      gsap.fromTo(
        rows,
        { x: 8, opacity: 0 },
        { x: 0, opacity: 1, duration: 0.35, ease: "power3.out", stagger: 0.08, overwrite: true }
      );
    },
    { dependencies: [status], scope: rootRef }
  );

  const field =
    "h-10 w-full rounded-xl border border-input bg-background px-3 text-sm text-foreground shadow-xs transition-[border-color,box-shadow] duration-200 placeholder:text-muted-foreground/60 hover:border-ring/30 focus-visible:outline-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/25";

  return (
    <div
      ref={rootRef}
      data-slot="penny-drop"
      className={cn(
        "w-full max-w-sm rounded-3xl border border-border/60 bg-card p-5 shadow-md",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2">
        <h3 className="type-title text-foreground">Verify bank account</h3>
        <span className="flex items-center gap-1.5 rounded-full bg-muted/60 px-2 py-0.5 type-caption font-medium text-muted-foreground ring-1 ring-inset ring-border/50">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true"><path d="M12 2 4 6v6c0 5 3.5 8 8 10 4.5-2 8-5 8-10V6z" /></svg>
          Penny drop
        </span>
      </div>

      {status === "idle" ? (
        <form
          className="mt-4 flex flex-col gap-3"
          onSubmit={(e) => {
            e.preventDefault();
            void verify();
          }}
        >
          <label className="flex flex-col gap-1.5 type-meta font-medium text-muted-foreground">
            Account number
            <input
              inputMode="numeric"
              aria-label="Account number"
              placeholder="0000 0000 0000"
              value={account}
              onChange={(e) => setAccount(e.target.value.replace(/\D/g, "").slice(0, 18))}
              className={cn(field, "font-mono numeric")}
            />
          </label>
          <label className="flex flex-col gap-1.5 type-meta font-medium text-muted-foreground">
            <span className="flex items-center justify-between">
              IFSC
              {bank ? (
                <span className="font-normal text-foreground">{bank}</span>
              ) : ifsc.length >= 4 && !bankFromIfsc(ifsc) ? (
                <span className="font-normal text-muted-foreground/70">Unknown bank</span>
              ) : null}
            </span>
            <input
              autoCapitalize="characters"
              aria-label="IFSC code"
              placeholder="HDFC0001234"
              value={ifsc}
              onChange={(e) => setIfsc(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 11))}
              className={cn(field, "font-mono uppercase tracking-wide", ifsc.length === 11 && !ifscValid && "border-destructive/60")}
            />
          </label>
          <button
            type="submit"
            disabled={!canVerify}
            className={cn(
              "mt-1 flex h-11 items-center justify-center gap-2 rounded-xl bg-primary text-sm font-semibold text-primary-foreground",
              "shadow-[inset_0_1px_0_0_hsl(0_0%_100%/0.12),var(--elevation-sm)]",
              "transition-[transform,box-shadow,opacity] duration-200 ease-out-expo hover:-translate-y-px active:translate-y-0",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ring-offset-background",
              "disabled:pointer-events-none disabled:opacity-50 motion-reduce:hover:translate-y-0"
            )}
          >
            Verify account
          </button>
          <p className="type-caption leading-4 text-muted-foreground">
            We deposit ₹1 to confirm the account is real and read back the registered
            name. Demo only.
          </p>
        </form>
      ) : (
        <div className="mt-4">
          {/* Account summary */}
          <div className="flex items-center justify-between rounded-xl border border-border/60 bg-background/60 px-3 py-2 text-xs shadow-xs">
            <span className="font-mono numeric text-foreground">
              ••{account.slice(-4)}
            </span>
            <span className="text-muted-foreground">{bank ?? ifsc}</span>
          </div>

          {/* Stages */}
          <ol ref={stagesRef} className="mt-3 flex flex-col">
            {STAGES.map((s, i) => {
              const done = reached >= i;
              const isCurrent = status === "verifying" && i === reached + 1;
              return (
                <li key={s.key} data-stage className="relative flex gap-3 pb-3 last:pb-0">
                  {i < STAGES.length - 1 ? (
                    <span
                      aria-hidden="true"
                      className="absolute left-[9px] top-5 h-[calc(100%-1.25rem)] w-0.5 rounded-full transition-colors duration-500"
                      style={{ background: done ? "color-mix(in oklab, var(--success) 45%, transparent)" : "var(--border)" }}
                    />
                  ) : null}
                  <span
                    className={cn(
                      "mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full border-2 transition-colors duration-300",
                      done
                        ? "border-success bg-success text-white"
                        : isCurrent
                          ? "border-info bg-background"
                          : "border-border bg-background"
                    )}
                  >
                    {done ? (
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true"><path d="M5 13l4 4L19 7" /></svg>
                    ) : isCurrent ? (
                      <span className="relative flex size-2">
                        <span className="absolute inline-flex size-full animate-ping rounded-full bg-info opacity-60" />
                        <span className="relative inline-flex size-2 rounded-full bg-info" />
                      </span>
                    ) : null}
                  </span>
                  <div className="min-w-0 flex-1 pt-0.5">
                    <p className={cn("text-xs font-medium", done || isCurrent ? "text-foreground" : "text-muted-foreground")}>
                      {done ? s.done : s.label}
                      {isCurrent ? "…" : ""}
                    </p>
                  </div>
                </li>
              );
            })}
          </ol>

          {/* Result */}
          {result ? (
            <div
              className={cn(
                "mt-2 rounded-2xl border p-3.5 shadow-xs transition-colors duration-300",
                result.status === "verified"
                  ? "border-success/40 bg-success/[0.06]"
                  : "border-warning/40 bg-warning/[0.06]"
              )}
            >
              <div className="flex items-center justify-between gap-2">
                <span className="type-overline text-muted-foreground">
                  Account holder
                </span>
                <span
                  className={cn(
                    "flex items-center gap-1 rounded-full px-2 py-0.5 type-caption font-semibold ring-1 ring-inset",
                    result.status === "verified"
                      ? "bg-success/12 text-success ring-success/25"
                      : "bg-warning/12 text-warning ring-warning/25"
                  )}
                >
                  {result.status === "verified" ? (
                    <>
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true"><path d="M5 13l4 4L19 7" /></svg>
                      Verified
                    </>
                  ) : (
                    "Name mismatch"
                  )}
                </span>
              </div>
              <p className="mt-1 text-base font-semibold text-foreground">{result.beneficiaryName}</p>
              <p className="type-meta text-muted-foreground">
                {result.bank} · ••{account.slice(-4)}
                {expectedName ? ` · ${Math.round(result.matchScore * 100)}% match to “${expectedName}”` : ""}
              </p>
              {result.status === "mismatch" ? (
                <p className="mt-1.5 type-meta leading-4 text-warning">
                  The registered name differs from what you entered. Confirm before sending money.
                </p>
              ) : null}
              <button
                type="button"
                onClick={reset}
                className="mt-3 type-meta font-medium text-muted-foreground underline-offset-2 transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                Verify another account
              </button>
            </div>
          ) : status === "failed" ? (
            <div className="mt-2 rounded-2xl border border-destructive/40 bg-destructive/[0.06] p-3.5 text-xs text-destructive shadow-xs">
              <p className="font-medium">Verification failed</p>
              <p className="mt-0.5 type-meta leading-4 text-muted-foreground">
                The ₹1 deposit could not be placed. Check the account and IFSC, then retry.
              </p>
              <button type="button" onClick={reset} className="mt-2 type-meta font-medium text-foreground underline-offset-2 hover:underline">
                Try again
              </button>
            </div>
          ) : null}
        </div>
      )}
    </div>
  );
}

