      >
        <path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z" />
        <circle cx="12" cy="12" r="2.5" />
      </svg>
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        className={cn(
          "absolute size-4 transition-opacity duration-150",
          visible ? "opacity-100" : "opacity-0"
        )}
      >
        <path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z" />
        <circle cx="12" cy="12" r="2.5" />
        <path d="M4 20 20 4" />
      </svg>
    </button>
  );
}

function StrengthMeter({ password }: { password: string }) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const wasVisible = React.useRef(false);
  const reduced = useReducedMotion();
  const visible = password.length > 0;
  const level = passwordLevel(password);

  // Mounts via height-auto after the first keystroke.
  useGSAP(
    () => {
      const el = rootRef.current;
      if (!el) return;
      if (visible && !wasVisible.current) {
        wasVisible.current = true;
        if (reduced) {
          gsap.set(el, { height: "auto", opacity: 1 });
          return;
        }
        gsap.fromTo(
          el,
          { height: 0, opacity: 0 },
          {
            height: el.scrollHeight,
            opacity: 1,
            duration: 0.45,
            ease: "power3.inOut",
            onComplete: () => gsap.set(el, { height: "auto" }),
          }
        );
      }
    },
    { dependencies: [visible, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="strength-meter"
      className="overflow-hidden"
      style={{ height: 0 }}
      aria-hidden={!visible}
    >
      <div className="flex items-center gap-3 pt-2">
        <div className="flex flex-1 gap-1">
          {[1, 2, 3, 4].map((seg) => (
            <span
              key={seg}
              className="h-1 flex-1 overflow-hidden rounded-full bg-muted"
            >
              <span
                className={cn(
                  "block h-full w-full origin-left rounded-full",
                  "transition-[transform,background-color] duration-200 ease-out",
                  seg <= level ? "scale-x-100" : "scale-x-0",
                  levelColor(level)
                )}
                style={{ transitionDelay: `${(seg - 1) * 60}ms` }}
              />
            </span>
          ))}
        </div>
        <span
          key={LEVEL_LABELS[level]}
          className="w-12 animate-[duku-fade-in_0.2s_ease-out] text-right text-xs text-muted-foreground"
          aria-live="polite"
        >
          {LEVEL_LABELS[level]}
        </span>
      </div>
    </div>
  );
}

export function SignupCard({
  onSubmit,
  onOAuth,
  title = "Create your account",
  loginHref,
  className,
  ref,
  ...rest
}: SignupCardProps) {
  const cardRef = React.useRef<HTMLDivElement>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const prevBodyHeight = React.useRef(0);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => cardRef.current as HTMLDivElement);

  const [values, setValues] = React.useState({
    name: "",
    email: "",
    password: "",
    terms: false,
  });
  const [errors, setErrors] = React.useState<
    Partial<Record<FieldName, string>>
  >({});
  const erred = React.useRef(new Set<FieldName>());
  const [showPw, setShowPw] = React.useState(false);
  const [loading, setLoading] = React.useState(false);
  const [success, setSuccess] = React.useState(false);
  const [done, setDone] = React.useState(false);
  const [submitError, setSubmitError] = React.useState<string | null>(null);

  const nameRef = React.useRef<HTMLInputElement>(null);
  const emailRef = React.useRef<HTMLInputElement>(null);
  const passwordRef = React.useRef<HTMLInputElement>(null);
  const termsRef = React.useRef<HTMLButtonElement>(null);

  const validate = React.useCallback(
    (field: FieldName, v = values): string | undefined => {
      switch (field) {
        case "name":
          return v.name.trim().length >= 2 ? undefined : MESSAGES.name;
        case "email":
          return EMAIL_RE.test(v.email) ? undefined : MESSAGES.email;
        case "password":
          return v.password.length >= 8 ? undefined : MESSAGES.password;
        case "terms":
          return v.terms ? undefined : MESSAGES.terms;
      }
    },
    [values]
  );

  // "Reward early, punish late": validate on blur first; once a field has
  // erred, re-validate on every change.
  const handleBlur = (field: FieldName) => {
    const msg = validate(field);
    if (msg) erred.current.add(field);
    setErrors((e) => ({ ...e, [field]: msg }));
  };
  const handleChange = (field: FieldName, next: Partial<typeof values>) => {
    const merged = { ...values, ...next };
    setValues(merged);
    if (erred.current.has(field)) {
      setErrors((e) => ({ ...e, [field]: validate(field, merged) }));
    }
  };

  // Card entrance: pop-in + children cascade.
  useGSAP(
    () => {
      const card = cardRef.current;
      if (!card) return;
      const items = gsap.utils.toArray<HTMLElement>(
        card.querySelectorAll('[data-slot="cascade-item"]')
      );
      if (reduced) {
        gsap.set(card, { opacity: 1, scale: 1 });
        gsap.set(items, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        card,
        { opacity: 0, scale: 0.96 },
        { opacity: 1, scale: 1, duration: 0.25, ease: "power3.out" }
      );
      gsap.fromTo(
        items,
        { y: 12, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.35,
          ease: "power2.out",
          stagger: 0.05,
          delay: 0.05,
        }
      );
    },
    { scope: cardRef }
  );

  // Crossfade to the success panel with a height-auto morph.
  useGSAP(
    () => {
      const body = bodyRef.current;
      if (!body || !done) return;
      const panel = body.querySelector<HTMLElement>(
        '[data-slot="success-panel"]'
      );
      if (!panel) return;
      if (reduced) {
        gsap.set(body, { height: "auto" });
        gsap.set(panel, { opacity: 1 });
        return;
      }
      gsap.fromTo(
        body,
        { height: prevBodyHeight.current },
        {
          height: body.scrollHeight,
          duration: 0.45,
          ease: "power3.inOut",
          onComplete: () => gsap.set(body, { height: "auto" }),
        }
      );
      gsap.fromTo(panel, { opacity: 0 }, { opacity: 1, duration: 0.3 });
      const circle = panel.querySelector<HTMLElement>('[data-slot="circle"]');
      const check = panel.querySelector<SVGPathElement>('[data-slot="check"]');
      const headline = panel.querySelector<HTMLElement>(
        '[data-slot="headline"]'
      );
      const subtext = panel.querySelector<HTMLElement>('[data-slot="subtext"]');
      if (circle) {
        gsap.fromTo(
          circle,
          { scale: 0 },
          { scale: 1, duration: 0.4, ease: "back.out(1.7)", delay: 0.1 }
        );
      }
      if (check) {
        gsap.fromTo(
          check,
          { strokeDashoffset: 1 },
          { strokeDashoffset: 0, duration: 0.3, ease: "power2.out", delay: 0.45 }
        );
      }
      if (headline) {
        gsap.fromTo(
          headline,
          { y: 12, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.35, ease: "power2.out", delay: 0.25 }
        );
      }
      if (subtext) {
        gsap.fromTo(
          subtext,
          { y: 12, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.35, ease: "power2.out", delay: 0.4 }
        );
      }
    },
    { dependencies: [done, reduced], scope: cardRef }
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const fields: FieldName[] = ["name", "email", "password", "terms"];
    const nextErrors: Partial<Record<FieldName, string>> = {};
    for (const f of fields) {
      const msg = validate(f);
      if (msg) {
        nextErrors[f] = msg;
        erred.current.add(f);
      }
    }
    if (Object.keys(nextErrors).length > 0) {
      setErrors(nextErrors);
      // Focus the first invalid field; its Field shake plays on error.
      const refs: Record<FieldName, React.RefObject<HTMLElement | null>> = {
        name: nameRef,
        email: emailRef,
        password: passwordRef,
        terms: termsRef,
      };
      for (const f of fields) {
        if (nextErrors[f]) {
          refs[f].current?.focus();
          break;
        }
      }
      return;
    }
    setErrors({});
    setSubmitError(null);
    setLoading(true);
    try {
      await onSubmit({
        name: values.name.trim(),
        email: values.email,
        password: values.password,
      });
      setLoading(false);
      setSuccess(true);
    } catch (err) {
      setLoading(false);
      setSubmitError(
        err instanceof Error ? err.message : "Something went wrong. Try again."
      );
    }
  };

  const emailValid = values.email !== "" && EMAIL_RE.test(values.email);

  return (
    <div
      ref={cardRef}
      data-slot="signup-card"
      className={cn(
        "w-full max-w-md rounded-3xl border border-border/60 bg-card p-8 opacity-0 shadow-md",
        className
      )}
      {...rest}
    >
      <div ref={bodyRef} className="overflow-hidden">
        {done ? (
          <div
            data-slot="success-panel"
            className="flex flex-col items-center gap-2 py-6 text-center opacity-0"
          >
            <span
              data-slot="circle"
              className="flex size-12 items-center justify-center rounded-full bg-emerald-600/10"
            >
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
                className="size-6 text-emerald-600 dark:text-emerald-400"
                aria-hidden="true"
              >
                <path
                  data-slot="check"
                  d="M5 13l4 4L19 7"
                  pathLength={1}
                  strokeDasharray={1}
                  strokeDashoffset={1}
                />
              </svg>
            </span>
            <h2
              data-slot="headline"
              className="mt-2 text-xl font-semibold text-foreground opacity-0"
            >
              Check your inbox
            </h2>
            <p
              data-slot="subtext"
              className="text-sm text-muted-foreground opacity-0"
            >
              We sent a confirmation link to {values.email}.
            </p>
          </div>
        ) : (
          <form noValidate onSubmit={handleSubmit} className="flex flex-col">
            <div data-slot="cascade-item">
              <h2 className="text-xl font-semibold text-foreground">{title}</h2>
              <p className="mt-1 text-sm text-muted-foreground">
                Start your 14-day free trial. No credit card required.
              </p>
            </div>

            {submitError != null ? (
              <div className="mt-4">
                <Alert variant="destructive" title={submitError} />
              </div>
            ) : null}

            {onOAuth ? (
              <div data-slot="cascade-item" className="mt-6">
                <div className="grid grid-cols-2 gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => onOAuth("google")}
                  >
                    <GoogleMark />
                    Google
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => onOAuth("github")}
                  >
                    <GitHubMark />
                    GitHub
                  </Button>
                </div>
                <div className="mt-4 flex items-center gap-3">
                  <span className="flex-1 border-t border-border" />
                  <span className="text-xs text-muted-foreground">or</span>
                  <span className="flex-1 border-t border-border" />
                </div>
              </div>
            ) : null}

            <div data-slot="cascade-item" className="mt-5">
              <Field
                label="Name"
                state={errors.name ? "error" : null}
                message={errors.name}
              >
                <Input
                  ref={nameRef}
                  name="name"
                  autoComplete="name"
                  value={values.name}
                  invalid={!!errors.name}
                  onChange={(e) =>
                    handleChange("name", { name: e.currentTarget.value })
                  }
                  onBlur={() => handleBlur("name")}
                  disabled={loading || success}
                />
              </Field>
            </div>

            <div data-slot="cascade-item" className="mt-4">
              <Field
                label="Email"
                state={errors.email ? "error" : null}
                message={errors.email}
              >
                <Input
                  ref={emailRef}
                  type="email"
                  name="email"
                  autoComplete="email"
                  value={values.email}
                  invalid={!!errors.email}
                  valid={emailValid}
                  onChange={(e) =>
                    handleChange("email", { email: e.currentTarget.value })
                  }
                  onBlur={() => handleBlur("email")}
                  disabled={loading || success}
                />
              </Field>
            </div>

            <div data-slot="cascade-item" className="mt-4">
              <Field
                label="Password"
                state={errors.password ? "error" : null}
                message={errors.password}
              >
                <Input
                  ref={passwordRef}
                  type={showPw ? "text" : "password"}
                  name="new-password"
                  autoComplete="new-password"
                  value={values.password}
                  invalid={!!errors.password}
                  suffixEl={
                    <EyeToggle
                      visible={showPw}
                      onToggle={() => setShowPw((v) => !v)}
                    />
                  }
                  onChange={(e) =>
                    handleChange("password", {
                      password: e.currentTarget.value,
                    })
                  }
                  onBlur={() => handleBlur("password")}
                  disabled={loading || success}
                />
              </Field>
              <StrengthMeter password={values.password} />
            </div>

            <div data-slot="cascade-item" className="mt-5">
              <Field
                state={errors.terms ? "error" : null}
                message={errors.terms}
              >
                <label className="flex items-start gap-2.5 text-sm text-muted-foreground">
                  <Checkbox
                    ref={termsRef}
                    checked={values.terms}
                    onCheckedChange={(c) =>
                      handleChange("terms", { terms: c === true })
                    }
                    disabled={loading || success}
                    className="mt-0.5"
                  />
                  <span>
                    I agree to the{" "}
                    <a
                      href="#terms"
                      className="font-medium text-foreground underline-offset-4 hover:underline"
                    >
                      Terms
                    </a>{" "}
                    and{" "}
                    <a
                      href="#privacy"
                      className="font-medium text-foreground underline-offset-4 hover:underline"
                    >
                      Privacy Policy
                    </a>
                    .
                  </span>
                </label>
              </Field>
            </div>

            <div data-slot="cascade-item" className="mt-6">
              <Button
                type="submit"
                size="lg"
                className="w-full"
                loading={loading}
                success={success}
                onSuccessEnd={() => {
                  prevBodyHeight.current = bodyRef.current?.offsetHeight ?? 0;
                  setSuccess(false);
                  setDone(true);
                }}
              >
                Create account
              </Button>
            </div>

            {loginHref ? (
              <p
                data-slot="cascade-item"
                className="mt-5 text-center text-sm text-muted-foreground"
              >
                Already have an account?{" "}
                <a
                  href={loginHref}
                  className="font-medium text-foreground underline-offset-4 hover:underline"
                >
                  Sign in
                </a>
              </p>
            ) : null}
          </form>
        )}
      </div>
    </div>
  );
}

registry/default/blocks/login-card.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Input } from "@/registry/default/ui/input";
import { Field } from "@/registry/default/ui/field";
import { Checkbox } from "@/registry/default/ui/checkbox";
import { Alert } from "@/registry/default/ui/alert";

export interface LoginCardProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit" | "title"> {
  onSubmit: (data: {
    email: string;
    password: string;
    remember: boolean;
  }) => Promise<void>;
  title?: string;
  forgotHref?: string;
  signupHref?: string;
  ref?: React.Ref<HTMLDivElement>;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function LoginCard({
  onSubmit,
  title = "Welcome back",
  forgotHref = "#forgot",
  signupHref,
  className,
  ref,
  ...rest
}: LoginCardProps) {
  const cardRef = React.useRef<HTMLDivElement>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const prevBodyHeight = React.useRef(0);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => cardRef.current as HTMLDivElement);

  const [values, setValues] = React.useState({
    email: "",
    password: "",
    remember: false,
  });
  const [errors, setErrors] = React.useState<{
    email?: string;
    password?: string;
  }>({});
  const erred = React.useRef(new Set<"email" | "password">());
  const [loading, setLoading] = React.useState(false);
  const [success, setSuccess] = React.useState(false);
  const [done, setDone] = React.useState(false);
  const [submitError, setSubmitError] = React.useState<string | null>(null);

  const emailRef = React.useRef<HTMLInputElement>(null);
  const passwordRef = React.useRef<HTMLInputElement>(null);

  const validate = (
    field: "email" | "password",
    v = values
  ): string | undefined => {
    if (field === "email")
      return EMAIL_RE.test(v.email)
        ? undefined
        : "Enter a valid email address";
    return v.password.length > 0 ? undefined : "Enter your password";
  };

  const handleBlur = (field: "email" | "password") => {
    const msg = validate(field);
    if (msg) erred.current.add(field);
    setErrors((e) => ({ ...e, [field]: msg }));
  };
  const handleChange = (
    field: "email" | "password",
    next: Partial<typeof values>
  ) => {
    const merged = { ...values, ...next };
    setValues(merged);
    if (erred.current.has(field)) {
      setErrors((e) => ({ ...e, [field]: validate(field, merged) }));
    }
  };

  useGSAP(
    () => {
      const card = cardRef.current;
      if (!card) return;
      const items = gsap.utils.toArray<HTMLElement>(
        card.querySelectorAll('[data-slot="cascade-item"]')
      );
      if (reduced) {
        gsap.set(card, { opacity: 1, scale: 1 });
        gsap.set(items, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        card,
        { opacity: 0, scale: 0.96 },
        { opacity: 1, scale: 1, duration: 0.25, ease: "power3.out" }
      );
      gsap.fromTo(
        items,
        { y: 12, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.35,
          ease: "power2.out",
          stagger: 0.05,
          delay: 0.05,
        }
      );
    },
    { scope: cardRef }
  );

  useGSAP(
    () => {
      const body = bodyRef.current;
      if (!body || !done) return;
      const panel = body.querySelector<HTMLElement>(
        '[data-slot="success-panel"]'
      );
      if (!panel) return;
      if (reduced) {
        gsap.set(body, { height: "auto" });
        gsap.set(panel, { opacity: 1 });
        return;
      }
      gsap.fromTo(
        body,
        { height: prevBodyHeight.current },
        {
          height: body.scrollHeight,
          duration: 0.45,
          ease: "power3.inOut",
          onComplete: () => gsap.set(body, { height: "auto" }),
        }
      );
      gsap.fromTo(panel, { opacity: 0 }, { opacity: 1, duration: 0.3 });
      const circle = panel.querySelector<HTMLElement>('[data-slot="circle"]');
      const check = panel.querySelector<SVGPathElement>('[data-slot="check"]');
      const headline = panel.querySelector<HTMLElement>(
        '[data-slot="headline"]'
      );
      if (circle)
        gsap.fromTo(
          circle,
          { scale: 0 },
          { scale: 1, duration: 0.4, ease: "back.out(1.7)", delay: 0.1 }
        );
      if (check)
        gsap.fromTo(
          check,
          { strokeDashoffset: 1 },
          { strokeDashoffset: 0, duration: 0.3, ease: "power2.out", delay: 0.45 }
        );
      if (headline)
        gsap.fromTo(
          headline,
          { y: 12, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.35, ease: "power2.out", delay: 0.25 }
        );
    },
    { dependencies: [done, reduced], scope: cardRef }
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const nextErrors: typeof errors = {};
    for (const f of ["email", "password"] as const) {
      const msg = validate(f);
      if (msg) {
        nextErrors[f] = msg;
        erred.current.add(f);
      }
    }
    if (Object.keys(nextErrors).length > 0) {
      setErrors(nextErrors);
      if (nextErrors.email) emailRef.current?.focus();
      else passwordRef.current?.focus();
      return;
    }
    setErrors({});
    setSubmitError(null);
    setLoading(true);
    try {
      await onSubmit(values);
      setLoading(false);
      setSuccess(true);
    } catch (err) {
      setLoading(false);
      setSubmitError(
        err instanceof Error ? err.message : "Invalid email or password."
      );
    }
  };

  return (
    <div
      ref={cardRef}
      data-slot="login-card"
      className={cn(
        "w-full max-w-md rounded-3xl border border-border/60 bg-card p-8 opacity-0 shadow-md",
        className
      )}
      {...rest}
    >
      <div ref={bodyRef} className="overflow-hidden">
        {done ? (
          <div
            data-slot="success-panel"
            className="flex flex-col items-center gap-2 py-6 text-center opacity-0"
          >
            <span
              data-slot="circle"
              className="flex size-12 items-center justify-center rounded-full bg-emerald-600/10"
            >
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
                className="size-6 text-emerald-600 dark:text-emerald-400"
                aria-hidden="true"
              >
                <path
                  data-slot="check"
                  d="M5 13l4 4L19 7"
                  pathLength={1}
                  strokeDasharray={1}
                  strokeDashoffset={1}
                />
              </svg>
            </span>
            <h2
              data-slot="headline"
              className="mt-2 text-xl font-semibold text-foreground opacity-0"
            >
              You&apos;re in
            </h2>
          </div>
        ) : (
          <form noValidate onSubmit={handleSubmit} className="flex flex-col">
            <div data-slot="cascade-item">
              <h2 className="text-xl font-semibold text-foreground">{title}</h2>
              <p className="mt-1 text-sm text-muted-foreground">
                Sign in to continue to your account.
              </p>
            </div>

            {submitError != null ? (
              <div className="mt-4">
                <Alert variant="destructive" title={submitError} />
              </div>
            ) : null}

            <div data-slot="cascade-item" className="mt-6">
              <Field
                label="Email"
                state={errors.email ? "error" : null}
                message={errors.email}
              >
                <Input
                  ref={emailRef}
                  type="email"
                  name="email"
                  autoComplete="email"
                  value={values.email}
                  invalid={!!errors.email}
                  onChange={(e) =>
                    handleChange("email", { email: e.currentTarget.value })
                  }
                  onBlur={() => handleBlur("email")}
                  disabled={loading || success}
                />
              </Field>
            </div>

            <div data-slot="cascade-item" className="mt-4">
              <Field
                label={
                  <span className="flex w-full items-center justify-between">
                    Password
                    <a
                      href={forgotHref}
                      tabIndex={0}
                      className="text-xs font-medium text-muted-foreground underline-offset-4 hover:text-foreground hover:underline"
                    >
                      Forgot password?
                    </a>
                  </span>
                }
                state={errors.password ? "error" : null}
                message={errors.password}
              >
                <Input
                  ref={passwordRef}
                  type="password"
                  name="current-password"
                  autoComplete="current-password"
                  value={values.password}
                  invalid={!!errors.password}
                  onChange={(e) =>
                    handleChange("password", {
                      password: e.currentTarget.value,
                    })
                  }
                  onBlur={() => handleBlur("password")}
                  disabled={loading || success}
                />
              </Field>
            </div>

            <div data-slot="cascade-item" className="mt-4">
              <label className="flex items-center gap-2.5 text-sm text-muted-foreground">
                <Checkbox
                  checked={values.remember}
                  onCheckedChange={(c) =>
                    setValues((v) => ({ ...v, remember: c === true }))
                  }
                  disabled={loading || success}
                />
                Remember me
              </label>
            </div>

            <div data-slot="cascade-item" className="mt-6">
              <Button
                type="submit"
                size="lg"
                className="w-full"
                loading={loading}
                success={success}
                onSuccessEnd={() => {
                  prevBodyHeight.current = bodyRef.current?.offsetHeight ?? 0;
                  setSuccess(false);
                  setDone(true);
                }}
              >
                Sign in
              </Button>
            </div>

            {signupHref ? (
              <p
                data-slot="cascade-item"
                className="mt-5 text-center text-sm text-muted-foreground"
              >
                No account?{" "}
                <a
                  href={signupHref}
                  className="font-medium text-foreground underline-offset-4 hover:underline"
                >
                  Create one
                </a>
              </p>
            ) : null}
          </form>
        )}
      </div>
    </div>
  );
}

registry/default/blocks/pricing-card.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { motion, AnimatePresence } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Badge } from "@/registry/default/ui/badge";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

export interface PricingCardProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  plan: string;
  description?: string;
  monthlyPrice: number;
  yearlyPrice: number;
  currencyPrefix?: string;
  features: string[];
  featured?: boolean;
  ctaLabel?: string;
  savingsLabel?: string;
  onSelect?: (billing: "monthly" | "yearly") => void;
  ref?: React.Ref<HTMLDivElement>;
}

function FeatureCheck({ delay }: { delay: number }) {
  const reduced = useReducedMotion();
  const [drawn, setDrawn] = React.useState(false);
  React.useEffect(() => {
    if (reduced) {
      setDrawn(true);
      return;
    }
    const t = setTimeout(() => setDrawn(true), delay);
    return () => clearTimeout(t);
  }, [delay, reduced]);
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      className="mt-0.5 size-3.5 shrink-0 text-emerald-600 dark:text-emerald-400"
      aria-hidden="true"
    >
      <path
        d="M5 13l4 4L19 7"
        pathLength={1}
        strokeDasharray={1}
        strokeDashoffset={drawn ? 0 : 1}
        className="transition-[stroke-dashoffset] duration-300 ease-out"
      />
    </svg>
  );
}

export function PricingCard({
  plan,
  description,
  monthlyPrice,
  yearlyPrice,
  currencyPrefix = "$",
  features,
  featured = false,
  ctaLabel = "Get started",
  savingsLabel = "Save 20%",
  onSelect,
  className,
  ref,
  ...rest
}: PricingCardProps) {
  const [billing, setBilling] = React.useState<"monthly" | "yearly">(
    "monthly"
  );
  const rootRef = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const springStandard = {
    type: "spring",
    stiffness: 380,
    damping: 32,
  } as const;

  // Feature rows cascade on mount.
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(
        root.querySelectorAll('[data-slot="feature-row"]')
      );
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 12, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.35,
          ease: "power2.out",
          stagger: 0.05,
          delay: 0.1,
        }
      );
    },
    { scope: rootRef }
  );

  const price = billing === "monthly" ? monthlyPrice : yearlyPrice;

  return (
    <div
      ref={rootRef}
      data-slot="pricing-card"
      className={cn(
        "relative w-full max-w-sm rounded-3xl border bg-card p-6",
        featured
          ? "border-primary/30 shadow-lg ring-1 ring-primary/10"
          : "border-border/60 shadow-md",
        className
      )}
      {...rest}
    >
      {featured ? (
        <>
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 top-0 h-28 overflow-hidden rounded-t-3xl"
          >
            <div className="absolute inset-x-0 top-0 h-full bg-[radial-gradient(70%_100%_at_50%_0%,hsl(var(--elevation-hue)/0.06),transparent)] dark:bg-[radial-gradient(70%_100%_at_50%_0%,hsl(0_0%_100%/0.06),transparent)]" />
          </div>
          <div className="absolute -top-3 left-1/2 -translate-x-1/2">
            <Badge>Most popular</Badge>
          </div>
        </>
      ) : null}

      <div className="flex items-center justify-between gap-2">
        <h3 className="type-title text-foreground">{plan}</h3>
        {/* billing toggle: two-option sliding pill */}
        <div
          data-slot="billing-toggle"
          role="tablist"
          aria-label="Billing period"
          className="relative isolate inline-flex items-center rounded-lg bg-muted p-0.5"
        >
          {(["monthly", "yearly"] as const).map((b) => (
            <button
              key={b}
              role="tab"
              aria-selected={billing === b}
              onClick={() => {
                setBilling(b);
                onSelect?.(b);
              }}
              className={cn(
                "relative z-10 rounded-md px-2.5 py-1 text-xs font-medium capitalize",
                "transition-colors duration-200",
                billing === b
                  ? "text-foreground"
                  : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              {billing === b ? (
                <motion.span
                  layoutId={`billing-pill-${plan}`}
                  aria-hidden="true"
                  className="absolute inset-0 -z-10 rounded-md bg-background shadow-sm"
                  transition={reduced ? { duration: 0 } : springStandard}
                />
              ) : null}
              {b}
            </button>
          ))}
        </div>
      </div>

      {description ? (
        <p className="mt-2 text-sm text-muted-foreground">{description}</p>
      ) : null}

      <div className="mt-5 flex items-baseline gap-2">
        <span className="text-4xl font-semibold tracking-tight text-foreground">
          <NumberFlow value={price} prefix={currencyPrefix} />
        </span>
        <span className="text-sm text-muted-foreground">
          /{billing === "monthly" ? "mo" : "yr"}
        </span>
        <AnimatePresence>
          {billing === "yearly" ? (
            <motion.span
              initial={
                reduced ? { opacity: 0 } : { opacity: 0, scale: 0.96 }
              }
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.96 }}
              transition={
                reduced ? { duration: 0 } : { duration: 0.25, ease: "easeOut" }
              }
            >
              <Badge variant="success">{savingsLabel}</Badge>
            </motion.span>
          ) : null}
        </AnimatePresence>
      </div>

      <ul className="mt-6 flex flex-col gap-2.5">
        {features.map((feature, i) => (
          <li
            key={feature}
            data-slot="feature-row"
            className="flex items-start gap-2.5 text-sm text-foreground opacity-0"
          >
            <FeatureCheck delay={150 + i * 50} />
            {feature}
          </li>
        ))}
      </ul>

      <div className="mt-6">
        <Button
          className="w-full"
          variant={featured ? "default" : "outline"}
          onClick={() => onSelect?.(billing)}
        >
          {ctaLabel}
        </Button>
      </div>
    </div>
  );
}

registry/default/blocks/newsletter-input:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { FieldMessage } from "@/registry/default/ui/field-message";

export interface NewsletterInputProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  onSubmit: (email: string) => Promise<void> | void;
  placeholder?: string;
  buttonLabel?: string;
  ref?: React.Ref<HTMLDivElement>;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type Phase = "idle" | "loading" | "success";

export function NewsletterInput({
  onSubmit,
  placeholder = "you@example.com",
  buttonLabel = "Subscribe",
  className,
  ref,
  ...rest
}: NewsletterInputProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const controlRef = React.useRef<HTMLDivElement>(null);
  const successRef = React.useRef<HTMLSpanElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const widthBeforeMorph = React.useRef(0);
  const [email, setEmail] = React.useState("");
  const [phase, setPhase] = React.useState<Phase>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [drawn, setDrawn] = React.useState(false);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const shake = React.useCallback(() => {
    if (reduced || !controlRef.current) return;
    gsap.fromTo(
      controlRef.current,
      { x: 0 },
      {
        x: 0,
        duration: 0.4,
        ease: "none",
        keyframes: { x: [-6, 6, -4, 4, -2, 0] },
      }
    );
  }, [reduced]);

  // Morph the control into the success pill and back.
  useGSAP(
    () => {
      const control = controlRef.current;
      const success = successRef.current;
      if (!control || !success) return;
      if (phase === "success") {
        const target = success.offsetWidth;
        setDrawn(false);
        const t = setTimeout(() => setDrawn(true), 200);
        if (reduced) {
          gsap.set(control, { width: target });
          return () => clearTimeout(t);
        }
        gsap.fromTo(
          control,
          { width: widthBeforeMorph.current },
          { width: target, duration: 0.35, ease: "power3.inOut" }
        );
        return () => clearTimeout(t);
      }
      if (phase === "idle" && widthBeforeMorph.current > 0) {
        if (reduced) {
          gsap.set(control, { width: "auto" });
          return;
        }
        gsap.fromTo(
          control,
          { width: control.offsetWidth },
          {
            width: widthBeforeMorph.current,
            duration: 0.35,
            ease: "power3.inOut",
            onComplete: () => gsap.set(control, { width: "auto" }),
          }
        );
      }
    },
    { dependencies: [phase, reduced], scope: rootRef }
  );

  const submit = async () => {
    if (phase !== "idle") return;
    if (!EMAIL_RE.test(email)) {
      setError("Enter a valid email address");
      shake();
      return;
    }
    setError(null);
    widthBeforeMorph.current = controlRef.current?.offsetWidth ?? 0;
    setPhase("loading");
    try {
      await onSubmit(email);
      setPhase("success");
      setTimeout(() => {
        setEmail("");
        setPhase("idle");
      }, 3000);
    } catch {
      setPhase("idle");
      setError("Something went wrong. Try again.");
      shake();
    }
  };

  return (
    <div
      ref={rootRef}
      data-slot="newsletter-input"
      className={cn("inline-flex flex-col", className)}
      {...rest}
    >
      <div
        ref={controlRef}
        data-slot="control"
        className={cn(
          "relative flex h-12 items-center overflow-hidden rounded-full border border-input bg-background pl-5 pr-1.5 shadow-sm",
          "transition-[border-color,box-shadow] duration-300",
          "hover:border-ring/30",
          "focus-within:border-ring focus-within:shadow-md focus-within:ring-2 focus-within:ring-ring/25",
          error != null && "border-destructive focus-within:ring-destructive/25",
          phase === "success" && "justify-center border-emerald-600 px-0"
        )}
      >
        <div
          className={cn(
            "flex w-full items-center gap-2 transition-opacity duration-200",
            phase === "success" && "pointer-events-none opacity-0"
          )}
        >
          <input
            ref={inputRef}
            type="email"
            inputMode="email"
            autoComplete="email"
            aria-label="Email address"
            aria-invalid={error != null || undefined}
            placeholder={placeholder}
            value={email}
            disabled={phase !== "idle"}
            onChange={(e) => {
              setEmail(e.currentTarget.value);
              if (error != null && EMAIL_RE.test(e.currentTarget.value)) {
                setError(null);
              }
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") void submit();
            }}
            className="w-52 flex-1 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground"
          />
          <Button
            type="button"
            size="sm"
            className="rounded-full"
            loading={phase === "loading"}
            onClick={() => void submit()}
          >
            {buttonLabel}
          </Button>
        </div>
        <span
          ref={successRef}
          data-slot="success-pill"
          aria-live="polite"
          className={cn(
            "absolute inline-flex items-center gap-2 whitespace-nowrap px-5 text-sm font-medium",
            "text-emerald-600 transition-opacity duration-200 dark:text-emerald-400",
            phase === "success" ? "opacity-100" : "pointer-events-none opacity-0"
          )}
        >
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2.5}
            strokeLinecap="round"
            strokeLinejoin="round"
            className="size-4"
            aria-hidden="true"
          >
            <path
              d="M5 13l4 4L19 7"
              pathLength={1}
              strokeDasharray={1}
              strokeDashoffset={drawn ? 0 : 1}
              className="transition-[stroke-dashoffset] duration-300 ease-out"
            />
          </svg>
          You&apos;re in
        </span>
      </div>
      <FieldMessage state={error != null ? "error" : null}>
        {error}
      </FieldMessage>
    </div>
  );
}
